// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

// --- OpenZeppelin imports ---
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

// --- Aave v3 minimal interfaces ---
interface IPool {
    function supply(address asset, uint256 amount, address onBehalfOf, uint16 referralCode) external;
    function withdraw(address asset, uint256 amount, address to) external returns (uint256);

    /// @notice FIX P1.L1: Aave V3 ReserveData getter — used as direct on-chain
    ///         fallback in the hybrid rate pattern. Returns currentLiquidityRate
    ///         in ray (1e27) at index 2 of the tuple. `currentLiquidityRate`
    ///         updates only on pool activity (supply/borrow/withdraw/repay),
    ///         so it can be stale on low-activity days; the keeper-pushed cache
    ///         is preferred when fresh, with this as the fallback.
    function getReserveData(address asset) external view returns (
        uint256 configuration,
        uint128 liquidityIndex,
        uint128 currentLiquidityRate,
        uint128 variableBorrowIndex,
        uint128 currentVariableBorrowRate,
        uint128 currentStableBorrowRate,
        uint40 lastUpdateTimestamp,
        uint16 id,
        address aTokenAddress,
        address stableDebtTokenAddress,
        address variableDebtTokenAddress,
        address interestRateStrategyAddress,
        uint128 accruedToTreasury,
        uint128 unbacked,
        uint128 isolationModeTotalDebt
    );
}

interface IAToken {
    function UNDERLYING_ASSET_ADDRESS() external view returns (address);
    function balanceOf(address user) external view returns (uint256);
}

// --- Optional minimal Rate Provider interface (can wrap Aave Data Provider) ---
interface IAaveRateProvider {
    // Returns current liquidity rate for `asset` in ray (1e27)
    function getLiquidityRateRay(address asset) external view returns (uint256);

    /// @dev FIX P1.L1: rate + timestamp for staleness check (hybrid pattern).
    function getLiquidityRateRayWithTs(address asset) external view returns (uint256 rateRay, uint64 lastUpdateTs);
}

// --- ILendingAdapter interface ---
interface ILendingAdapter {
    function name() external view returns (string memory);
    function underlying() external view returns (address);

    function totalAssets() external view returns (uint256);
    function withdrawableAssets() external view returns (uint256);

    function deposit(uint256 assets) external;
    function withdraw(uint256 assets, address receiver) external returns (uint256 withdrawn);

    function currentAPYBps() external view returns (uint16);
    function incentiveAPYBps() external view returns (uint16);
    function harvestableProfit() external view returns (uint256);
    event HarvestCallFailed(bytes4 indexed operation, bytes reason);

    function harvest(address receiver) external returns (uint256 realized);

    function maxCapacity() external view returns (uint256);
    function externalMarketTVL() external view returns (uint256);
}

// --- Adapter Contract ---
interface IAaveRewardsController {
    function claimRewardsToSelf(address[] calldata assets, uint256 amount, address reward)
        external returns (uint256);
}

interface ISwapHelper {
    function canSwap(address token) external view returns (bool);
    function previewExpectedOut(address token, uint256 amountIn) external view returns (uint256);
    function swapToUSDC(address token, uint256 amountIn, address receiver) external returns (uint256);
}

contract AaveV3USDCAdapter is ILendingAdapter, AccessControl, ReentrancyGuard, Initializable {
    using SafeERC20 for IERC20;

    // --- Roles ---
    bytes32 public constant VAULT_ROLE = keccak256("VAULT_ROLE");

    // --- V10 Storage (was immutable in V9.x; logically immutable post-initialize) ---
    // V10 BREAKING CHANGE: storage variables enable byte-identical multi-chain deployment.
    // Set ONCE in initialize() and never reassigned (no setter functions exist).
    address public asset; // USDC token
    IPool public pool; // Aave v3 Pool
    address public aToken; // aUSDC v3
    address public vault; // Authorized Strategy Vault

    // --- Configurable Storage ---
    uint256 public maxCap; // Deposit cap (0 = unlimited)
    uint16 public incentiveBps; // Optional incentive APY in bps
    uint16 public apyOverrideBps; // Optional APY override (bps), 0 = disabled
    address public rateProvider; // Optional external on-chain rate provider

    /// @notice FIX P1.L1: max staleness for keeper-pushed cache. Past this
    ///         threshold, the adapter falls back to direct on-chain read from
    ///         Pool.getReserveData. Default 24h (rateProvider keeper expected
    ///         to poke every 1-6h). Range enforced [1h, 30d] in setter.
    /// @dev OPERATIONAL_AUDIT: heartbeat USDC/USD su Arbitrum e' 86400s (24h).
    ///      Default 90_000s = heartbeat + 1h buffer per evitare cache-miss su edge timing
    ///      (keeper push leggermente in ritardo non triggera fallback inutile a direct read).
    ///      Range [3600s, 30 days] enforced in setMaxRateStalenessSec.
    uint32 public maxRateStalenessSec = 90_000;

    // --- Events ---
    event Supplied(uint256 assets);
    event Withdrawn(uint256 assets, address receiver);
    event MaxCapUpdated(uint256 newCap);
    event IncentiveBpsUpdated(uint16 newBps);
    event APYOverrideUpdated(uint16 newBps);
    event RateProviderUpdated(address provider);
    // ─── Reward pipeline v1 (M1 canSwap gate + M2 graceful) ──────────────
    address public rewardsController;
    address public swapHelper;
    address[] private _rewardTokens;
    mapping(address => bool) public isRewardWhitelisted;
    uint16 public incentiveHaircutBps = 7500; // default 75% retain 25%
    uint16 public realizedRewardAPRBps; // off-chain measured realized reward APR (bps)

    event RewardConfigInitialized(address rewardsController, address swapHelper, address[] tokens);
    event RewardTokenAdded(address indexed token);
    event RewardTokenRemoved(address indexed token);
    event IncentiveHaircutUpdated(uint16 bps);
    event RealizedRewardAPRUpdated(uint16 bps);
    event SwapHelperUpdated(address helper);
    event Harvested(address indexed receiver, uint256 totalRealized);
    /// @dev SLITHER-FIX-1: emit per-token claimed amount captured from claimRewardsToSelf return.
    event RewardClaimed(address indexed token, uint256 amount);

    event MaxRateStalenessUpdated(uint32 secs);

    // --- Modifiers ---
    modifier onlyVault() {
        require(msg.sender == vault, "not vault");
        _;
    }

    // --- V10 Constructor (locked) ---

    // --- V10 Initialization (one-shot, gated by OZ initializer modifier) ---
    /// @notice One-shot initialization called atomically by AdapterFactory.
    /// @dev Reverts on second call via OZ initializer modifier.
    function initialize(
        address asset_,
        address pool_,
        address aToken_,
        address admin_,
        address vault_,
        uint256 maxCap_
    ) external initializer {
        require(
            asset_ != address(0) && pool_ != address(0) && aToken_ != address(0)
                && admin_ != address(0) && vault_ != address(0),
            "zero"
        );
        require(IAToken(aToken_).UNDERLYING_ASSET_ADDRESS() == asset_, "aToken/asset mismatch");
        asset = asset_;
        pool = IPool(pool_);
        aToken = aToken_;
        vault = vault_;
        maxCap = maxCap_;

        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
        _grantRole(VAULT_ROLE, vault_);
    }

    // --- ILendingAdapter: Metadata ---
    function name() external pure override returns (string memory) {
        return "AaveV3_USDC_Adapter_Arbitrum";
    }

    /// @notice Returns false because Aave uses PULL deposit pattern
    /// @dev Adapter calls transferFrom() to pull USDC from Strategy during deposit()
    function isPushMode() external pure returns (bool) {
        return false;
    }

    function underlying() external view override returns (address) {
        return asset;
    }

    // --- ILendingAdapter: Accounting ---
    function idleAssetBalance() public view returns (uint256) {
        return IERC20(asset).balanceOf(address(this));
    }

    function investedAssets() public view returns (uint256) {
        // aToken is 1:1 with USDC, grows with interest
        return IAToken(aToken).balanceOf(address(this));
    }

    function totalAssets() public view override returns (uint256) {
        return investedAssets() + idleAssetBalance();
    }

    function withdrawableAssets() public view override returns (uint256) {
        // Conservative: min(aToken balance, pool liquidity).
        // In Aave V3, USDC is held by the aToken contract (not the Pool proxy),
        // so liquidity must be checked against aToken's underlying balance.
        uint256 bal = IAToken(aToken).balanceOf(address(this));
        uint256 liq = IERC20(asset).balanceOf(aToken);
        return bal < liq ? bal : liq;
    }

    // --- ILendingAdapter: Lifecycle ---
    function deposit(uint256 assets) external override nonReentrant onlyVault {
        require(assets > 0, "ZERO_ASSETS");
        if (maxCap > 0) require(totalAssets() + assets <= maxCap, "CAP");

        // Gas: cache `asset`/`pool` locally -- both are set once in
        // initialize() with no setter, so they cannot change mid-call. Avoids
        // repeated warm SLOADs across the transferFrom/approve/supply/revoke
        // sequence below.
        address asset_ = asset;
        IPool pool_ = pool;

        IERC20(asset_).safeTransferFrom(msg.sender, address(this), assets);

        // Just-in-time approval for exact amount (security best practice)
        IERC20(asset_).forceApprove(address(pool_), assets);

        pool_.supply(asset_, assets, address(this), 0);

        // Revoke approval after operation
        IERC20(asset_).forceApprove(address(pool_), 0);

        emit Supplied(assets);
    }

    // Receiver forced: always sends to vault, ignores 'receiver' param
    function withdraw(
        uint256 assets,
        address /*receiver*/
    )
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 withdrawn)
    {
        require(assets > 0, "ZERO_ASSETS");
        uint256 want = assets;
        uint256 maxOut = withdrawableAssets();
        if (want > maxOut) want = maxOut;

        address vault_ = vault; // read once, used twice below
        withdrawn = pool.withdraw(asset, want, vault_); // Always to vault
        emit Withdrawn(withdrawn, vault_);
    }

    // --- ILendingAdapter: Yield ---
    /// @notice Returns current supply APY in bps.
    /// @dev FIX P1.L1 (quant audit verified, hybrid pattern A2):
    ///      1) Admin override (apyOverrideBps) — escape hatch
    ///      2) Keeper-pushed cache + staleness check (preferred when fresh)
    ///      3) Direct on-chain read from Pool.getReserveData (fallback)
    ///      4) Return 0 (no source available)
    ///
    ///      The keeper cache is PRIMARY because Aave V3 `currentLiquidityRate`
    ///      updates only on pool activity (lazy). Direct on-chain read is no
    ///      stricter-fresher: it returns the same value last written by activity.
    ///      Hybrid gives best of both: fresh keeper snapshot when available,
    ///      direct fallback when cache stale.
    function currentAPYBps() external view override returns (uint16) {
        // (1) Admin override
        if (apyOverrideBps != 0) return apyOverrideBps;

        // (2) Keeper-pushed cache with staleness check
        if (rateProvider != address(0)) {
            try IAaveRateProvider(rateProvider).getLiquidityRateRayWithTs(asset)
                returns (uint256 rateRay, uint64 ts)
            {
                if (ts > 0 && rateRay > 0) {
                    uint256 age = block.timestamp - uint256(ts);
                    if (age <= uint256(maxRateStalenessSec)) {
                        return _rateRayToBps(rateRay);
                    }
                }
                // Cache stale or empty — fall through to direct read.
            } catch {
                // Provider doesn't support new ABI — fall through.
            }
        }

        // (3) Direct on-chain read fallback
        try IPool(pool).getReserveData(asset) returns (
            uint256, uint128, uint128 currentLiquidityRate,
            uint128, uint128, uint128, uint40, uint16,
            address, address, address, address,
            uint128, uint128, uint128
        ) {
            if (currentLiquidityRate > 0) {
                return _rateRayToBps(uint256(currentLiquidityRate));
            }
        } catch {}

        // (4) No source available
        return 0;
    }

    /// @dev Convert ray (1e27) APR to bps (1e4). bps = rateRay / 1e23.
    function _rateRayToBps(uint256 rateRay) internal pure returns (uint16) {
        uint256 bps = rateRay / 1e23;
        if (bps > type(uint16).max) return type(uint16).max;
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint16(bps);
    }

    function incentiveAPYBps() external view override returns (uint16) {
        // realized takes priority over legacy incentiveBps; haircut applied to retain 25% of realized.
        uint256 raw = realizedRewardAPRBps != 0 ? realizedRewardAPRBps : incentiveBps;
        if (raw == 0) return 0;
        uint256 retain = 10_000 - uint256(incentiveHaircutBps);
        uint256 result = (raw * retain) / 10_000;
        if (result > type(uint16).max) return type(uint16).max;
        return uint16(result);
    }

    function setIncentiveBps(uint16 bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        incentiveBps = bps;
        emit IncentiveBpsUpdated(bps);
    }

    function setAPYOverrideBps(uint16 bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        apyOverrideBps = bps;
        emit APYOverrideUpdated(bps);
    }

    function setRateProvider(address provider) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(provider != address(0), "zero address");
        rateProvider = provider;
        emit RateProviderUpdated(provider);
    }

    /// @notice FIX P1.L1: configure max age for keeper-pushed rate cache.
    ///         Past this threshold, fall back to direct on-chain read.
    /// @param secs new staleness threshold in seconds (1h-30d range)
    function setMaxRateStalenessSec(uint32 secs) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(secs >= 3_600 && secs <= 30 days, "staleness-range");
        maxRateStalenessSec = secs;
        emit MaxRateStalenessUpdated(secs);
    }

    function harvestableProfit() external view override returns (uint256) {
        if (swapHelper == address(0)) return 0;
        uint256 n = _rewardTokens.length;
        if (n == 0) return 0;
        uint256 sum = 0;
        ISwapHelper sh = ISwapHelper(swapHelper);
        for (uint256 i = 0; i < n; ) {
            address tok = _rewardTokens[i];
            uint256 bal = IERC20(tok).balanceOf(address(this));
            if (bal == 0) { unchecked { ++i; } continue; }
            // M1 pre-flight: skip tokens whose oracle is stale to avoid LINK burn
            if (!sh.canSwap(tok)) { unchecked { ++i; } continue; }
            try sh.previewExpectedOut(tok, bal) returns (uint256 q) { sum += q; } catch {}
            unchecked { ++i; }
        }
        return sum;
    }

    function harvest(address receiver) external override nonReentrant returns (uint256 realized) {
        require(msg.sender == vault, "not vault");
        uint256 n = _rewardTokens.length;
        if (n == 0) return 0;
        address rc = rewardsController;
        address sh = swapHelper;
        address[] memory emptyAssets = new address[](0);
        uint256 total = 0;
        for (uint256 i = 0; i < n; ) {
            address tok = _rewardTokens[i];
            // (1) try claim — never propagate revert (M2 graceful)
            // SLITHER-FIX-1: capture claimed amount + emit per-token event for observability.
            if (rc != address(0)) {
                try IAaveRewardsController(rc).claimRewardsToSelf(emptyAssets, type(uint256).max, tok) returns (uint256 _claimed) {
                    if (_claimed > 0) emit RewardClaimed(tok, _claimed);
                } catch (bytes memory reason) { emit HarvestCallFailed(msg.sig, reason); }
            }
            uint256 bal = IERC20(tok).balanceOf(address(this));
            if (bal == 0) { unchecked { ++i; } continue; }
            if (sh == address(0)) { unchecked { ++i; } continue; }
            // (2) M1 pre-flight: defer if oracle stale (no LINK burn on doomed swap)
            try ISwapHelper(sh).canSwap(tok) returns (bool ok) {
                if (!ok) { unchecked { ++i; } continue; }
            } catch (bytes memory reason) { emit HarvestCallFailed(msg.sig, reason); unchecked { ++i; } continue; }
            // (3) M2 swap — approve, attempt, reset approval regardless of outcome
            IERC20(tok).safeApprove(sh, 0);
            IERC20(tok).safeApprove(sh, bal);
            try ISwapHelper(sh).swapToUSDC(tok, bal, receiver) returns (uint256 out) {
                total += out;
            } catch (bytes memory reason) { emit HarvestCallFailed(msg.sig, reason); }
            IERC20(tok).safeApprove(sh, 0);
            unchecked { ++i; }
        }
        emit Harvested(receiver, total);
        return total;
    }

    // --- ILendingAdapter: Limits ---
    function maxCapacity() external view override returns (uint256) {
        return maxCap == 0 ? type(uint256).max : maxCap;
    }

    function setMaxCap(uint256 newCap) external onlyRole(DEFAULT_ADMIN_ROLE) {
        maxCap = newCap;
        emit MaxCapUpdated(newCap);
    }

    // --- ILendingAdapter: External Market TVL ---
    /// @notice Returns total USDC deposited in the Aave V3 pool (aToken totalSupply)
    function externalMarketTVL() external view override returns (uint256) {
        try IERC20(aToken).totalSupply() returns (uint256 supply) {
            return supply;
        } catch {
            return 0;
        }
    }

    // --- Idle Asset & Emergency Recovery ---
    event IdleAssetSwept(uint256 amount);
    event EmergencyPullExecuted(uint256 amount);
    /// @dev SLITHER-FIX-2: emit captured withdrawn amount from pool.withdraw return.
    event EmergencyAavePoolWithdrawn(uint256 requested, uint256 withdrawn);

    function sweepIdleAssetToVault() external nonReentrant onlyVault {
        uint256 idle = IERC20(asset).balanceOf(address(this));
        require(idle > 0, "no idle");
        IERC20(asset).safeTransfer(vault, idle);
        emit IdleAssetSwept(idle);
    }

    function emergencyPullAllToVault() external nonReentrant onlyVault {
        // Withdraw all invested from Aave
        uint256 invested = IAToken(aToken).balanceOf(address(this));
        if (invested > 0) {
            // SLITHER-FIX-2: capture withdrawn amount from pool.withdraw return + emit
            // detailed event. Aave returns the actual amount withdrawn (may differ from
            // requested in edge cases — e.g., utilization-bounded withdrawal).
            try pool.withdraw(asset, invested, address(this)) returns (uint256 _withdrawn) {
                emit EmergencyAavePoolWithdrawn(invested, _withdrawn);
            } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                // Withdraw failed - still sweep whatever is available; emit zero to signal failure
                emit EmergencyAavePoolWithdrawn(invested, 0);
            }
        }
        // Transfer FULL balance (withdrawn + any pre-existing idle) to vault
        uint256 fullBalance = IERC20(asset).balanceOf(address(this));
        if (fullBalance > 0) {
            IERC20(asset).safeTransfer(vault, fullBalance);
        }
        emit EmergencyPullExecuted(fullBalance);
    }

    // --- Fallbacks disabled ---

    // ─── Reward config admin ─────────────────────────────────────────────

    function initRewardConfig(address[] calldata tokens, address rc, address sh) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(rewardsController == address(0) && swapHelper == address(0), "already-init");
        require(tokens.length > 0, "empty-tokens");
        require(rc != address(0) && sh != address(0), "zero");
        for (uint256 i = 0; i < tokens.length; ) {
            address tok = tokens[i];
            require(tok != address(0), "zero-token");
            require(!isRewardWhitelisted[tok], "duplicate");
            isRewardWhitelisted[tok] = true;
            _rewardTokens.push(tok);
            unchecked { ++i; }
        }
        rewardsController = rc;
        swapHelper = sh;
        emit RewardConfigInitialized(rc, sh, tokens);
    }

    function addRewardToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(token != address(0), "zero");
        require(!isRewardWhitelisted[token], "already-whitelisted");
        isRewardWhitelisted[token] = true;
        _rewardTokens.push(token);
        emit RewardTokenAdded(token);
    }

    function removeRewardToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(isRewardWhitelisted[token], "not-whitelisted");
        isRewardWhitelisted[token] = false;
        // O(n) compact-remove from array
        uint256 n = _rewardTokens.length;
        for (uint256 i = 0; i < n; ) {
            if (_rewardTokens[i] == token) {
                _rewardTokens[i] = _rewardTokens[n - 1];
                _rewardTokens.pop();
                break;
            }
            unchecked { ++i; }
        }
        emit RewardTokenRemoved(token);
    }

    function setSwapHelper(address sh) external onlyRole(DEFAULT_ADMIN_ROLE) {
        // allow set to zero (emergency disable harvest pipeline)
        swapHelper = sh;
        emit SwapHelperUpdated(sh);
    }

    function setIncentiveHaircutBps(uint16 bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(bps <= 10_000, "bps>10000");
        incentiveHaircutBps = bps;
        emit IncentiveHaircutUpdated(bps);
    }

    function setRealizedRewardAPRBps(uint16 bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        realizedRewardAPRBps = bps;
        emit RealizedRewardAPRUpdated(bps);
    }

    function rewardTokens() external view returns (address[] memory) {
        return _rewardTokens;
    }

    function rewardTokensCount() external view returns (uint256) {
        return _rewardTokens.length;
    }

    function pendingRewardBalance(address token) external view returns (uint256) {
        if (!isRewardWhitelisted[token]) return 0;
        return IERC20(token).balanceOf(address(this));
    }

    receive() external payable {
        revert("NO_RECEIVE");
    }

    fallback() external payable {
        revert("NO_FALLBACK");
    }
    event AdapterOperationFailed(bytes4 indexed operation, bytes reason);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

// ----------- OpenZeppelin imports -----------
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

// ----------- IProtocolRegistry interface -----------
interface IProtocolRegistry {
    enum ProtocolType {
        AAVE_V3,
        EULER_V2,
        MORPHO,
        COMPOUND_V3,
        DOLOMITE,
        GAINS,
        SILO_V2
    }
    function getEnabledVaults(ProtocolType protocol) external view returns (address[] memory);
    function isEnabled(ProtocolType protocol, address vault) external view returns (bool);
}

// ----------- ILendingAdapter interface -----------
interface ILendingAdapter {
    function name() external view returns (string memory);
    function underlying() external view returns (address);

    // accounting
    function totalAssets() external view returns (uint256);
    function withdrawableAssets() external view returns (uint256);

    // lifecycle
    function deposit(uint256 assets) external;
    function withdraw(uint256 assets, address receiver) external returns (uint256 withdrawn);

    // yield
    function currentAPYBps() external view returns (uint16);
    function incentiveAPYBps() external view returns (uint16);
    function harvestableProfit() external view returns (uint256);
    function harvest(address receiver) external returns (uint256 realized);

    // limits
    function maxCapacity() external view returns (uint256);

    // external TVL
    function externalMarketTVL() external view returns (uint256);
}

// ----------- Minimal Comet interface -----------
interface IComet {
    function baseToken() external view returns (address);
    function supply(address asset, uint256 amount) external;
    function withdraw(address asset, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function getUtilization() external view returns (uint256);
    function getSupplyRate(uint256 utilization) external view returns (uint256);
    // V9.1: needed for external TVL calculation
    function totalsBasic() external view returns (uint64, uint64, uint104, uint104, uint64, uint64);
    function baseIndexScale() external view returns (uint64);
}

interface ICometRewards {
    /// @dev Compound III rewards controller — claim COMP for a given Comet market.
    function claim(address comet, address src, bool shouldAccrue) external;
    function rewardConfig(address comet) external view returns (address token, uint64 rescaleFactor, bool shouldUpscale);
}

interface IRewardSwapHelperComet {
    /// @dev RA-10 oracle freshness gate (M1) + USDC swap (M2).
    function canSwap(address rewardToken) external view returns (bool);
    function previewExpectedOut(address rewardToken, uint256 amountIn) external view returns (uint256);
    function swapToUSDC(address rewardToken, uint256 amountIn, address receiver) external returns (uint256);
}

// ----------- Adapter Contract -----------
contract CometUsdcMultiMarketAdapter is ILendingAdapter, AccessControl, ReentrancyGuard, Initializable {
    using SafeERC20 for IERC20;

    // ----------- Roles -----------
    bytes32 public constant PARAM_ROLE = keccak256("PARAM_ROLE");

    // ----------- Immutable config -----------
    // --- V10 Storage (was immutable in V9.x; logically immutable post-initialize) ---
    address public override underlying; // USDC
    address public vault; // Strategy Vault (no-custody)
    IProtocolRegistry public registry; // Optional registry (address(0) if not used)

    // ----------- Market Registry -----------
    struct Market {
        address comet; // Comet USDC market address
        bool enabled; // included in allocation
        bool flagged; // defense/hold
        uint16 riskScoreBps; // 0..10000 (10000 = lowest risk)
    }
    Market[] internal mkts;

    // ----------- Scoring Weights (constant for gas optimization) -----------
    uint16 public constant wAPY = 4000;
    uint16 public constant wLiq = 2500;
    uint16 public constant wRisk = 2000;
    uint16 public constant wStability = 1000;
    uint16 public constant wIncentive = 500;

    // ----------- Optimize/Drift/Gate Parameters -----------
    uint16 public rebalanceMinMoveBps = 50; // 0.5%
    uint32 public minSecondsBetweenOptimize = 6 hours;
    uint16 public constant driftToleranceBps = 10; // 0.1%
    uint16 public constant gateHorizonDays = 7;
    uint16 public gateMinNetBenefitBps = 2; // 0.02%
    uint16 public slippageBpsEstimate; // e.g. 4 = 0.04%
    uint16 public withdrawalSpreadBpsEstimate; // e.g. 2 = 0.02%
    uint256 public gasCostUSDC; // cost in USDC for optimize

    // ----------- Capacity & Incentives -----------
    uint256 public capacity; // 0 = infinite
    uint16 public incentiveBpsGlobal; // optional

    // ----------- Reward Pipeline v1 (M1+M2 + RA-10) -----------
    address public rewardToken;          // COMP
    address public rewardsController;    // CometRewards contract
    address public swapHelper;           // RewardSwapHelper instance
    uint16 public incentiveHaircutBps = 7500; // default 75% retain 25%
    uint16 public realizedRewardAPRBps;       // off-chain measured realized reward APR (bps)

    event RewardConfigInitialized(address rewardToken, address rewardsController, address swapHelper);
    event SwapHelperUpdated(address swapHelper);
    event IncentiveHaircutUpdated(uint16 bps);
    event RealizedRewardAPRUpdated(uint16 bps);
    event RewardsClaimed(uint256 amount);
    event RewardClaimFailed(address indexed controller, address indexed market, bytes reason);
    event HarvestExecuted(address rewardToken, uint256 amountIn, uint256 usdcOut, address receiver);
    event SwapDeferred(address rewardToken, uint256 pendingBalance, string reason);

    // ----------- State: allocation & telemetry -----------
    uint256[] public principal; // principal per market
    uint256 public principalTotal;
    uint64 public lastOptimizeTs;
    uint8 public activeIdx;

    // ----------- Events -----------
    event MarketAdded(uint256 indexed idx, address comet);
    event MarketToggled(uint256 indexed idx, bool enabled);
    event MarketFlagged(uint256 indexed idx, bool flagged);
    event MarketUpdated(uint256 indexed idx, address comet);
    event CostsEstimatesUpdated(
        uint16 slippageBps, uint16 withdrawalSpreadBps, uint256 gasCostUSDC
    );
    event OptimizeParamsUpdated(
        uint32 minSecondsBetweenOptimize, uint16 subMoveMinBps, uint16 subGateMinNetBenefitBps
    );
    event CapacityUpdated(uint256 capacity);
    event RiskScoreUpdated(uint256 indexed idx, uint16 riskScoreBps);
    event IntraRebalanced(address fromMarket, address toMarket, uint256 movedAssets);
    event Supplied(uint256 assets, address market);
    event Withdrawn(uint256 assets, address market, address receiver);

    // ----------- Modifiers -----------
    modifier onlyVault() {
        require(msg.sender == vault, "NotVault");
        _;
    }

    modifier onlyParam() {
        require(hasRole(PARAM_ROLE, msg.sender), "NotParam");
        _;
    }

    // ----------- Constructor -----------

    /// @notice One-shot initialization called atomically by AdapterFactory.
    function initialize(
        address usdc_,
        address admin_,
        address vault_,
        uint256 capacity_,
        address registry_
    ) external initializer {
        require(usdc_ != address(0) && admin_ != address(0) && vault_ != address(0), "zero");
        underlying = usdc_;
        vault = vault_;
        capacity = capacity_;
        registry = IProtocolRegistry(registry_); // Can be address(0)

        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
        _grantRole(PARAM_ROLE, admin_);

        // Auto-load from registry if available
        if (registry_ != address(0)) {
            _loadFromRegistry();
        }

        // V9 HARDENING: Fail-fast if no markets loaded
        require(mkts.length > 0, "CometAdapter: no markets - registry required or use addMarket");
    }

    // ----------- Registry Management (PARAM_ROLE) -----------
    function addMarket(address comet) external onlyParam {
        require(comet != address(0), "zero");
        require(IComet(comet).baseToken() == underlying, "NotUSDC");
        mkts.push(Market({ comet: comet, enabled: true, flagged: false, riskScoreBps: 10000 }));
        principal.push(0);
        emit MarketAdded(mkts.length - 1, comet);
    }

    function toggleMarket(uint256 idx, bool enabled) external onlyParam {
        require(idx < mkts.length, "badIdx");
        mkts[idx].enabled = enabled;
        emit MarketToggled(idx, enabled);
    }

    function flagMarket(uint256 idx, bool flagged) external onlyParam {
        require(idx < mkts.length, "badIdx");
        mkts[idx].flagged = flagged;
        emit MarketFlagged(idx, flagged);
    }

    function updateMarketAddress(uint256 idx, address comet) external onlyParam {
        require(idx < mkts.length, "badIdx");
        require(comet != address(0), "zero");
        require(IComet(comet).baseToken() == underlying, "NotUSDC");
        mkts[idx].comet = comet;
        emit MarketUpdated(idx, comet);
    }

    function setRiskScore(uint256 idx, uint16 riskScoreBps) external onlyParam {
        require(idx < mkts.length, "badIdx");
        require(riskScoreBps <= 10000, "badScore");
        mkts[idx].riskScoreBps = riskScoreBps;
        emit RiskScoreUpdated(idx, riskScoreBps);
    }

    function setCostsEstimates(
        uint16 slippageBps,
        uint16 withdrawalSpreadBps,
        uint256 gasCostUSDC_
    ) external onlyParam {
        slippageBpsEstimate = slippageBps;
        withdrawalSpreadBpsEstimate = withdrawalSpreadBps;
        gasCostUSDC = gasCostUSDC_;
        emit CostsEstimatesUpdated(slippageBps, withdrawalSpreadBps, gasCostUSDC_);
    }

    function setOptimizeParams(
        uint32 minSecondsBetweenOptimize_,
        uint16 subMoveMinBps,
        uint16 subGateMinNetBenefitBps
    ) external onlyParam {
        minSecondsBetweenOptimize = minSecondsBetweenOptimize_;
        rebalanceMinMoveBps = subMoveMinBps;
        gateMinNetBenefitBps = subGateMinNetBenefitBps;
        emit OptimizeParamsUpdated(
            minSecondsBetweenOptimize_, subMoveMinBps, subGateMinNetBenefitBps
        );
    }

    function setCapacity(uint256 capacity_) external onlyParam {
        capacity = capacity_;
        emit CapacityUpdated(capacity_);
    }

    function setIncentiveBps(uint16 bps) external onlyParam {
        incentiveBpsGlobal = bps;
    }

    // ----------- ILendingAdapter: View Functions -----------
    function name() external pure override returns (string memory) {
        return "Comet_USDC_MultiMarket_Adapter_Arbitrum";
    }

    /// @notice Returns false because Comet uses PULL deposit pattern
    /// @dev Adapter calls transferFrom() to pull USDC from Strategy during deposit()
    function isPushMode() external pure returns (bool) {
        return false;
    }

    function idleAssetBalance() public view returns (uint256) {
        return IERC20(underlying).balanceOf(address(this));
    }

    function investedAssets() public view returns (uint256 total) {
        total = 0; // Initialize local variable (slither: uninitialized-local)
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            total += _assetsOn(i);
        }
    }

    function totalAssets() public view override returns (uint256) {
        return investedAssets() + idleAssetBalance();
    }

    function withdrawableAssets() public view override returns (uint256 total) {
        total = 0; // Initialize local variable (slither: uninitialized-local)
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            total += _withdrawableOn(i);
        }
    }

    function currentAPYBps() public view override returns (uint16) {
        if (mkts.length < 1) return 0; // slither: incorrect-equality - use < 1 instead of == 0
        Market storage m = mkts[activeIdx];
        return _getAPYBps(m.comet);
    }

    function incentiveAPYBps() external view override returns (uint16) {
        // realized takes priority; haircut applied to retain (10000-haircut) of realized.
        uint256 raw = realizedRewardAPRBps != 0 ? realizedRewardAPRBps : incentiveBpsGlobal;
        if (raw == 0) return 0;
        uint256 retain = 10_000 - uint256(incentiveHaircutBps);
        uint256 result = (raw * retain) / 10_000;
        if (result > type(uint16).max) return type(uint16).max;
        return uint16(result);
    }

    function harvestableProfit() external view override returns (uint256) {
        if (rewardToken == address(0) || swapHelper == address(0)) return 0;
        uint256 bal = IERC20(rewardToken).balanceOf(address(this));
        if (bal == 0) return 0;
        try IRewardSwapHelperComet(swapHelper).canSwap(rewardToken) returns (bool ok) {
            if (!ok) return 0;
        } catch { return 0; }
        try IRewardSwapHelperComet(swapHelper).previewExpectedOut(rewardToken, bal) returns (uint256 e) {
            return e;
        } catch { return 0; }
    }

    function harvest(address receiver) external override nonReentrant onlyVault returns (uint256 realized) {
        // Gas: cache both once -- neither has a setter reachable from within
        // this call, and each was otherwise re-read from storage up to ~10x
        // (rewardToken) / ~6x (swapHelper) across this function.
        address rewardToken_ = rewardToken;
        address swapHelper_ = swapHelper;
        if (rewardToken_ == address(0) || rewardsController == address(0)) return 0;
        // (1) Claim COMP — graceful (M2): never propagate revert
        // Iterate enabled markets and claim from each (single rewardToken across all markets)
        uint256 nMkt = mkts.length;
        for (uint256 i = 0; i < nMkt; ) {
            if (mkts[i].enabled) {
                try ICometRewards(rewardsController).claim(mkts[i].comet, address(this), true) {} catch (bytes memory reason) {
                    emit RewardClaimFailed(rewardsController, mkts[i].comet, reason);
                }
            }
            unchecked { ++i; }
        }
        uint256 bal = IERC20(rewardToken_).balanceOf(address(this));
        if (bal > 0) emit RewardsClaimed(bal);
        if (bal == 0) return 0;
        if (swapHelper_ == address(0)) {
            emit SwapDeferred(rewardToken_, bal, "no-helper");
            return 0;
        }
        // (2) M1 pre-flight: defer if oracle stale (no LINK burn on doomed swap)
        bool ok;
        try IRewardSwapHelperComet(swapHelper_).canSwap(rewardToken_) returns (bool v) { ok = v; } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason); ok = false; }
        if (!ok) {
            emit SwapDeferred(rewardToken_, bal, "oracle-stale");
            return 0;
        }
        // (3) M2 swap — approve, attempt, reset approval regardless of outcome
        IERC20(rewardToken_).forceApprove(swapHelper_, 0);
        IERC20(rewardToken_).forceApprove(swapHelper_, bal);
        try IRewardSwapHelperComet(swapHelper_).swapToUSDC(rewardToken_, bal, receiver) returns (uint256 out) {
            realized = out;
            emit HarvestExecuted(rewardToken_, bal, out, receiver);
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            emit SwapDeferred(rewardToken_, bal, "swap-revert");
        }
        IERC20(rewardToken_).forceApprove(swapHelper_, 0);
        return realized;
    }

    function maxCapacity() external view override returns (uint256) {
        return capacity == 0 ? type(uint256).max : capacity;
    }

    /// @notice Returns total USDC liquidity across all enabled Comet markets
    /// @dev Uses USDC balance of each Comet contract (available liquidity, conservative lower bound)
    /// @notice Total USDC supplied to external Comet markets.
    /// @dev Uses totalsBasic().totalSupplyBase * baseSupplyIndex / baseIndexScale
    ///      for accurate total supply (not just available cash).
    function externalMarketTVL() external view override returns (uint256 total) {
        total = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (!mkts[i].enabled) continue;
            try IComet(mkts[i].comet).totalsBasic() returns (
                uint64 baseSupplyIndex, uint64, uint104, uint104, uint64 totalSupplyBase, uint64
            ) {
                try IComet(mkts[i].comet).baseIndexScale() returns (uint64 scale) {
                    if (scale > 0) {
                        total += (uint256(totalSupplyBase) * uint256(baseSupplyIndex)) / uint256(scale);
                    }
                } catch {}
            } catch {
                // Fallback: use cash balance as conservative proxy
                try IERC20(underlying).balanceOf(mkts[i].comet) returns (uint256 bal) {
                    total += bal;
                } catch {}
            }
        }
    }

    // ----------- Extra Public View: Markets & Positions -----------
    function markets() external view returns (address[] memory) {
        uint256 n = mkts.length;
        address[] memory out = new address[](n);
        for (uint256 i = 0; i < n; ++i) {
            out[i] = mkts[i].comet;
        }
        return out;
    }

    function activeMarket() external view returns (address) {
        return mkts.length < 1 ? address(0) : mkts[activeIdx].comet; // slither: incorrect-equality - use < 1 instead of == 0
    }

    function positions() external view returns (uint256[] memory assetsByMarket) {
        uint256 n = mkts.length;
        assetsByMarket = new uint256[](n);
        for (uint256 i = 0; i < n; ++i) {
            assetsByMarket[i] = _assetsOn(i);
        }
    }

    function effectiveAPYBps() external view returns (uint16) {
        uint256 n = mkts.length;
        uint256 total = totalAssets();
        if (total < 1) return 0; // slither: incorrect-equality - use < 1 instead of == 0
        uint256 apySum = 0; // Initialize local variable (slither: uninitialized-local)
        for (uint256 i = 0; i < n; ++i) {
            uint256 assets = _assetsOn(i);
            if (assets < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
            apySum += _getAPYBps(mkts[i].comet) * assets;
        }
        uint256 result = apySum / total;
        require(result <= type(uint16).max, "CometUsdcMultiMarket: APY overflow");
        // casting to uint16 is safe because overflow is checked above
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint16(result);
    }

    // ----------- INTERNAL HELPERS -----------

    /// @notice Sets just-in-time approval for exact amount
    /// @dev Prevents unlimited protocol exposure if Compound market is compromised
    function _approveMarket(address marketAddr, uint256 amount) internal {
        IERC20(underlying).forceApprove(marketAddr, amount);
    }

    /// @notice Resets market approval to zero
    function _revokeMarketApproval(address marketAddr) internal {
        IERC20(underlying).forceApprove(marketAddr, 0);
    }

    // ----------- Internal: Market Helpers -----------
    /// @dev Guarded: a bricked/paused market reports 0 assets rather than
    ///      reverting -- callers (withdraw()'s per-market loop, totalAssets())
    ///      then correctly treat it as having nothing available, instead of
    ///      the whole call reverting because of one broken market.
    function _assetsOn(uint256 idx) internal view returns (uint256) {
        Market storage m = mkts[idx];
        try IComet(m.comet).balanceOf(address(this)) returns (uint256 bal) {
            return bal;
        } catch {
            return 0;
        }
    }

    function _withdrawableOn(uint256 idx) internal view returns (uint256) {
        Market storage m = mkts[idx];
        uint256 assets = _assetsOn(idx);
        uint256 usdcAvail = IERC20(underlying).balanceOf(m.comet);
        return assets < usdcAvail ? assets : usdcAvail;
    }

    /// @dev Guarded: a single paused/deprecated Comet market must not brick
    ///      scoring/sorting (and therefore deposit()/withdraw()) for every
    ///      other healthy market on this adapter. A failing market reports
    ///      APY=0, which sorts it last for deposits and first for withdrawal
    ///      attempts (harmless -- _withdrawableOn/_assetsOn are separately
    ///      guarded below and simply skip it if it can't report a balance).
    function _getAPYBps(address comet) internal view returns (uint16) {
        try IComet(comet).getUtilization() returns (uint256 util) {
            try IComet(comet).getSupplyRate(util) returns (uint256 ratePerSec) {
                uint256 aprWad = ratePerSec * 31_536_000; // 365*24*60*60
                uint256 bps = (aprWad * 10000) / 1e18;
                // casting to uint16 is safe because overflow is checked with ternary
                // forge-lint: disable-next-line(unsafe-typecast)
                return bps > type(uint16).max ? type(uint16).max : uint16(bps);
            } catch {
                return 0;
            }
        } catch {
            return 0;
        }
    }

    // ----------- Lifecycle: Deposit/Withdraw (No-custody) -----------
    function deposit(uint256 assets) external override nonReentrant onlyVault {
        require(assets > 0, "zero");
        if (capacity > 0) require(totalAssets() + assets <= capacity, "cap");
        uint256 target = _selectBestMarket();
        Market storage m = mkts[target];
        require(m.enabled && !m.flagged, "noMkt");

        // Gas: cache the target market's address once -- `m` is a storage
        // pointer, so each `m.comet` access is its own SLOAD; `comet_` was
        // otherwise read 3x for one unchanged value.
        address comet_ = m.comet;
        IERC20(underlying).safeTransferFrom(msg.sender, address(this), assets);
        _approveMarket(comet_, assets);
        IComet(comet_).supply(underlying, assets);
        _revokeMarketApproval(comet_);

        principal[target] += assets;
        principalTotal += assets;
        require(target <= type(uint8).max, "CometUsdcMultiMarket: target overflow");
        // casting to uint8 is safe because overflow is checked above
        // forge-lint: disable-next-line(unsafe-typecast)
        activeIdx = uint8(target);

        emit Supplied(assets, m.comet);
    }

    function withdraw(
        uint256 assets,
        address /*receiver*/
    )
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 withdrawn)
    {
        uint256 want = assets;
        uint256 avail = withdrawableAssets();
        if (want > avail) want = avail;
        require(want > 0, "zero");

        withdrawn = 0; // Initialize local variable (slither: uninitialized-local)
        uint256 n = mkts.length;
        uint256 left = want;
        // Withdraw from least performant markets first (lowest APY)
        uint256[] memory order = _marketsByAPY(false); // ascending APY
        for (uint256 i = 0; i < n && left > 0; ++i) {
            uint256 idx = order[i];
            uint256 can = _withdrawableOn(idx);
            if (can < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
            uint256 take = can > left ? left : can;
            if (take > 0) {
                IComet(mkts[idx].comet).withdraw(underlying, take);
                IERC20(underlying).safeTransfer(vault, take);

                // Adjust principal proportionally
                uint256 balBefore = principal[idx];
                uint256 totalAssetsOn = _assetsOn(idx);
                if (balBefore > 0) {
                    uint256 principalDelta = balBefore * take / (totalAssetsOn + take);
                    if (principalDelta > balBefore) principalDelta = balBefore;
                    principal[idx] -= principalDelta;
                    principalTotal -= principalDelta;
                }

                emit Withdrawn(take, mkts[idx].comet, vault);
                left -= take;
                if (left < 1) break; // slither: incorrect-equality - use < 1 instead of == 0
            }
        }
        withdrawn = want - left;
    }

    // ----------- Optimize / Rebalance -----------
    function optimize()
        external
        nonReentrant
        onlyVault
        returns (uint256 movedUSDC, address fromMarket, address toMarket)
    {
        require(block.timestamp >= lastOptimizeTs + minSecondsBetweenOptimize, "cooldown");

        uint256 n = mkts.length;
        require(n > 1, "singleMkt");

        // Score all enabled & unflagged markets
        uint256[] memory scores = new uint256[](n);
        uint256 bestScore = 0;
        uint256 bestIdx = 0;
        for (uint256 i = 0; i < n; ++i) {
            Market storage m = mkts[i];
            if (!m.enabled || m.flagged) continue;
            uint16 apy = _getAPYBps(m.comet);
            uint256 liq = IERC20(underlying).balanceOf(m.comet);
            uint16 risk = 10000 - m.riskScoreBps;
            // Stability: for simplicity, use APY as EMA
            uint16 stability = apy;
            uint16 incentive = incentiveBpsGlobal;

            uint256 score = uint256(apy) * wAPY + liq * wLiq / 1e6 // normalize liquidity to bps
                + uint256(risk) * wRisk + uint256(stability) * wStability + uint256(incentive)
                * wIncentive;
            scores[i] = score;
            if (score > bestScore) {
                bestScore = score;
                bestIdx = i;
            }
        }

        // If already optimal, skip
        if (bestIdx == activeIdx) return (0, mkts[activeIdx].comet, mkts[bestIdx].comet);

        // Move from current active to best
        uint256 fromIdx = activeIdx;
        uint256 toIdx = bestIdx;

        uint256 tvl = totalAssets();
        uint256 fromAssets = _assetsOn(fromIdx);
        uint256 toAssets = _assetsOn(toIdx);

        // Move at least minMove
        uint256 minMove = (tvl * rebalanceMinMoveBps) / 1e4;
        if (fromAssets < minMove) return (0, mkts[fromIdx].comet, mkts[toIdx].comet);

        // Estimate benefit
        uint16 apyFrom = _getAPYBps(mkts[fromIdx].comet);
        uint16 apyTo = _getAPYBps(mkts[toIdx].comet);
        if (apyTo <= apyFrom) return (0, mkts[fromIdx].comet, mkts[toIdx].comet);
        uint256 deltaAPY = apyTo - apyFrom;

        uint256 horizon = gateHorizonDays * 1 days;
        uint256 grossBenefit = (fromAssets * deltaAPY * horizon) / (10000 * 365 days);
        uint256 moveCost = gasCostUSDC
            + (fromAssets * (slippageBpsEstimate + withdrawalSpreadBpsEstimate)) / 10000;
        require(
            grossBenefit <= uint256(type(int256).max), "CometUsdcMultiMarket: grossBenefit overflow"
        );
        require(moveCost <= uint256(type(int256).max), "CometUsdcMultiMarket: moveCost overflow");
        // casting to int256 is safe because overflow is checked above
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 netBenefit = int256(grossBenefit) - int256(moveCost);
        uint256 netBenefitBps = (grossBenefit > 0 && tvl > 0) ? (grossBenefit * 10000) / tvl : 0;
        if (netBenefit <= 0 || netBenefitBps < gateMinNetBenefitBps) {
            return (0, mkts[fromIdx].comet, mkts[toIdx].comet);
        }

        // Audit #2 P0.3 — clamp the move BEFORE the withdraw.
        //   fromAvail: actual withdrawable from source (market liquidity).
        //   toRoom:    how much target is willing to accept.
        //   moveAmount = min(planned, fromAvail, toRoom).
        // This prevents the classic pattern of "withdraw everything, then discover
        // the target rejects" which would leave funds idle and break accounting.
        uint256 fromAvail = _withdrawableOn(fromIdx);
        uint256 toRoom = _maxAdditionalDeposit(toIdx);
        uint256 moveAmount = fromAssets;
        if (moveAmount > fromAvail) moveAmount = fromAvail;
        if (moveAmount > toRoom) moveAmount = toRoom;
        if (moveAmount < minMove) {
            return (0, mkts[fromIdx].comet, mkts[toIdx].comet);
        }

        // Withdraw from fromIdx (clamped)
        IComet(mkts[fromIdx].comet).withdraw(underlying, moveAmount);
        _approveMarket(mkts[toIdx].comet, moveAmount);
        IComet(mkts[toIdx].comet).supply(underlying, moveAmount);
        _revokeMarketApproval(mkts[toIdx].comet);

        // Update principal proportionally — never zero out fromIdx unless we moved all of it.
        uint256 fromPrincipal = principal[fromIdx];
        if (moveAmount >= fromPrincipal) {
            principal[fromIdx] = 0;
        } else {
            principal[fromIdx] = fromPrincipal - moveAmount;
        }
        principal[toIdx] += moveAmount;
        require(toIdx <= type(uint8).max, "CometUsdcMultiMarket: toIdx overflow");
        require(block.timestamp <= type(uint64).max, "CometUsdcMultiMarket: timestamp overflow");
        // Only flip activeIdx if source is now empty after the move.
        if (principal[fromIdx] == 0) {
            // forge-lint: disable-next-line(unsafe-typecast)
            activeIdx = uint8(toIdx);
        }
        // forge-lint: disable-next-line(unsafe-typecast)
        lastOptimizeTs = uint64(block.timestamp);

        emit IntraRebalanced(mkts[fromIdx].comet, mkts[toIdx].comet, moveAmount);
        return (moveAmount, mkts[fromIdx].comet, mkts[toIdx].comet);
    }

    /// @dev Audit #2 P0.3 — Comet does not advertise a supply cap on-chain, but we
    ///      keep a deliberate guard here so future hardening (e.g. per-market caps
    ///      via riskScoreBps) can plug into the same abstraction.
    function _maxAdditionalDeposit(uint256 idx) internal view returns (uint256) {
        if (idx >= mkts.length) return 0;
        // Comet: effectively unbounded; return a conservative sentinel.
        return type(uint256).max;
    }

    // ----------- Internal: Market Selection & Ordering -----------
    function _selectBestMarket() internal view returns (uint256 bestIdx) {
        uint256 n = mkts.length;
        require(n > 0, "noMkts");
        bestIdx = 0; // Initialize local variable (slither: uninitialized-local)
        uint256 bestScore = 0;
        for (uint256 i = 0; i < n; ++i) {
            Market storage m = mkts[i];
            if (!m.enabled || m.flagged) continue;
            uint16 apy = _getAPYBps(m.comet);
            if (apy > bestScore) {
                bestScore = apy;
                bestIdx = i;
            }
        }
    }

    // Returns market indices sorted by APY ascending/descending
    function _marketsByAPY(bool descending) internal view returns (uint256[] memory order) {
        uint256 n = mkts.length;
        order = new uint256[](n);
        for (uint256 i = 0; i < n; ++i) {
            order[i] = i;
        }

        // Selection sort (gas-efficient for small N)
        for (uint256 i = 0; i < n; ++i) {
            uint256 best = i;
            for (uint256 j = i + 1; j < n; ++j) {
                uint16 apyBest = _getAPYBps(mkts[order[best]].comet);
                uint16 apyJ = _getAPYBps(mkts[order[j]].comet);
                if (descending ? (apyJ > apyBest) : (apyJ < apyBest)) best = j;
            }
            if (best != i) {
                uint256 tmp = order[i];
                order[i] = order[best];
                order[best] = tmp;
            }
        }
    }

    // ----------- Registry Integration -----------

    /// @notice Internal: Load vault addresses from registry
    function _loadFromRegistry() internal {
        try registry.getEnabledVaults(IProtocolRegistry.ProtocolType.COMPOUND_V3) returns (
            address[] memory vaults
        ) {
            for (uint256 i = 0; i < vaults.length; i++) {
                if (vaults[i] != address(0)) {
                    // Registry is trusted source - no validation needed
                    // Vaults from registry are pre-validated and whitelisted
                    mkts.push(
                        Market({
                            comet: vaults[i], enabled: true, flagged: false, riskScoreBps: 10000
                        })
                    );
                    principal.push(0);
                }
            }
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            // Registry call failed - adapter will start with empty markets or use manual addMarket()
        }
    }

    /// @notice Refresh markets from registry (clear and reload)
    function refreshFromRegistry() external onlyParam {
        require(address(registry) != address(0), "no registry");

        // Clear existing markets
        delete mkts;
        delete principal;

        // Reload from registry
        _loadFromRegistry();
    }

    // ----------- Idle Asset & Emergency Recovery -----------
    event IdleAssetSwept(uint256 amount);
    event EmergencyPullExecuted(uint256 amount);

    function sweepIdleAssetToVault() external nonReentrant onlyVault {
        uint256 idle = IERC20(underlying).balanceOf(address(this));
        require(idle > 0, "no idle");
        IERC20(underlying).safeTransfer(vault, idle);
        emit IdleAssetSwept(idle);
    }

    function emergencyPullAllToVault() external nonReentrant onlyVault {
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            uint256 bal = _assetsOn(i);
            if (bal > 0) {
                try IComet(mkts[i].comet).withdraw(underlying, bal) {
                } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                    // Withdraw failed - skip this market
                }
                principal[i] = 0;
            }
        }
        principalTotal = 0;
        // Transfer FULL balance (withdrawn + any pre-existing idle) to vault
        uint256 fullBalance = IERC20(underlying).balanceOf(address(this));
        if (fullBalance > 0) {
            IERC20(underlying).safeTransfer(vault, fullBalance);
        }
        emit EmergencyPullExecuted(fullBalance);
    }

    // ----------- Sweep Protection -----------
    receive() external payable {
        revert("ETH not accepted");
    }

    fallback() external payable {
        revert("fallback");
    }

    // ----------- Reward config admin (PARAM_ROLE) -----------

    function setRewardConfig(address _rewardToken, address _rewardsController, address _swapHelper) external onlyParam {
        require(rewardToken == address(0) && rewardsController == address(0), "already-init");
        require(_rewardToken != address(0) && _rewardsController != address(0) && _swapHelper != address(0), "zero");
        rewardToken = _rewardToken;
        rewardsController = _rewardsController;
        swapHelper = _swapHelper;
        emit RewardConfigInitialized(_rewardToken, _rewardsController, _swapHelper);
    }

    function setSwapHelper(address sh) external onlyParam {
        // allow set to zero (emergency disable)
        swapHelper = sh;
        emit SwapHelperUpdated(sh);
    }

    function setIncentiveHaircutBps(uint16 bps) external onlyParam {
        require(bps <= 10_000, "bps>10000");
        incentiveHaircutBps = bps;
        emit IncentiveHaircutUpdated(bps);
    }

    function setRealizedRewardAPRBps(uint16 bps) external onlyParam {
        realizedRewardAPRBps = bps;
        emit RealizedRewardAPRUpdated(bps);
    }

    function pendingRewardBalance() external view returns (uint256) {
        if (rewardToken == address(0)) return 0;
        return IERC20(rewardToken).balanceOf(address(this));
    }

    event AdapterOperationFailed(bytes4 indexed operation, bytes reason);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;
import { PpsRateLib } from "./PpsRateLib.sol";

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

// ===== Dolomite Adapter Interfaces =====

// Registry interface
interface IProtocolRegistry {
    enum ProtocolType {
        AAVE_V3,
        EULER_V2,
        MORPHO,
        COMPOUND_V3,
        DOLOMITE,
        GAINS,
        SILO_V2
    }
    function getEnabledVaults(ProtocolType protocol) external view returns (address[] memory);
    function isEnabled(ProtocolType protocol, address vault) external view returns (bool);
}

// Core/Strategy Vault expected interface
interface ILendingAdapter {
    function name() external view returns (string memory);
    function underlying() external view returns (address);

    // accounting
    function totalAssets() external view returns (uint256);
    function withdrawableAssets() external view returns (uint256);

    // lifecycle
    function deposit(uint256 assets) external;
    function withdraw(uint256 assets, address receiver) external returns (uint256 withdrawn);

    // yield
    function currentAPYBps() external view returns (uint16);
    function incentiveAPYBps() external view returns (uint16);
    function harvestableProfit() external view returns (uint256);
    function harvest(address receiver) external returns (uint256 realized);

    // limits
    function maxCapacity() external view returns (uint256);

    // external TVL
    function externalMarketTVL() external view returns (uint256);
}

// ERC-4626-like market interface
interface IERC4626Like {
    function asset() external view returns (address);
    function totalAssets() external view returns (uint256);
    function convertToAssets(uint256 shares) external view returns (uint256);
    function convertToShares(uint256 assets) external view returns (uint256);
    function previewWithdraw(uint256 assets) external view returns (uint256 shares);
    function deposit(uint256 assets, address receiver) external returns (uint256 sharesMinted);
    function withdraw(uint256 assets, address receiver, address owner)
        external
        returns (uint256 sharesBurned);
}

// Pool-like (Dolomite core/margin style) market interface
interface IDolomiteLike {
    function baseToken() external view returns (address);
    function supply(address token, uint256 amount) external;
    function withdraw(address token, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function availableLiquidity(address token) external view returns (uint256);
    // Optionally: function toAssets(uint256 shares) external view returns (uint256);
    // Optionally: function toShares(uint256 assets) external view returns (uint256);
}

// Dolomite Margin V9 interface (correct interface for Arbitrum mainnet)
interface IDolomiteMargin {
    struct AccountInfo {
        address owner;
        uint256 number;
    }

    struct Wei {
        bool sign; // true = positive, false = negative
        uint256 value;
    }
    function getAccountWei(AccountInfo calldata account, uint256 marketId)
        external
        view
        returns (Wei memory);
    function getMarketTokenAddress(uint256 marketId) external view returns (address);
}

// Optional external rate provider for Pool-like markets. Returns supply rate per second (WAD 1e18)
interface IDolomiteRateProvider {
    function getSupplyRatePerSecond(address market) external view returns (uint256);
}

// Audit #2 P0.4 / P0.5 — strict-detection and config-guard errors.
error AmbiguousMarketType(address market);
error UnsupportedMarketType(address market);
error InvalidDolomiteConfig(address market, uint256 marketId, uint256 accountNumber);
error DolomiteConfigInvalid();

// ===== Adapter Contract =====

contract DolomiteUsdcMultiMarketAdapter is ILendingAdapter, AccessControl, ReentrancyGuard, Initializable {
    using SafeERC20 for IERC20;

    // --- Roles ---
    bytes32 public constant PARAM_ROLE = keccak256("PARAM_ROLE");

    // --- Immutable addresses ---
    // --- V10 Storage (was immutable in V9.x; logically immutable post-initialize) ---
    address public asset; // USDC native (Arbitrum)
    address public vault; // Authorized Strategy Vault
    IProtocolRegistry public registry; // Optional registry (address(0) if not used)

    // --- Capacity and incentives ---
    uint256 public capacity; // 0 = no limit
    uint16 public incentiveBpsGlobal; // Optional, default 0
    uint16 public apyOverrideBps; // Optional APY override (bps), 0=disabled
    address public rateProvider; // Optional on-chain rate provider for Pool-like markets

    // --- Dolomite Margin V9 fix ---
    uint256 public usdcMarketId; // USDC market ID on Dolomite Margin (e.g., 17 on Arbitrum)
    uint256 public accountNumber; // Account number for getAccountWei (default 0)

    // Audit #2 P0.5 — the adapter is NOT considered usable on Margin markets until
    // validateDolomiteConfig() has passed at least once after the last mutation.
    bool public dolomiteConfigValid;

    // ERC-4626 APY snapshot for share price (pps)
    struct PpsSnap {
        uint256 pps;
        uint64 ts;
    }
    mapping(address => PpsSnap) public ppsSnap;

    // --- Market Types ---
    enum MarketType {
        ERC4626,
        PoolLike
    }

    // --- Market Registry ---
    struct Market {
        address addr;
        MarketType mtype;
        bool enabled;
        bool flagged; // defense/hold: don't increment alloc
        uint16 riskScoreBps; // 0..10000 (10000 = min risk)
        uint16 lastAPYBps; // last observed APY (for Stability/EMA)
    }
    Market[] internal mkts;

    // --- Accounting ---
    uint256[] internal principal; // principal per market
    uint256 internal principalTotal;

    // --- Preferences/telemetry ---
    uint8 public activeIdx; // default target market
    uint64 public lastOptimizeTs;

    // --- Score Weights (sum 10000) ---
    uint16 public wAPY;
    uint16 public wLiq;
    uint16 public wRisk;
    uint16 public wStability;
    uint16 public wIncentive;

    // --- Movement/gate parameters ---
    uint16 public rebalanceMinMoveBps; // e.g. 50 = 0.5% TVL
    uint32 public minSecondsBetweenOptimize; // e.g. 21600 (6h)
    uint16 public driftToleranceBps; // e.g. 80 (0.80%)

    // --- Benefit>Cost gate ---
    uint16 public constant gateHorizonDays = 7;
    uint16 public gateMinNetBenefitBps; // e.g. 2 (0.02%)
    uint16 public slippageBpsEstimate; // e.g. 3
    uint16 public withdrawalSpreadBpsEstimate; // e.g. 5
    uint256 public gasCostUSDC; // gas cost estimate (USDC)

    // ===== Events =====
    event MarketAdded(uint256 indexed idx, address market, MarketType mtype);
    event MarketUpdated(uint256 indexed idx, address market, MarketType mtype);
    event MarketToggled(uint256 indexed idx, bool enabled);
    event MarketFlagged(uint256 indexed idx, bool flagged);
    event RiskScoreUpdated(uint256 indexed idx, uint16 riskScoreBps);

    event Supplied(uint256 assets, address market);
    event Withdrawn(uint256 assets, address market, address receiver);
    event IntraRebalanced(address fromMarket, address toMarket, uint256 movedAssets);

    event CostsEstimatesUpdated(
        uint16 slippageBps, uint16 withdrawalSpreadBps, uint256 gasCostUSDC
    );
    event OptimizeParamsUpdated(
        uint32 minSecondsBetweenOptimize,
        uint16 subMoveMinBps,
        uint16 subGateMinNetBenefitBps,
        uint16 driftTolBps
    );
    event CapacityUpdated(uint256 capacity);
    event WeightsUpdated(
        uint16 wAPY, uint16 wLiq, uint16 wRisk, uint16 wStability, uint16 wIncentive
    );
    event RateProviderUpdated(address provider);
    event DolomiteMarketIdUpdated(uint256 marketId);
    event DolomiteAccountNumberUpdated(uint256 accountNumber);

    // ===== Modifiers =====

    modifier onlyVault() {
        require(msg.sender == vault, "not vault");
        _;
    }

    // ===== Constructor =====


    /// @notice One-shot initialization called atomically by AdapterFactory.
    function initialize(
        address usdc_,
        address admin_,
        address vault_,
        uint256 capacity_,
        address registry_
    ) external initializer {
        require(usdc_ != address(0) && admin_ != address(0) && vault_ != address(0), "zero");
        asset = usdc_;
        vault = vault_;
        capacity = capacity_;
        registry = IProtocolRegistry(registry_); // Can be address(0)

        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
        _grantRole(PARAM_ROLE, admin_);

        // Default weights (sum 10000)
        wAPY = 5000;
        wLiq = 2000;
        wRisk = 1500;
        wStability = 1000;
        wIncentive = 500;

        // Default movement/gate
        rebalanceMinMoveBps = 50; // 0.5% TVL
        minSecondsBetweenOptimize = 21600; // 6h
        driftToleranceBps = 80; // 0.80%

        // gateHorizonDays is constant (7)
        gateMinNetBenefitBps = 2;
        slippageBpsEstimate = 3;
        withdrawalSpreadBpsEstimate = 5;
        gasCostUSDC = 0;

        // Auto-load from registry if available
        if (registry_ != address(0)) {
            _loadFromRegistry();
        }

        // V9 HARDENING: Fail-fast if no markets loaded
        require(mkts.length > 0, "DolomiteAdapter: no markets - registry required or use addMarket");
    }

    // ===== Registry & Setters (PARAM_ROLE) =====

    function addMarket(address m, MarketType t) external onlyRole(PARAM_ROLE) {
        require(m != address(0), "m=0");
        // Audit #2 P0.4 — cross-validate the declared type against the on-chain
        // surface; never trust the operator-supplied type alone.
        MarketType detected = _detectMarketType(m);
        require(detected == t, "Dolomite: declared type mismatch with detected");
        mkts.push(
            Market({
                addr: m, mtype: t, enabled: true, flagged: false, riskScoreBps: 10000, lastAPYBps: 0
            })
        );
        principal.push(0);
        // Audit #2 P0.5 — any registry mutation invalidates the config until
        // validateDolomiteConfig() is re-run.
        dolomiteConfigValid = false;
        emit MarketAdded(mkts.length - 1, m, t);
    }

    function updateMarket(uint256 idx, address m, MarketType t) external onlyRole(PARAM_ROLE) {
        require(idx < mkts.length && m != address(0), "bad");
        MarketType detected = _detectMarketType(m);
        require(detected == t, "Dolomite: declared type mismatch with detected");
        mkts[idx].addr = m;
        mkts[idx].mtype = t;
        dolomiteConfigValid = false;
        emit MarketUpdated(idx, m, t);
    }

    /// @notice Audit #2 P0.4 — strict market type detection by underlying match.
    /// @dev Rejects ambiguous (both interfaces valid) and unknown markets.
    function _detectMarketType(address m) internal view returns (MarketType) {
        bool is4626;
        bool isPool;

        try IERC4626Like(m).asset() returns (address a) {
            is4626 = (a == asset);
        } catch {}

        try IDolomiteLike(m).baseToken() returns (address b) {
            isPool = (b == asset);
        } catch {}

        if (is4626 && isPool) revert AmbiguousMarketType(m);
        if (is4626) return MarketType.ERC4626;
        if (isPool) return MarketType.PoolLike;
        revert UnsupportedMarketType(m);
    }

    function toggleMarket(uint256 idx, bool en) external onlyRole(PARAM_ROLE) {
        require(idx < mkts.length, "idx");
        mkts[idx].enabled = en;
        emit MarketToggled(idx, en);
    }

    function flagMarket(uint256 idx, bool fl) external onlyRole(PARAM_ROLE) {
        require(idx < mkts.length, "idx");
        mkts[idx].flagged = fl;
        emit MarketFlagged(idx, fl);
    }

    function setRiskScore(uint256 idx, uint16 v) external onlyRole(PARAM_ROLE) {
        require(idx < mkts.length, "idx");
        require(v <= 10000, "score");
        mkts[idx].riskScoreBps = v;
        emit RiskScoreUpdated(idx, v);
    }

    function setCostsEstimates(uint16 slippageBps, uint16 withdrawalSpreadBps, uint256 gasCost)
        external
        onlyRole(PARAM_ROLE)
    {
        slippageBpsEstimate = slippageBps;
        withdrawalSpreadBpsEstimate = withdrawalSpreadBps;
        gasCostUSDC = gasCost;
        emit CostsEstimatesUpdated(slippageBps, withdrawalSpreadBps, gasCost);
    }

    function setOptimizeParams(
        uint32 minSecs,
        uint16 subMoveMinBps,
        uint16 subGateMinNetBenefitBps,
        uint16 driftTolBps_
    ) external onlyRole(PARAM_ROLE) {
        minSecondsBetweenOptimize = minSecs;
        rebalanceMinMoveBps = subMoveMinBps;
        gateMinNetBenefitBps = subGateMinNetBenefitBps;
        driftToleranceBps = driftTolBps_;
        emit OptimizeParamsUpdated(minSecs, subMoveMinBps, subGateMinNetBenefitBps, driftTolBps_);
    }

    function setCapacity(uint256 cap) external onlyRole(PARAM_ROLE) {
        capacity = cap;
        emit CapacityUpdated(cap);
    }

    function setWeights(
        uint16 _wAPY,
        uint16 _wLiq,
        uint16 _wRisk,
        uint16 _wStability,
        uint16 _wIncentive
    ) external onlyRole(PARAM_ROLE) {
        require(uint256(_wAPY) + _wLiq + _wRisk + _wStability + _wIncentive == 10000, "sum!=10000");
        wAPY = _wAPY;
        wLiq = _wLiq;
        wRisk = _wRisk;
        wStability = _wStability;
        wIncentive = _wIncentive;
        emit WeightsUpdated(_wAPY, _wLiq, _wRisk, _wStability, _wIncentive);
    }

    function setIncentiveBps(uint16 bps) external onlyRole(PARAM_ROLE) {
        incentiveBpsGlobal = bps;
    }

    function setAPYOverrideBps(uint16 bps) external onlyRole(PARAM_ROLE) {
        apyOverrideBps = bps;
    }

    function setRateProvider(address provider) external onlyRole(PARAM_ROLE) {
        require(provider != address(0), "zero address");
        rateProvider = provider;
        emit RateProviderUpdated(provider);
    }

    /// @notice Set Dolomite Margin USDC market ID (V9 fix)
    /// @param marketId The USDC market ID on Dolomite Margin (e.g., 17 on Arbitrum)
    function setUsdcMarketId(uint256 marketId) external onlyRole(PARAM_ROLE) {
        usdcMarketId = marketId;
        // Audit #2 P0.5 — invalidate config; activation requires an explicit
        // validateDolomiteConfig() call to pass.
        dolomiteConfigValid = false;
        emit DolomiteMarketIdUpdated(marketId);
    }

    /// @notice Set Dolomite account number (V9 fix)
    /// @param accNum The account number for getAccountWei (default 0)
    function setAccountNumber(uint256 accNum) external onlyRole(PARAM_ROLE) {
        accountNumber = accNum;
        dolomiteConfigValid = false;
        emit DolomiteAccountNumberUpdated(accNum);
    }

    /// @notice Audit #2 P0.5 — probe every enabled PoolLike market with the
    ///         current (usdcMarketId, accountNumber) tuple. If any call reverts,
    ///         the config is considered invalid and Margin-market accounting is
    ///         gated off until this function passes.
    function validateDolomiteConfig() external onlyRole(PARAM_ROLE) {
        uint256 n = mkts.length;
        for (uint256 i; i < n; ++i) {
            if (!mkts[i].enabled) continue;
            if (mkts[i].mtype != MarketType.PoolLike) continue;

            IDolomiteMargin.AccountInfo memory account =
                IDolomiteMargin.AccountInfo({ owner: address(this), number: accountNumber });

            try IDolomiteMargin(mkts[i].addr).getAccountWei(account, usdcMarketId) returns (
                IDolomiteMargin.Wei memory
            ) {
                // success — continue probing other markets
            } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                revert InvalidDolomiteConfig(mkts[i].addr, usdcMarketId, accountNumber);
            }
        }
        dolomiteConfigValid = true;
    }

    function pokeAPYSnapshots() external onlyRole(PARAM_ROLE) {
        uint256 n = mkts.length;
        uint64 nowTs = uint64(block.timestamp);
        for (uint256 i = 0; i < n; ++i) {
            Market storage m = mkts[i];
            if (!m.enabled) continue;
            if (m.mtype != MarketType.ERC4626) continue;
            uint256 pps = IERC4626Like(m.addr).convertToAssets(1e18);
            PpsRateLib.update(rateSamples[m.addr], IERC4626Like(m.addr).convertToAssets(1e24));
            ppsSnap[m.addr] = PpsSnap({ pps: pps, ts: nowTs });
        }
    }

    // ===== INTERNAL HELPERS =====

    /// @notice Sets just-in-time approval for a market operation
    /// @dev Prevents unlimited protocol exposure by approving only the required amount
    /// @param marketAddr The market address to approve
    /// @param amount The exact amount to approve
    function _approveMarket(address marketAddr, uint256 amount) internal {
        IERC20(asset).forceApprove(marketAddr, amount);
    }

    /// @notice Revokes approval for a market after operation
    /// @dev Security measure to prevent unlimited protocol exposure
    /// @param marketAddr The market address to revoke approval from
    function _revokeMarketApproval(address marketAddr) internal {
        IERC20(asset).forceApprove(marketAddr, 0);
    }

    // ===== Accounting Helpers =====

    // Assets currently held in a given market (in USDC)
    function _assetsOn(uint256 idx) internal view returns (uint256 assets) {
        Market storage m = mkts[idx];
        if (!m.enabled) return 0;
        assets = 0; // Initialize local variable (slither: uninitialized-local)
        if (m.mtype == MarketType.ERC4626) {
            uint256 shares = IERC20(m.addr).balanceOf(address(this));
            if (shares < 1) return 0; // slither: incorrect-equality - use < 1 instead of == 0
            assets = IERC4626Like(m.addr).convertToAssets(shares);
        } else {
            // Audit #2 P0.5 — no silent fallback to balanceOf(). PoolLike/Margin
            // markets MUST have a validated (usdcMarketId, accountNumber) config;
            // otherwise we return 0 rather than reading a wrong number.
            if (!dolomiteConfigValid) return 0;
            IDolomiteMargin.AccountInfo memory account =
                IDolomiteMargin.AccountInfo({ owner: address(this), number: accountNumber });
            try IDolomiteMargin(m.addr).getAccountWei(account, usdcMarketId) returns (
                IDolomiteMargin.Wei memory wei_
            ) {
                // sign=true means positive balance
                if (wei_.sign) {
                    assets = wei_.value;
                }
            } catch {
                // Config was validated earlier but now fails — surface as 0
                // and let the keeper/admin re-validate. Never fall back to
                // balanceOf() on a Margin market: that number is unrelated
                // to the actual position held in the vault.
                assets = 0;
            }
        }
    }

    // Withdrawable assets (in USDC) per market
    // Source of truth:
    //   - ERC4626 markets (e.g. dUSDC): use maxWithdraw(address(this)) which accounts for
    //     underlying market liquidity constraints. Fallback to min(assets, cash) if unavailable.
    //   - PoolLike markets: use min(assets, availableLiquidity) as before.
    function _withdrawableOn(uint256 idx) internal view returns (uint256) {
        Market storage m = mkts[idx];
        if (!m.enabled) return 0;

        if (m.mtype == MarketType.ERC4626) {
            // Prefer maxWithdraw() which accounts for underlying liquidity
            (bool success, bytes memory data) =
                m.addr.staticcall(abi.encodeWithSignature("maxWithdraw(address)", address(this)));
            if (success && data.length >= 32) {
                return abi.decode(data, (uint256));
            }
            // Fallback: min(assets, cash in vault)
            uint256 a = _assetsOn(idx);
            uint256 cash = IERC20(asset).balanceOf(m.addr);
            return a < cash ? a : cash;
        } else {
            // PoolLike: use existing pool liquidity check
            uint256 a = _assetsOn(idx);
            uint256 cash = IDolomiteLike(m.addr).availableLiquidity(asset);
            return a < cash ? a : cash;
        }
    }

    /// @dev Audit #2 P0.3 — max additional deposit a target market is willing to accept.
    ///      ERC4626: honour maxDeposit(receiver).
    ///      PoolLike: Dolomite Margin has no public cap on supply → effectively
    ///      unbounded, return type(uint256).max.
    function _maxAdditionalDeposit(uint256 idx) internal view returns (uint256) {
        Market storage m = mkts[idx];
        if (!m.enabled) return 0;

        if (m.mtype == MarketType.ERC4626) {
            (bool success, bytes memory data) =
                m.addr.staticcall(abi.encodeWithSignature("maxDeposit(address)", address(this)));
            if (success && data.length >= 32) {
                return abi.decode(data, (uint256));
            }
            return type(uint256).max;
        }
        return type(uint256).max;
    }

    // ===== ILendingAdapter Implementation =====

    function name() external pure returns (string memory) {
        return "Dolomite_USDC_MultiMarket_Adapter_Arbitrum";
    }

    /// @notice Returns false because Dolomite uses PULL deposit pattern
    /// @dev Adapter calls transferFrom() to pull USDC from Strategy during deposit()
    function isPushMode() external pure returns (bool) {
        return false;
    }

    function underlying() external view returns (address) {
        return asset;
    }

    function idleAssetBalance() public view returns (uint256) {
        return IERC20(asset).balanceOf(address(this));
    }

    function investedAssets() public view returns (uint256) {
        uint256 n = mkts.length;
        uint256 sum = 0; // Initialize local variable (slither: uninitialized-local)
        for (uint256 i = 0; i < n; ++i) {
            sum += _assetsOn(i);
        }
        return sum;
    }

    function totalAssets() public view returns (uint256) {
        return investedAssets() + idleAssetBalance();
    }

    function withdrawableAssets() public view returns (uint256) {
        uint256 n = mkts.length;
        uint256 sum = 0; // Initialize local variable (slither: uninitialized-local)
        for (uint256 i = 0; i < n; ++i) {
            sum += _withdrawableOn(i);
        }
        return sum;
    }

    mapping(address => PpsRateLib.Sample) internal rateSamples;
    function currentAPYBps() external view returns (uint16) {
        if (apyOverrideBps != 0) return apyOverrideBps;
        if (activeIdx < mkts.length && mkts[activeIdx].enabled
            && mkts[activeIdx].mtype == MarketType.ERC4626) {
            address m = mkts[activeIdx].addr;
            try IERC4626Like(m).convertToAssets(1e24) returns (uint256 pps) {
                return PpsRateLib.read(rateSamples[m], pps);
            } catch { return 0; }
        }
        // Else if Pool-like and rate provider configured, use provider
        if (
            activeIdx < mkts.length && mkts[activeIdx].enabled
                && mkts[activeIdx].mtype == MarketType.PoolLike && rateProvider != address(0)
        ) {
            address m = mkts[activeIdx].addr;
            uint256 rpsWad = IDolomiteRateProvider(rateProvider).getSupplyRatePerSecond(m);
            uint256 aprWad = rpsWad * 31_536_000; // seconds per year
            uint256 bps = aprWad / 1e14;
            if (bps > type(uint16).max) return type(uint16).max;
            // casting to uint16 is safe because overflow is checked above
            // forge-lint: disable-next-line(unsafe-typecast)
            return uint16(bps);
        }
        // Fallback
        return 0;
    }

    function incentiveAPYBps() external view returns (uint16) {
        return incentiveBpsGlobal;
    }

    function harvestableProfit() external pure returns (uint256) {
        return 0;
    }

    function harvest(address) external pure returns (uint256 realized) {
        return 0;
    }

    function maxCapacity() external view returns (uint256) {
        return capacity == 0 ? type(uint256).max : capacity;
    }

    /// @notice Returns sum of totalAssets() for ERC4626 markets, or USDC balance for PoolLike markets
    function externalMarketTVL() external view returns (uint256 total) {
        total = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (!mkts[i].enabled) continue;
            if (mkts[i].mtype == MarketType.ERC4626) {
                try IERC4626Like(mkts[i].addr).totalAssets() returns (uint256 ta) {
                    total += ta;
                } catch {
                    // skip failed market
                }
            } else {
                // PoolLike: use USDC balance as conservative proxy
                try IERC20(asset).balanceOf(mkts[i].addr) returns (uint256 bal) {
                    total += bal;
                } catch {
                    // skip failed market
                }
            }
        }
    }

    /// @notice Returns the recorded deposit principal for a market (telemetry/testing).
    function principalAt(uint256 idx) external view returns (uint256) {
        require(idx < mkts.length, "idx");
        return principal[idx];
    }

    /// @notice Returns the total recorded principal across all markets (telemetry/testing).
    function principalTotalValue() external view returns (uint256) {
        return principalTotal;
    }

    // ===== Lifecycle: No-custody =====

    function deposit(uint256 assets) external nonReentrant onlyVault {
        require(assets > 0, "ZERO_ASSETS");
        if (capacity > 0) require(totalAssets() + assets <= capacity, "CAP");
        IERC20(asset).safeTransferFrom(msg.sender, address(this), assets);

        uint256 idx = _pickTargetIndex();
        Market storage m = mkts[idx];
        // Gas: `m` is a storage pointer -- each `.addr`/`.mtype` access is its
        // own SLOAD. Nothing writes m.addr/m.mtype before line "principal[idx]
        // += assets" below, so caching is exact.
        address mktAddr = m.addr;
        MarketType mtype_ = m.mtype;

        _approveMarket(mktAddr, assets);
        if (mtype_ == MarketType.ERC4626) {
            // slither: unused-return - capture return value
            uint256 sharesMinted = IERC4626Like(mktAddr).deposit(assets, address(this));
            require(sharesMinted > 0, "Dolomite: deposit returned 0 shares");
        } else {
            IDolomiteLike(mktAddr).supply(asset, assets);
        }
        _revokeMarketApproval(mktAddr);

        principal[idx] += assets;
        principalTotal += assets;
        require(idx <= type(uint8).max, "DolomiteUsdcMultiMarket: idx overflow");
        // casting to uint8 is safe because overflow is checked above
        // forge-lint: disable-next-line(unsafe-typecast)
        activeIdx = uint8(idx);
        emit Supplied(assets, mktAddr);
    }

    function withdraw(
        uint256 assets,
        address /*receiver*/
    )
        external
        nonReentrant
        onlyVault
        returns (uint256 withdrawn)
    {
        require(assets > 0, "ZERO_ASSETS");
        uint256 want = assets;
        uint256 maxOut = withdrawableAssets();
        if (want > maxOut) want = maxOut;
        if (want < 1) return 0; // slither: incorrect-equality - use < 1 instead of == 0

        withdrawn = 0; // Initialize local variable (slither: uninitialized-local)
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n && want > 0; ++i) {
            if (!mkts[i].enabled) continue;
            uint256 can = _withdrawableOn(i);
            if (can < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
            uint256 take = can < want ? can : want;
            if (take < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0

            // HIGH-D-01: capture before the market call — ERC4626 interest accrual
            // increases assetsPerShare, so a flat deduction by `take` would understate
            // principal consumption; reduce proportionally to fraction of position withdrawn.
            uint256 assetsOnBefore = _assetsOn(i);
            Market storage m = mkts[i];
            if (m.mtype == MarketType.ERC4626) {
                // slither: unused-return - capture return value
                uint256 sharesBurned =
                    IERC4626Like(m.addr).withdraw(take, address(this), address(this));
                require(sharesBurned > 0 || take < 1, "Dolomite: withdraw returned 0 shares");
            } else {
                IDolomiteLike(m.addr).withdraw(asset, take);
            }

            IERC20(asset).safeTransfer(vault, take);

            uint256 reduction = assetsOnBefore > 0 ? (principal[i] * take) / assetsOnBefore : principal[i];
            principal[i] = principal[i] >= reduction ? principal[i] - reduction : 0;
            principalTotal = principalTotal >= reduction ? principalTotal - reduction : 0;

            withdrawn += take;
            emit Withdrawn(take, m.addr, vault);
            want -= take;
        }
        return withdrawn;
    }

    // ===== Optimize / Rebalance =====

    /// @notice Optimize allocation across markets, moving USDC from a worse to a better market if economic gates are satisfied.
    function optimize()
        external
        nonReentrant
        onlyVault
        returns (uint256 movedUSDC, address fromMarket, address toMarket)
    {
        require(block.timestamp >= lastOptimizeTs + minSecondsBetweenOptimize, "cooldown");

        (uint256 fromIdx, uint256 toIdx) = _bestRebalancePair();
        if (fromIdx == type(uint256).max || toIdx == type(uint256).max) {
            return (0, address(0), address(0));
        }
        if (mkts[toIdx].flagged) return (0, address(0), address(0));

        uint256 tvl = totalAssets();
        uint256 minMove = (tvl * rebalanceMinMoveBps) / 10000;
        uint256 movedPlan = minMove;
        uint256 withdrawableFrom = _withdrawableOn(fromIdx);
        if (movedPlan > withdrawableFrom) movedPlan = withdrawableFrom;

        // Audit #2 P0.3 — clamp by target capacity too, NOT only source.
        uint256 toRoom = _maxAdditionalDeposit(toIdx);
        if (movedPlan > toRoom) movedPlan = toRoom;

        // After clamps, re-check economic threshold — movePlan < minMove means the
        // target/source cannot accommodate a meaningful move this round.
        if (movedPlan < minMove || movedPlan < 1) {
            return (0, address(0), address(0));
        }

        int256 netBps = _estimateNetBenefitBps(fromIdx, toIdx, movedPlan, tvl);
        if (netBps < int256(uint256(gateMinNetBenefitBps))) return (0, address(0), address(0));

        // HIGH-D-01: capture before withdraw for proportional principal reduction
        uint256 fromAssetsOnBefore = _assetsOn(fromIdx);
        Market storage mf = mkts[fromIdx];
        Market storage mt = mkts[toIdx];

        // Withdraw from source market to adapter
        if (mf.mtype == MarketType.ERC4626) {
            // slither: unused-return - capture return value
            uint256 sharesBurned =
                IERC4626Like(mf.addr).withdraw(movedPlan, address(this), address(this));
            require(
                sharesBurned > 0 || movedPlan < 1, "Dolomite: optimize withdraw returned 0 shares"
            );
        } else {
            IDolomiteLike(mf.addr).withdraw(asset, movedPlan);
        }
        // Deposit into target market with just-in-time approval
        _approveMarket(mt.addr, movedPlan);
        if (mt.mtype == MarketType.ERC4626) {
            // slither: unused-return - capture return value
            uint256 sharesMinted = IERC4626Like(mt.addr).deposit(movedPlan, address(this));
            require(sharesMinted > 0, "Dolomite: optimize deposit returned 0 shares");
        } else {
            IDolomiteLike(mt.addr).supply(asset, movedPlan);
        }
        _revokeMarketApproval(mt.addr);

        // Update principal — HIGH-D-01: proportional reduction mirrors withdraw() fix
        uint256 fromReduction = fromAssetsOnBefore > 0
            ? (principal[fromIdx] * movedPlan) / fromAssetsOnBefore
            : principal[fromIdx];
        principal[fromIdx] = principal[fromIdx] >= fromReduction ? principal[fromIdx] - fromReduction : 0;
        principal[toIdx] += movedPlan;
        require(toIdx <= type(uint8).max, "DolomiteUsdcMultiMarket: toIdx overflow");
        require(block.timestamp <= type(uint64).max, "DolomiteUsdcMultiMarket: timestamp overflow");
        // casting to uint8 and uint64 is safe because overflow is checked above
        // forge-lint: disable-next-line(unsafe-typecast)
        activeIdx = uint8(toIdx);
        // forge-lint: disable-next-line(unsafe-typecast)
        lastOptimizeTs = uint64(block.timestamp);

        emit IntraRebalanced(mf.addr, mt.addr, movedPlan);
        return (movedPlan, mf.addr, mt.addr);
    }

    // ===== Scoring and Rebalance Helpers =====

    // Picks the target market for new deposits. Prefer activeIdx if valid, else best by score.
    function _pickTargetIndex() internal view returns (uint256 idx) {
        uint256 n = mkts.length;
        if (n == 0) revert("no markets");
        if (activeIdx < n && mkts[activeIdx].enabled && !mkts[activeIdx].flagged) return activeIdx;

        uint256 bestScore = 0;
        uint256 bestIdx = type(uint256).max;
        for (uint256 i = 0; i < n; ++i) {
            if (!mkts[i].enabled || mkts[i].flagged) continue;
            uint256 s = _score(i);
            if (s > bestScore) {
                bestScore = s;
                bestIdx = i;
            }
        }
        require(bestIdx != type(uint256).max, "no enabled market");
        return bestIdx;
    }

    // Compute the composite score (0..1e8) for a market
    function _score(uint256 idx) internal view returns (uint256) {
        Market storage m = mkts[idx];
        if (!m.enabled) return 0;

        // APY: If not available, treat as 0. (Can be extended in future)
        uint16 apyBps = m.lastAPYBps;
        uint16 apyNorm = apyBps; // Already in 0..10000

        // Liquidity: availableLiquidity / (availableLiquidity + allocOnMarket), scaled to 0..10000
        uint256 alloc = _assetsOn(idx);
        uint256 liq;
        if (m.mtype == MarketType.ERC4626) {
            liq = IERC20(asset).balanceOf(m.addr);
        } else {
            // Guarded external call: a single reverting/paused Dolomite pool must
            // not brick scoring for every other healthy market. A failure here is
            // treated as zero available liquidity for this market (score naturally
            // drops toward 0), not a revert of the whole deposit()/optimize() call.
            try IDolomiteLike(m.addr).availableLiquidity(asset) returns (uint256 l) {
                liq = l;
            } catch {
                return 0;
            }
        }
        uint16 liqBps = (liq + alloc < 1) ? 0 : uint16((liq * 10000) / (liq + alloc)); // slither: incorrect-equality - use < 1 instead of == 0

        // Risk: 10000 - riskScoreBps (higher = riskier)
        uint16 riskBps = 10000 - m.riskScoreBps;

        // Stability: use lastAPYBps as a proxy (normalized)
        uint16 stabBps = m.lastAPYBps;

        // Incentive: global param, normalized
        uint16 incBps = incentiveBpsGlobal;

        // Weighted sum (all in bps, so score is 0..1e8)
        uint256 score = uint256(wAPY) * apyNorm + uint256(wLiq) * liqBps + uint256(wRisk) * riskBps
            + uint256(wStability) * stabBps + uint256(wIncentive) * incBps;
        return score;
    }

    // Find the best rebalance pair (fromIdx, toIdx)
    function _bestRebalancePair() internal view returns (uint256 fromIdx, uint256 toIdx) {
        uint256 n = mkts.length;
        uint256 worstScore = type(uint256).max;
        uint256 bestScore = 0;
        fromIdx = type(uint256).max;
        toIdx = type(uint256).max;

        for (uint256 i = 0; i < n; ++i) {
            if (!mkts[i].enabled) continue;
            uint256 s = _score(i);
            if (s < worstScore && _withdrawableOn(i) > 0 && !mkts[i].flagged) {
                worstScore = s;
                fromIdx = i;
            }
            if (s > bestScore && !mkts[i].flagged) {
                bestScore = s;
                toIdx = i;
            }
        }
        // Don't rebalance if best==worst or no valid pairs
        if (fromIdx == toIdx) {
            fromIdx = type(uint256).max;
            toIdx = type(uint256).max;
        }
    }

    // Estimate net benefit in bps for a move
    function _estimateNetBenefitBps(
        uint256 fromIdx,
        uint256 toIdx,
        uint256 movedAmount,
        uint256 /* tvl */
    )
        internal
        view
        returns (int256)
    {
        // Use lastAPYBps as proxy for APY
        uint16 apyFrom = mkts[fromIdx].lastAPYBps;
        uint16 apyTo = mkts[toIdx].lastAPYBps;

        if (apyTo <= apyFrom) return -1; // No benefit

        uint256 deltaAPY = uint256(apyTo - apyFrom); // bps

        // Gross benefit: movedAmount * deltaAPY/10000 * (gateHorizonDays/365)
        uint256 grossBenefit = (movedAmount * deltaAPY * gateHorizonDays) / (10000 * 365);

        // Move cost: gas + slippage + withdrawal spread
        uint256 moveCost = gasCostUSDC
            + (movedAmount * (slippageBpsEstimate + withdrawalSpreadBpsEstimate)) / 10000;

        // Net benefit per movedAmount, in bps
        if (movedAmount < 1) return -1; // slither: incorrect-equality - use < 1 instead of == 0
        require(
            grossBenefit <= uint256(type(int256).max),
            "DolomiteUsdcMultiMarket: grossBenefit overflow"
        );
        require(moveCost <= uint256(type(int256).max), "DolomiteUsdcMultiMarket: moveCost overflow");
        require(
            movedAmount <= uint256(type(int256).max),
            "DolomiteUsdcMultiMarket: movedAmount overflow"
        );
        // casting to int256 is safe because overflow is checked above
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 netBenefit = int256(grossBenefit) - int256(moveCost);
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 netBenefitBps = (netBenefit * 10000) / int256(movedAmount);

        return netBenefitBps;
    }

