    // ===== Registry Integration =====

    function _loadFromRegistry() internal {
        try registry.getEnabledVaults(IProtocolRegistry.ProtocolType.DOLOMITE) returns (
            address[] memory vaults
        ) {
            for (uint256 i = 0; i < vaults.length; i++) {
                if (vaults[i] != address(0)) {
                    bool isERC4626 = _tryERC4626(vaults[i]);
                    if (isERC4626) {
                        mkts.push(
                            Market({
                                addr: vaults[i],
                                mtype: MarketType.ERC4626,
                                enabled: true,
                                flagged: false,
                                riskScoreBps: 10000,
                                lastAPYBps: 0
                            })
                        );
                        principal.push(0);
                    } else {
                        // Hardening: only accept PoolLike if baseToken() exists and matches adapter asset.
                        // Prevents misconfigured registrations (e.g. DolomiteMargin) from entering mkts.
                        (bool ok, address base) = _tryPoolLike(vaults[i]);
                        if (ok && base == asset) {
                            mkts.push(
                                Market({
                                    addr: vaults[i],
                                    mtype: MarketType.PoolLike,
                                    enabled: true,
                                    flagged: false,
                                    riskScoreBps: 10000,
                                    lastAPYBps: 0
                                })
                            );
                            principal.push(0);
                        }
                    }
                }
            }
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            // Registry call failed - adapter will start with empty markets
        }
    }

    function _tryERC4626(address vaultAddr) internal view returns (bool) {
        try IERC4626Like(vaultAddr).asset() returns (address assetAddr) {
            // Return true if asset call succeeds (assetAddr captured for slither)
            return assetAddr != address(0);
        } catch {
            return false;
        }
    }

    function _tryPoolLike(address vaultAddr) internal view returns (bool ok, address base) {
        try IDolomiteLike(vaultAddr).baseToken() returns (address b) {
            return (true, b);
        } catch {
            return (false, address(0));
        }
    }

    function refreshFromRegistry() external onlyRole(PARAM_ROLE) {
        require(address(registry) != address(0), "no registry");
        delete mkts;
        delete principal;
        _loadFromRegistry();
    }

    // ===== Idle Asset & Emergency Recovery =====
    event IdleAssetSwept(uint256 amount);
    event EmergencyPullExecuted(uint256 amount);
    /// @dev SLITHER-FIX-5: per-market withdraw outcome captured for incident-response observability.
    event EmergencyDolomiteMarketWithdrawn(uint256 indexed marketIdx, address indexed market, uint8 mtype, uint256 requested, uint256 sharesBurned);

    function sweepIdleAssetToVault() external nonReentrant onlyVault {
        uint256 idle = IERC20(asset).balanceOf(address(this));
        require(idle > 0, "no idle");
        IERC20(asset).safeTransfer(vault, idle);
        emit IdleAssetSwept(idle);
    }

    function emergencyPullAllToVault() external nonReentrant onlyVault {
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (!mkts[i].enabled) continue;
            uint256 bal = _assetsOn(i);
            if (bal > 0) {
                Market storage m = mkts[i];
                if (m.mtype == MarketType.ERC4626) {
                    try IERC4626Like(m.addr).withdraw(bal, address(this), address(this)) returns (uint256 _sharesBurned) {
                        emit EmergencyDolomiteMarketWithdrawn(i, m.addr, uint8(m.mtype), bal, _sharesBurned);
                    } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                        emit EmergencyDolomiteMarketWithdrawn(i, m.addr, uint8(m.mtype), bal, 0);
                    }
                } else {
                    try IDolomiteLike(m.addr).withdraw(asset, bal) {
                        emit EmergencyDolomiteMarketWithdrawn(i, m.addr, uint8(m.mtype), bal, 0);
                    } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                        emit EmergencyDolomiteMarketWithdrawn(i, m.addr, uint8(m.mtype), bal, 0);
                    }
                }
                principal[i] = 0;
            }
        }
        principalTotal = 0;
        // Transfer FULL balance (withdrawn + any pre-existing idle) to vault
        uint256 fullBalance = IERC20(asset).balanceOf(address(this));
        if (fullBalance > 0) {
            IERC20(asset).safeTransfer(vault, fullBalance);
        }
        emit EmergencyPullExecuted(fullBalance);
    }

    // ===== Fallback =====
    receive() external payable {
        revert("NO_NATIVE");
    }

    fallback() external payable {
        revert("NO_FALLBACK");
    }
    event AdapterOperationFailed(bytes4 indexed operation, bytes reason);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

// OpenZeppelin imports
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";

/// @notice Minimal interface for protocol registry
interface IProtocolRegistry {
    enum ProtocolType {
        AAVE_V3,
        EULER_V2,
        MORPHO,
        COMPOUND_V3,
        DOLOMITE,
        GAINS,
        SILO_V2
    }
    function getEnabledVaults(ProtocolType protocol) external view returns (address[] memory);
    function isEnabled(ProtocolType protocol, address vault) external view returns (bool);
}

/// @notice Minimal interface for Euler USDC markets (EVault interface)
interface IEulerUsdcMarket {
    function deposit(uint256 assets, address receiver) external returns (uint256);
    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256);
    function balanceOf(address account) external view returns (uint256); // shares
    function convertToAssets(uint256 shares) external view returns (uint256); // convert shares to assets
    function maxWithdraw(address owner) external view returns (uint256); // max withdrawable assets
    function maxDeposit(address receiver) external view returns (uint256); // max depositable assets (supply cap)
    function interestRate() external view returns (uint256); // APY in 1e27 scaling (ray)
    function asset() external view returns (address); // underlying asset (USDC)
    function totalAssets() external view returns (uint256); // total USDC deposited in vault
}

/// @notice Lending Adapter interface for Vault integration
interface ILendingAdapter {
    function name() external view returns (string memory);
    function underlying() external view returns (address);
    function totalAssets() external view returns (uint256);
    function withdrawableAssets() external view returns (uint256);
    function deposit(uint256 assets) external;
    function withdraw(uint256 assets, address receiver) external returns (uint256 withdrawn);
    function currentAPYBps() external view returns (uint16);
    function incentiveAPYBps() external view returns (uint16);
    function harvestableProfit() external view returns (uint256);
    function harvest(address receiver) external returns (uint256 realized);
    function maxCapacity() external view returns (uint256);

    // external TVL
    function externalMarketTVL() external view returns (uint256);

    // Extensions
    function optimize() external returns (uint256 movedUSDC, address fromMarket, address toMarket);
    function markets() external view returns (address[] memory);
    function activeMarket() external view returns (address);
    function positions() external view returns (uint256[] memory assetsByMarket);
    function effectiveAPYBps() external view returns (uint16);
}

/// @dev Minimal Permit2 AllowanceTransfer interface (Euler EVK requires internal allowance)
interface IPermit2Allowance {
    function allowance(address owner, address token, address spender)
        external
        view
        returns (uint160 amount, uint48 expiration, uint48 nonce);

    function approve(address token, address spender, uint160 amount, uint48 expiration) external;
}

contract EulerUsdcMultiMarketAdapter is ILendingAdapter, AccessControl, ReentrancyGuard, Initializable {
    using SafeERC20 for IERC20Metadata;

    // --- STRUCTS & STORAGE ---

    struct Market {
        address addr;
        bool enabled;
        bool flagged;
        uint16 riskScoreBps;
    }

    // Roles
    bytes32 public constant PARAM_ROLE = keccak256("PARAM_ROLE");

    // Permit2 canonical address (AllowanceTransfer — used by Euler EVK)
    address internal constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    uint48 internal constant PERMIT2_MIN_TTL = uint48(1 days);
    uint48 internal constant PERMIT2_TTL = uint48(365 days * 10); // 10y — safe for EVK

    // --- V10 Storage (was immutable in V9.x; logically immutable post-initialize) ---
    IERC20Metadata public USDC;
    address public vault;
    IProtocolRegistry public registry; // Optional registry (address(0) if not used)

    Market[] internal mkts; // Dynamic array - can grow with Registry updates
    uint256[] internal principal; // principal[i]: USDC (6 decimals)
    uint256 internal principalTotal;

    uint32 public minSecondsBetweenOptimize = 3 hours;
    uint16 public subMoveMinBps = 25; // 0.25%
    uint16 public subGateMinNetBenefitBps = 2; // 0.02%
    uint16 public slippageBpsEstimate = 3;
    uint16 public withdrawalSpreadBpsEstimate = 2;
    uint256 public gasCostUSDC = 0;
    uint256 public capacity = 0; // 0 = unlimited
    uint256 public lastOptimizeTs;

    // --- EVENTS ---

    event Deposited(address indexed market, uint256 assets);
    event MarketSkippedLowCapacity(address indexed market, uint256 capacity);
    event MarketSelectionFallback(address indexed failedMarket, address indexed fallbackMarket);
    event DepositCapped(address indexed market, uint256 requested, uint256 capped);
    event Withdrawn(
        address indexed market, uint256 asked, uint256 withdrawn, address indexed receiver
    );
    event Harvested(uint256 profitUSDC);
    event IntraRebalanced(address indexed fromMarket, address indexed toMarket, uint256 movedUSDC);

    event MarketToggled(uint256 indexed idx, address market, bool enabled, bool flagged);
    event MarketAddressUpdated(uint256 indexed idx, address oldMarket, address newMarket);
    event RiskScoreUpdated(uint256 indexed idx, uint16 riskScoreBps);

    event CostsEstimatesUpdated(
        uint16 slippageBps, uint16 withdrawalSpreadBps, uint256 gasCostUSDC
    );
    event OptimizeParamsUpdated(
        uint32 minSecondsBetweenOptimize, uint16 subMoveMinBps, uint16 subGateMinNetBenefitBps
    );
    event CapacityUpdated(uint256 capacity);
    event Permit2AllowanceRefreshed(address indexed vault, uint160 amount, uint48 expiration);
    event IdleAssetSwept(uint256 amount);
    event EmergencyPullExecuted(uint256 amount);

    // --- MODIFIERS ---

    modifier onlyVault() {
        require(msg.sender == vault, "Only vault");
        _;
    }

    modifier onlyParamRole() {
        require(hasRole(PARAM_ROLE, msg.sender), "Only param role");
        _;
    }

    // --- CONSTRUCTOR ---


    /// @notice One-shot initialization called atomically by AdapterFactory.
    /// @dev _admin is explicit because msg.sender in initialize() = AdapterFactory, not deployer.
    function initialize(
        address _vault,
        address _usdc,
        address[] memory _markets,
        address _registry,
        address _admin
    ) external initializer {
        require(_vault != address(0), "vault zero");
        require(_usdc != address(0), "usdc zero");
        require(_admin != address(0), "admin zero");

        USDC = IERC20Metadata(_usdc);
        vault = _vault;
        registry = IProtocolRegistry(_registry); // Can be address(0)

        // Validate and initialize markets from constructor array
        uint256 marketCount = _markets.length;
        for (uint256 i = 0; i < marketCount; ++i) {
            require(_markets[i] != address(0), "market zero");
            for (uint256 j = 0; j < i; ++j) {
                require(_markets[i] != _markets[j], "market dup");
            }
            mkts.push(Market({ addr: _markets[i], enabled: true, flagged: false, riskScoreBps: 0 }));
            principal.push(0);
        }

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(PARAM_ROLE, _admin);

        // Approve Permit2 for Euler EVK vaults (one-time unlimited approval)
        // Euler vaults use Permit2 internally during deposit() -- this is REQUIRED.
        USDC.forceApprove(PERMIT2, type(uint256).max);

        // Auto-load from registry if available (will replace constructor markets)
        if (_registry != address(0)) {
            _loadFromRegistry();
        }

        // V9 FIX: HARDENING - Revert if no markets loaded
        // This prevents deployment of a non-functional adapter
        require(
            mkts.length > 0, "EulerAdapter: no markets - registry required or pass _markets array"
        );
    }

    // --- MARKET INITIALIZATION ---

    /// @notice Initialize Permit2 allowances for all markets (call BEFORE role transfer)
    /// @dev Sets Permit2 internal allowance for each market. Must be called after
    ///      constructor and before admin roles are transferred to Timelock.
    ///      This separates Permit2 setup from the deposit flow (see v7-euler-fix-report.md).
    function initializeMarkets() external onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 len = mkts.length;
        for (uint256 i = 0; i < len; i++) {
            if (mkts[i].addr == address(0)) continue;
            _ensurePermit2(mkts[i].addr);
        }
        emit MarketsInitialized(len);
    }

    event MarketsInitialized(uint256 marketCount);

    // --- INTERNAL HELPERS ---

    /// @notice Sets just-in-time approval for a market operation
    /// @dev Prevents unlimited protocol exposure by approving only the required amount
    /// @param marketAddr The market address to approve
    /// @param amount The exact amount to approve
    function _approveMarket(address marketAddr, uint256 amount) internal {
        USDC.forceApprove(marketAddr, amount);
    }

    /// @notice Revokes approval for a market after operation
    /// @dev Security measure to prevent unlimited protocol exposure
    /// @param marketAddr The market address to revoke approval from
    function _revokeMarketApproval(address marketAddr) internal {
        USDC.forceApprove(marketAddr, 0);
    }

    /// @dev Ensures Permit2 internal allowance is active for a given Euler vault.
    ///      Idempotent: only calls approve if allowance is low or expired.
    ///      Euler EVK uses Permit2.transferFrom internally during deposit.
    function _ensurePermit2(address eulerVault) internal {
        if (eulerVault == address(0)) return;

        (uint160 amt, uint48 exp,) =
            IPermit2Allowance(PERMIT2).allowance(address(this), address(USDC), eulerVault);

        uint48 nowTs = uint48(block.timestamp);
        uint48 wantedExp = nowTs + PERMIT2_TTL;

        // Refresh if: amount too low OR expired/expiring within PERMIT2_MIN_TTL
        if (amt < type(uint160).max / 2 || exp < nowTs + PERMIT2_MIN_TTL) {
            IPermit2Allowance(PERMIT2)
                .approve(address(USDC), eulerVault, type(uint160).max, wantedExp);
            emit Permit2AllowanceRefreshed(eulerVault, type(uint160).max, wantedExp);
        }
    }

    // Dust amount for market activation. Must produce >= 1 share.
    // 1 wei = 0 shares at current Euler exchange rates (E_ZeroShares).
    // 100 wei (0.0001 USDC) safely produces shares at any reasonable rate.
    uint256 private constant POKE_DUST = 100;

    /// @notice Initializes a market with a dust deposit to activate it
    /// @dev Euler vaults require initialization before they can be queried
    /// @param idx Market index to poke
    /// @return success True if market was successfully activated
    function _pokeMarket(uint256 idx) internal returns (bool success) {
        if (idx >= mkts.length) return false;

        // Audit #2 P1.8 — check maxDeposit BEFORE attempting dust deposit.
        // If the market's supply cap is hit (maxDeposit == 0), skip immediately
        // rather than wasting gas on a guaranteed-to-fail ERC4626 deposit.
        try IEulerUsdcMarket(mkts[idx].addr).maxDeposit(address(this)) returns (uint256 maxDep) {
            if (maxDep == 0) {
                emit MarketSkippedLowCapacity(mkts[idx].addr, 0);
                return false;
            }
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            // maxDeposit() not available or reverted — skip this market.
            emit MarketSkippedLowCapacity(mkts[idx].addr, 0);
            return false;
        }

        // Check if we have enough USDC for dust deposit
        uint256 bal = USDC.balanceOf(address(this));
        if (bal < POKE_DUST) return false;

        // Ensure Permit2 internal allowance, then approve and deposit dust amount
        _ensurePermit2(mkts[idx].addr);
        _approveMarket(mkts[idx].addr, POKE_DUST);

        // Try dust deposit — needs enough to produce >= 1 share
        try IEulerUsdcMarket(mkts[idx].addr).deposit(POKE_DUST, address(this)) returns (uint256 shares) {
            if (shares < 1) { } // intentionally empty - we just need non-zero to confirm
            _revokeMarketApproval(mkts[idx].addr);
            return true;
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            _revokeMarketApproval(mkts[idx].addr);
            return false;
        }
    }

    function _balanceInUnderlying(uint256 i) internal view returns (uint256) {
        // Euler EVault uses ERC4626 standard: balanceOf returns shares, convertToAssets converts to underlying
        // Use low-level staticcall to avoid try-catch gas issues
        (bool success1, bytes memory data1) =
            mkts[i].addr.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));

        if (!success1 || data1.length < 32) {
            return 0;
        }

        uint256 shares = abi.decode(data1, (uint256));
        if (shares < 1) {
            // slither: incorrect-equality - use < 1 instead of == 0
            return 0;
        }

        (bool success2, bytes memory data2) =
            mkts[i].addr.staticcall(abi.encodeWithSignature("convertToAssets(uint256)", shares));

        if (!success2 || data2.length < 32) {
            return 0;
        }

        return abi.decode(data2, (uint256));
    }

    function _liquidity(uint256 i) internal view returns (uint256) {
        // maxWithdraw returns the maximum amount of assets that can be withdrawn
        // Use low-level staticcall to avoid try-catch gas issues
        (bool success, bytes memory data) =
            mkts[i].addr.staticcall(abi.encodeWithSignature("maxWithdraw(address)", address(this)));

        if (!success || data.length < 32) {
            return 0;
        }

        return abi.decode(data, (uint256));
    }

    function _supplyAPYBps(uint256 i) internal view returns (uint16) {
        // Euler interestRate() returns borrow rate (SPY) in 1e27 scaling (RAY format)
        // We need to calculate supply APY = borrow APY × utilization × (1 - fee)
        // Use low-level staticcall to avoid try-catch gas issues in view functions

        // Get borrow rate (interestRate)
        (bool success1, bytes memory data1) =
            mkts[i].addr.staticcall(abi.encodeWithSignature("interestRate()"));
        if (!success1 || data1.length < 32) {
            return 0;
        }
        uint256 borrowRateSPY = abi.decode(data1, (uint256));

        // Get total borrows
        (bool success2, bytes memory data2) =
            mkts[i].addr.staticcall(abi.encodeWithSignature("totalBorrows()"));
        if (!success2 || data2.length < 32) {
            return 0;
        }
        uint256 totalBorrows = abi.decode(data2, (uint256));

        // Get total assets
        (bool success3, bytes memory data3) =
            mkts[i].addr.staticcall(abi.encodeWithSignature("totalAssets()"));
        if (!success3 || data3.length < 32) {
            return 0;
        }
        uint256 vaultTotalAssets = abi.decode(data3, (uint256));

        // Get interest fee
        (bool success4, bytes memory data4) =
            mkts[i].addr.staticcall(abi.encodeWithSignature("interestFee()"));
        if (!success4 || data4.length < 32) {
            return 0;
        }
        uint256 interestFee = abi.decode(data4, (uint256));

        // Avoid division by zero
        if (vaultTotalAssets < 1) {
            // slither: incorrect-equality - use < 1 instead of == 0
            return 0;
        }

        // Calculate borrow APY in bps
        // SPY to annual: borrowRateSPY / 3,168,808,781,402,895
        uint256 borrowAPYBps = borrowRateSPY / 3_168_808_781_402_895;

        // Calculate utilization rate in WAD (1e18)
        // utilization = totalBorrows / vaultTotalAssets
        uint256 utilizationWAD = (totalBorrows * 1e18) / vaultTotalAssets;

        // Calculate supply APY = borrow APY × utilization × (1 - fee)
        // fee is in basis points (10000 = 100%)
        // supply APY = borrowAPY × utilization × (10000 - fee) / 10000
        uint256 supplyAPYBps =
            (borrowAPYBps * utilizationWAD * (10000 - interestFee)) / (1e18 * 10000);

        // Cap at uint16 max to prevent overflow
        // forge-lint: disable-next-line(unsafe-typecast)
        uint16 apyBps = supplyAPYBps > type(uint16).max ? type(uint16).max : uint16(supplyAPYBps);
        return apyBps;
    }

    /// @dev Minimum deposit capacity for a market to be eligible.
    ///      Markets with capacity below this are skipped (avoids partial fills on tiny caps).
    uint256 public minMarketCapacity = 1e6; // 1 USDC default

    /// @notice Set minimum market capacity for target selection
    function setMinMarketCapacity(uint256 _min) external onlyRole(PARAM_ROLE) {
        minMarketCapacity = _min;
    }

    /// @dev View-safe target market selection (no events, for view functions)
    function _targetMarket() internal view returns (uint256 idx, bool found) {
        return _targetMarketView(0);
    }

    /// @dev View-safe: find best market with capacity (no events)
    function _targetMarketView(uint256 excludeUpTo) internal view returns (uint256 idx, bool found) {
        uint16 bestAPY = 0;
        idx = 0;
        found = false;
        uint256 n = mkts.length;
        uint256 _minCap = minMarketCapacity;
        for (uint256 i = 0; i < n; ++i) {
            if (excludeUpTo > 0 && i < excludeUpTo) continue;
            if (mkts[i].enabled && !mkts[i].flagged) {
                uint256 maxDep = IEulerUsdcMarket(mkts[i].addr).maxDeposit(address(this));
                if (maxDep < _minCap) continue;
                uint16 apy = _supplyAPYBps(i);
                if (!found || apy > bestAPY) {
                    bestAPY = apy;
                    idx = i;
                    found = true;
                }
            }
        }
    }

    /// @dev Non-view: find best market with capacity + emit skip events
    function _targetMarketWithEvents(uint256 excludeUpTo) internal returns (uint256 idx, bool found) {
        uint16 bestAPY = 0;
        idx = 0;
        found = false;
        uint256 n = mkts.length;
        uint256 _minCap = minMarketCapacity;
        for (uint256 i = 0; i < n; ++i) {
            if (excludeUpTo > 0 && i < excludeUpTo) continue;
            if (mkts[i].enabled && !mkts[i].flagged) {
                uint256 maxDep = IEulerUsdcMarket(mkts[i].addr).maxDeposit(address(this));
                if (maxDep < _minCap) {
                    emit MarketSkippedLowCapacity(mkts[i].addr, maxDep);
                    continue;
                }
                uint16 apy = _supplyAPYBps(i);
                if (!found || apy > bestAPY) {
                    bestAPY = apy;
                    idx = i;
                    found = true;
                }
            }
        }
    }

    function _activeMarketIdx() internal view returns (uint256 idx, bool found) {
        // Market with max position
        uint256 maxBal = 0;
        idx = 0; // Initialize return variable (slither: uninitialized-local)
        found = false; // Initialize return variable
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            uint256 bal = _balanceInUnderlying(i);
            if (bal > 0 && (!found || bal > maxBal)) {
                maxBal = bal;
                idx = i;
                found = true;
            }
        }
        return (idx, found);
    }

    // --- INTERFACE IMPLEMENTATION ---

    function name() external pure override returns (string memory) {
        return "Euler USDC Multi-Market Adapter";
    }

    /// @notice Returns true because Euler uses PUSH deposit pattern
    /// @dev Strategy must transfer USDC to this adapter BEFORE calling deposit()
    function isPushMode() external pure returns (bool) {
        return true;
    }

    function underlying() external view override returns (address) {
        return address(USDC);
    }

    function idleAssetBalance() public view returns (uint256) {
        return USDC.balanceOf(address(this));
    }

    function investedAssets() public view returns (uint256) {
        uint256 sum = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            sum += _balanceInUnderlying(i);
        }
        return sum;
    }

    function totalAssets() public view override returns (uint256) {
        return investedAssets() + idleAssetBalance();
    }

    function withdrawableAssets() public view override returns (uint256) {
        // If only one market has position: min(balance, liquidity)
        uint256 nPos = 0;
        uint256 lastIdx = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (_balanceInUnderlying(i) > 0) {
                nPos++;
                lastIdx = i;
            }
        }
        if (nPos == 1) {
            uint256 bal = _balanceInUnderlying(lastIdx);
            uint256 liq = _liquidity(lastIdx);
            return bal < liq ? bal : liq;
        }
        // Else: sum min(balance, liquidity) over all markets with position
        uint256 sum = 0;
        for (uint256 i = 0; i < n; ++i) {
            uint256 bal = _balanceInUnderlying(i);
            if (bal > 0) {
                uint256 liq = _liquidity(i);
                sum += bal < liq ? bal : liq;
            }
        }
        return sum;
    }

    function deposit(uint256 assets) external override nonReentrant onlyVault {
        require(assets > 0, "zero assets");
        if (capacity != 0) {
            require(totalAssets() + assets <= capacity, "capacity");
        }

        // USDC must be pre-transferred to this contract by Vault
        bool deposited = _tryDepositToMarket(assets, 0); // 0 = no exclusion

        if (!deposited) {
            revert("Deposit failed - no market with sufficient capacity");
        }
    }

    /// @dev Try to deposit into the best available market. If it fails, retry with next best.
    ///      Fix 2: clamps deposit to maxDeposit. Fix 3: retry fallback on failure.
    function _tryDepositToMarket(uint256 assets, uint256 excludeIdx) internal returns (bool) {
        (uint256 targetIdx, bool found) = _targetMarketWithEvents(excludeIdx);
        if (!found) return false;
        require(mkts[targetIdx].enabled && !mkts[targetIdx].flagged, "target not allowed");

        // Gas: `mkts[targetIdx].addr` was re-read from storage up to 13x in
        // this function (each `mkts[targetIdx].addr` recomputes the array's
        // keccak-derived slot + a fresh SLOAD). Nothing in this function --
        // including _pokeMarket(targetIdx), which only reads market state --
        // writes mkts[targetIdx].addr, so caching it once is exact.
        address mktAddr = mkts[targetIdx].addr;

        // Fix 2: Clamp deposit to market's available capacity
        uint256 maxDep = IEulerUsdcMarket(mktAddr).maxDeposit(address(this));
        uint256 amountToDeposit = assets;
        if (amountToDeposit > maxDep) {
            amountToDeposit = maxDep;
            emit DepositCapped(mktAddr, assets, amountToDeposit);
        }
        if (amountToDeposit == 0) return false;

        // Ensure Permit2 internal allowance + standard approval
        _ensurePermit2(mktAddr);
        _approveMarket(mktAddr, amountToDeposit);

        // Try deposit
        try IEulerUsdcMarket(mktAddr).deposit(amountToDeposit, address(this)) returns (
            uint256 sharesMinted
        ) {
            if (sharesMinted < 1) { } // slither: intentionally empty
            _revokeMarketApproval(mktAddr);

            // Update accounting
            principal[targetIdx] += amountToDeposit;
            principalTotal += amountToDeposit;
            emit Deposited(mktAddr, amountToDeposit);

            // If we capped and have remaining, try next market
            uint256 remaining = assets - amountToDeposit;
            if (remaining > 0) {
                // Recursive retry with next best market (exclude current)
                // Uses 1-based index to distinguish from "no exclusion" (0)
                _tryDepositToMarket(remaining, targetIdx + 1);
                // If remaining deposit fails, that's OK — we already deposited the capped amount
            }
            return true;
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            // Fix 3: Retry fallback — try poke first, then next market
            _revokeMarketApproval(mktAddr);

            bool poked = _pokeMarket(targetIdx);
            if (poked) {
                // Retry same market after poke
                _approveMarket(mktAddr, amountToDeposit);
                try IEulerUsdcMarket(mktAddr).deposit(amountToDeposit, address(this)) returns (
                    uint256 retryShares
                ) {
                    if (retryShares < 1) { } // slither: intentionally empty
                    _revokeMarketApproval(mktAddr);
                    principal[targetIdx] += amountToDeposit;
                    principalTotal += amountToDeposit;
                    emit Deposited(mktAddr, amountToDeposit);
                    return true;
                } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                    _revokeMarketApproval(mktAddr);
                }
            }

            // Fallback to next best market
            emit MarketSelectionFallback(mktAddr, address(0));
            return _tryDepositToMarket(assets, targetIdx + 1);
        }
    }

    function withdraw(uint256 assets, address receiver)
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 withdrawn)
    {
        require(assets > 0, "zero assets");
        require(receiver == vault, "receiver must be vault");

        withdrawn = 0; // Initialize return variable (slither: uninitialized-local)
        uint256 assetsLeft = assets;
        uint256 totalWithdrawn = 0;
        uint256 n = mkts.length;
        uint256[] memory balancesBefore = new uint256[](n);
        for (uint256 i = 0; i < n; ++i) {
            balancesBefore[i] = _balanceInUnderlying(i);
        }
        // Try from active market first, then others
        (uint256 actIdx,) = _activeMarketIdx();
        for (uint256 pass = 0; pass < 2 && assetsLeft > 0; ++pass) {
            for (uint256 i = 0; i < n && assetsLeft > 0; ++i) {
                if ((pass == 0 && i != actIdx) || (pass == 1 && i == actIdx)) continue;
                uint256 bal = balancesBefore[i];
                if (bal < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
                uint256 liq = _liquidity(i);
                uint256 toPull = assetsLeft < bal ? assetsLeft : bal;
                toPull = toPull < liq ? toPull : liq;
                if (toPull < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0

                // NOTE: ERC4626 withdraw() returns shares burned, NOT assets withdrawn
                // We track actual USDC received by checking balance before/after
                uint256 usdcBefore = USDC.balanceOf(address(this));
                try IEulerUsdcMarket(mkts[i].addr)
                    .withdraw(toPull, address(this), address(this)) returns (
                    uint256 sharesBurned
                ) {
                    // sharesBurned captured for slither - we track USDC not shares
                    if (sharesBurned < 1) { } // intentionally empty check
                    uint256 usdcAfter = USDC.balanceOf(address(this));
                    uint256 got = usdcAfter - usdcBefore;
                    totalWithdrawn += got;
                    assetsLeft = assetsLeft > got ? assetsLeft - got : 0;
                    // Update accounting: after withdraw, principal[i] = min(principal[i], newBalance)
                    uint256 balNew = _balanceInUnderlying(i);
                    principal[i] = principal[i] < balNew ? principal[i] : balNew;
                    if (principalTotal >= (bal - balNew)) {
                        principalTotal -= (bal - balNew);
                    } else {
                        principalTotal = 0;
                    }
                    emit Withdrawn(mkts[i].addr, toPull, got, receiver);
                } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                    // Withdraw failed (NotActivated or other error) - skip this market
                    continue;
                }
            }
        }
        if (totalWithdrawn > 0) {
            USDC.safeTransfer(receiver, totalWithdrawn);
        }
        return totalWithdrawn;
    }

    function currentAPYBps() public view override returns (uint16) {
        (uint256 idx, bool found) = _targetMarket();
        if (!found) return 0;
        return _supplyAPYBps(idx);
    }

    function incentiveAPYBps() external pure override returns (uint16) {
        return 0;
    }

    function harvestableProfit() public view override returns (uint256) {
        uint256 profit = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            uint256 bal = _balanceInUnderlying(i);
            if (bal > principal[i]) {
                profit += (bal - principal[i]);
            }
        }
        return profit;
    }

    function harvest(address receiver)
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 realized)
    {
        require(receiver == vault, "receiver must be vault");
        realized = 0; // Initialize return variable (slither: uninitialized-local)
        uint256 profit = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            uint256 bal = _balanceInUnderlying(i);
            if (bal > principal[i]) {
                uint256 profit_i = bal - principal[i];
                // NOTE: ERC4626 withdraw() returns shares burned, NOT assets withdrawn
                uint256 usdcBefore = USDC.balanceOf(address(this));
                try IEulerUsdcMarket(mkts[i].addr)
                    .withdraw(profit_i, address(this), address(this)) returns (
                    uint256 sharesBurned
                ) {
                    // sharesBurned captured for slither - we track USDC not shares
                    if (sharesBurned < 1) { } // intentionally empty check
                    uint256 usdcAfter = USDC.balanceOf(address(this));
                    profit += usdcAfter - usdcBefore;
                } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                    // Withdraw failed (NotActivated or other error) - skip this market
                    continue;
                }
            }
        }
        if (profit > 0) {
            USDC.safeTransfer(receiver, profit);
            emit Harvested(profit);
        }
        return profit;
    }

    function maxCapacity() external view override returns (uint256) {
        return capacity == 0 ? type(uint256).max : capacity;
    }

    /// @notice Returns sum of totalAssets() across all enabled Euler markets
    function externalMarketTVL() external view override returns (uint256 total) {
        total = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (!mkts[i].enabled) continue;
            try IEulerUsdcMarket(mkts[i].addr).totalAssets() returns (uint256 ta) {
                total += ta;
            } catch {
                // skip failed market
            }
        }
    }

    // --- EXTENSIONS ---

    function optimize()
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 movedUSDC, address fromMarket, address toMarket)
    {
        require(block.timestamp - lastOptimizeTs >= minSecondsBetweenOptimize, "cooldown");
        (uint256 fromIdx, bool foundFrom) = _activeMarketIdx();
        (uint256 toIdx, bool foundTo) = _targetMarket();
        require(foundFrom && foundTo, "no market");
        if (fromIdx == toIdx) {
            return (0, mkts[fromIdx].addr, mkts[toIdx].addr);
        }
        uint256 balanceFrom = _balanceInUnderlying(fromIdx);
        uint256 liquidityFrom = _liquidity(fromIdx);
        uint256 adapterTVL = totalAssets();
        uint256 capacityTo = capacity == 0
            ? type(uint256).max
            : (capacity > (adapterTVL - balanceFrom) ? capacity - (adapterTVL - balanceFrom) : 0);
        uint256 movedCandidate = balanceFrom < liquidityFrom ? balanceFrom : liquidityFrom;
        movedCandidate = movedCandidate < capacityTo ? movedCandidate : capacityTo;
        require(movedCandidate > 0, "nothing to move");
        require(movedCandidate * 10000 / adapterTVL >= subMoveMinBps, "move too small");

        uint16 apyFrom = _supplyAPYBps(fromIdx);
        uint16 apyTo = _supplyAPYBps(toIdx);
        if (apyTo <= apyFrom) {
            return (0, mkts[fromIdx].addr, mkts[toIdx].addr);
        }
        uint256 deltaAPY = apyTo - apyFrom; // bps

        // Estimate grossBenefit ~ movedCandidate * deltaAPY/10000 * (7 days / 365 days)
        uint256 grossBenefit = movedCandidate * deltaAPY * 7 / 365 / 10000;
        uint256 moveCost = gasCostUSDC
            + (movedCandidate * (slippageBpsEstimate + withdrawalSpreadBpsEstimate)) / 10000;
        uint256 netBenefitBps =
            grossBenefit > moveCost ? ((grossBenefit - moveCost) * 10000 / movedCandidate) : 0;
        require(netBenefitBps >= subGateMinNetBenefitBps, "no net benefit");

        // Withdraw from fromIdx (ERC4626)
        // NOTE: ERC4626 withdraw() returns shares burned, NOT assets withdrawn
        uint256 usdcBeforeOptimize = USDC.balanceOf(address(this));
        try IEulerUsdcMarket(mkts[fromIdx].addr)
            .withdraw(movedCandidate, address(this), address(this)) returns (
            uint256 sharesBurned
        ) {
            // sharesBurned captured for slither - we track USDC not shares
            if (sharesBurned < 1) { } // intentionally empty check
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            revert("Optimize withdraw failed - market not activated");
        }
        uint256 movedOut = USDC.balanceOf(address(this)) - usdcBeforeOptimize;

        // Ensure Permit2 internal allowance, then just-in-time approval and deposit to toIdx (ERC4626)
        _ensurePermit2(mkts[toIdx].addr);
        _approveMarket(mkts[toIdx].addr, movedOut);
        try IEulerUsdcMarket(mkts[toIdx].addr).deposit(movedOut, address(this)) returns (
            uint256 sharesMinted
        ) {
            // sharesMinted captured for slither - we track USDC not shares
            if (sharesMinted < 1) { } // intentionally empty check
            // Deposit successful - revoke approval
            _revokeMarketApproval(mkts[toIdx].addr);
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            // Deposit to target failed - try to poke it first
            bool poked = _pokeMarket(toIdx);
            require(poked, "Optimize deposit failed - market not activated");

            // Retry deposit
            uint256 retryShares =
                IEulerUsdcMarket(mkts[toIdx].addr).deposit(movedOut, address(this));
            if (retryShares < 1) { } // intentionally empty check

            // Revoke approval after successful deposit
            _revokeMarketApproval(mkts[toIdx].addr);
        }

        // Move principal portion
        uint256 capFrom = principal[fromIdx];
        uint256 balFromBefore = balanceFrom;
        uint256 movedCapitalPortion =
            (capFrom < 1 || balFromBefore < 1) ? 0 : (capFrom * movedOut) / balFromBefore; // slither: incorrect-equality - use < 1 instead of == 0
        principal[fromIdx] = capFrom > movedCapitalPortion ? capFrom - movedCapitalPortion : 0;
        principal[toIdx] += movedCapitalPortion;
        // principalTotal unchanged

        lastOptimizeTs = block.timestamp;

        emit IntraRebalanced(mkts[fromIdx].addr, mkts[toIdx].addr, movedOut);

        return (movedOut, mkts[fromIdx].addr, mkts[toIdx].addr);
    }

    function sweepIdleAssetToVault() external nonReentrant onlyVault {
        uint256 idle = USDC.balanceOf(address(this));
        require(idle > 0, "no idle");
        USDC.safeTransfer(vault, idle);
        emit IdleAssetSwept(idle);
    }

    function emergencyPullAllToVault() external nonReentrant onlyVault {
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            uint256 bal = _balanceInUnderlying(i);
            if (bal > 0) {
                // NOTE: ERC4626 withdraw() returns shares burned, NOT assets withdrawn
                // We track actual USDC received by checking balance before/after
                try IEulerUsdcMarket(mkts[i].addr)
                    .withdraw(bal, address(this), address(this)) returns (
                    uint256 sharesBurned
                ) {
                    // sharesBurned captured for slither - we track USDC not shares
                    if (sharesBurned < 1) { } // intentionally empty check
                } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                    // Withdraw failed (NotActivated or other error) - skip this market
                }
                principal[i] = 0;
            }
        }
        principalTotal = 0;
        // Transfer FULL balance (withdrawn + any pre-existing idle) to vault
        uint256 fullBalance = USDC.balanceOf(address(this));
        if (fullBalance > 0) {
            USDC.safeTransfer(vault, fullBalance);
        }
        emit EmergencyPullExecuted(fullBalance);
    }

    // --- DIAGNOSTICS ---

    function markets() external view override returns (address[] memory out) {
        uint256 n = mkts.length;
        out = new address[](n);
        for (uint256 i = 0; i < n; ++i) {
            out[i] = mkts[i].addr;
        }
    }

    function activeMarket() external view override returns (address) {
        (uint256 idx, bool found) = _activeMarketIdx();
        return found ? mkts[idx].addr : address(0);
    }

    function positions() external view override returns (uint256[] memory out) {
        uint256 n = mkts.length;
        out = new uint256[](n);
        for (uint256 i = 0; i < n; ++i) {
            out[i] = _balanceInUnderlying(i);
        }
    }

    function effectiveAPYBps() external view override returns (uint16) {
        uint256 sumBal = 0;
        uint256 sumAPY = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            uint256 bal = _balanceInUnderlying(i);
            if (bal > 0) {
                sumBal += bal;
                sumAPY += bal * _supplyAPYBps(i);
            }
        }
        if (sumBal < 1) return 0; // slither: incorrect-equality - use < 1 instead of == 0
        uint256 result = sumAPY / sumBal;
        require(result <= type(uint16).max, "EulerUsdcMultiMarket: APY overflow");
        // casting to uint16 is safe because overflow is checked above
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint16(result);
    }

    // --- ADMIN FUNCTIONS ---

    function setCostsEstimates(
        uint16 _slippageBps,
        uint16 _withdrawalSpreadBps,
        uint256 _gasCostUSDC
    ) external onlyParamRole {
        slippageBpsEstimate = _slippageBps;
        withdrawalSpreadBpsEstimate = _withdrawalSpreadBps;
        gasCostUSDC = _gasCostUSDC;
        emit CostsEstimatesUpdated(_slippageBps, _withdrawalSpreadBps, _gasCostUSDC);
    }

    function setOptimizeParams(
        uint32 _minSecondsBetweenOptimize,
        uint16 _subMoveMinBps,
        uint16 _subGateMinNetBenefitBps
    ) external onlyParamRole {
        minSecondsBetweenOptimize = _minSecondsBetweenOptimize;
        subMoveMinBps = _subMoveMinBps;
        subGateMinNetBenefitBps = _subGateMinNetBenefitBps;
        emit OptimizeParamsUpdated(
            _minSecondsBetweenOptimize, _subMoveMinBps, _subGateMinNetBenefitBps
        );
    }

    function setCapacity(uint256 _capacity) external onlyParamRole {
        capacity = _capacity;
        emit CapacityUpdated(_capacity);
    }

    function toggleMarket(uint256 idx, bool enabled, bool flagged) external onlyParamRole {
        require(idx < mkts.length, "idx out of bounds");
        mkts[idx].enabled = enabled;
        mkts[idx].flagged = flagged;
        emit MarketToggled(idx, mkts[idx].addr, enabled, flagged);
    }

    function setRiskScore(uint256 idx, uint16 riskScoreBps) external onlyParamRole {
        require(idx < mkts.length, "idx out of bounds");
        mkts[idx].riskScoreBps = riskScoreBps;
        emit RiskScoreUpdated(idx, riskScoreBps);
    }

    function updateMarketAddress(uint256 idx, address newAddr) external onlyParamRole {
        require(idx < mkts.length, "idx out of bounds");
        require(newAddr != address(0), "zero");
        address old = mkts[idx].addr;
        mkts[idx].addr = newAddr;
        emit MarketAddressUpdated(idx, old, newAddr);
    }

    function setParamRole(address newAdmin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(newAdmin != address(0), "zero");
        _grantRole(PARAM_ROLE, newAdmin);
    }

    // --- REGISTRY INTEGRATION ---

    /// @notice Internal: Load vault addresses from registry (if available)
    /// @dev V9 FIX: Deduplicates against existing markets to prevent double-counting
    function _loadFromRegistry() internal {
        try registry.getEnabledVaults(IProtocolRegistry.ProtocolType.EULER_V2) returns (
            address[] memory vaults
        ) {
            for (uint256 i = 0; i < vaults.length; i++) {
                if (vaults[i] != address(0)) {
                    // V9 FIX: Check for duplicates before adding
                    bool isDuplicate = false;
                    for (uint256 j = 0; j < mkts.length; j++) {
                        if (mkts[j].addr == vaults[i]) {
                            isDuplicate = true;
                            break;
                        }
                    }
                    if (!isDuplicate) {
                        // Registry is trusted source - no validation needed
                        // Vaults from registry are pre-validated and whitelisted
                        mkts.push(
                            Market({
                                addr: vaults[i], enabled: true, flagged: false, riskScoreBps: 0
                            })
                        );
                        principal.push(0);
                    }
                }
            }
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            // Registry call failed - use hardcoded markets from constructor
        }
    }

    /// @notice Refresh vault addresses from registry (only if registry configured)
    function refreshFromRegistry() external onlyParamRole {
        require(address(registry) != address(0), "no registry");
        _loadFromRegistry();
    }

    // --- FALLBACKS ---

    receive() external payable {
        revert("No ETH");
    }

    fallback() external payable {
        revert("No fallback");
    }
    event AdapterOperationFailed(bytes4 indexed operation, bytes reason);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;
import { PpsRateLib } from "./PpsRateLib.sol";

// ===== OpenZeppelin imports =====
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

// ===== Minimal ERC-4626 interface for Fluid fToken =====
interface IERC4626 {
    function asset() external view returns (address);
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);
    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256 sharesBurned);
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assetsOut);
    function convertToAssets(uint256 shares) external view returns (uint256 assets);
    function convertToShares(uint256 assets) external view returns (uint256 shares);
    function maxWithdraw(address owner) external view returns (uint256);
    function maxDeposit(address receiver) external view returns (uint256);
    function totalAssets() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

// ===== ILendingAdapter interface =====
interface ILendingAdapter {
    function name() external view returns (string memory);
    function underlying() external view returns (address);
    function totalAssets() external view returns (uint256);
    function withdrawableAssets() external view returns (uint256);
    function deposit(uint256 assets) external;
    function withdraw(uint256 assets, address receiver) external returns (uint256 withdrawn);
    function currentAPYBps() external view returns (uint16);
    function incentiveAPYBps() external view returns (uint16);
    function harvestableProfit() external view returns (uint256);
    function harvest(address receiver) external returns (uint256 realized);
    function maxCapacity() external view returns (uint256);
    function externalMarketTVL() external view returns (uint256);
    function isPushMode() external pure returns (bool);
    function idleAssetBalance() external view returns (uint256);
    function investedAssets() external view returns (uint256);
    function sweepIdleAssetToVault() external;
    function emergencyPullAllToVault() external;
}

/// @title FluidUsdcMultiMarketAdapter
/// @notice Lending adapter for Fluid fUSDC (ERC-4626) on Arbitrum.
/// @dev Single-market initially; can be extended to multi-market pattern later.
///      PULL mode: adapter calls transferFrom() to pull USDC from strategy during deposit().
///      APY: PPS-snapshot-based (pokeAPYSnapshots stores share price, currentAPYBps computes delta).
contract FluidUsdcMultiMarketAdapter is ILendingAdapter, AccessControl, ReentrancyGuard, Initializable {
    using SafeERC20 for IERC20;

    // ===== Roles =====
    bytes32 public constant PARAM_ROLE = keccak256("PARAM_ROLE");

    // ===== Immutable Storage =====
    // --- V10 Storage (was immutable in V9.x; logically immutable post-initialize) ---
    address public asset;       // USDC
    address public vault;       // Strategy vault
    IERC4626 public fToken;     // Fluid fUSDC

    // ===== Configurable Storage =====
    uint256 public capacity;              // Deposit cap (0 = unlimited)
    uint16  public incentiveBps;          // Optional incentive APY in bps
    uint16  public apyOverrideBps;        // Manual APY override (0 = disabled)

    // ===== APY Snapshot Storage =====
    uint256 internal lastSnapshotPPS;     // Share price at last poke (1e18 scale)
    uint64  internal lastSnapshotTs;      // Timestamp of last poke

    // ===== Events =====
    event Deposited(uint256 assets, uint256 shares);
    event Withdrawn(uint256 assets, address receiver);
    event CapacityUpdated(uint256 newCap);
    event IncentiveBpsUpdated(uint16 newBps);
    event APYOverrideUpdated(uint16 newBps);
    event APYSnapshotPoked(uint256 pps, uint64 ts);
    event IdleAssetSwept(uint256 amount);
    event EmergencyPullExecuted(uint256 amount);
    /// @dev SLITHER-FIX-4: emit captured assetsOut from fToken.redeem return for incident-response visibility.
    event EmergencyFluidRedeemed(uint256 shares, uint256 assetsOut);

    // ===== Modifiers =====
    modifier onlyVault() {
        require(msg.sender == vault, "not vault");
        _;
    }

    modifier onlyParamRole() {
        require(hasRole(PARAM_ROLE, msg.sender), "not param role");
        _;
    }

    // ===== Constructor =====

    /// @notice One-shot initialization called atomically by AdapterFactory.
    function initialize(
        address usdc_,
        address admin_,
        address vault_,
        uint256 capacity_,
        address fToken_
    ) external initializer {
        require(
            usdc_ != address(0) && admin_ != address(0)
                && vault_ != address(0) && fToken_ != address(0),
            "zero"
        );
        require(IERC4626(fToken_).asset() == usdc_, "fToken/asset mismatch");

        asset = usdc_;
        vault = vault_;
        fToken = IERC4626(fToken_);
        capacity = capacity_;

        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
        _grantRole(PARAM_ROLE, admin_);

        // Initialize APY snapshot
        lastSnapshotPPS = IERC4626(fToken_).convertToAssets(1e18);
        lastSnapshotTs = uint64(block.timestamp);
        PpsRateLib.update(rateSample, IERC4626(fToken_).convertToAssets(1e24));
    }

    // ===== ILendingAdapter: Metadata =====

    function name() external pure override returns (string memory) {
        return "Fluid_USDC_Adapter_Arbitrum";
    }

    function underlying() external view override returns (address) {
        return asset;
    }

    /// @notice PULL mode: adapter calls transferFrom() on strategy during deposit()
    function isPushMode() external pure override returns (bool) {
        return false;
    }

    // ===== ILendingAdapter: Accounting =====

    /// @notice Raw USDC balance held locally (not invested in Fluid)
    function idleAssetBalance() public view override returns (uint256) {
        return IERC20(asset).balanceOf(address(this));
    }

    /// @notice USDC value of fToken shares held by this adapter
    function investedAssets() public view override returns (uint256) {
        uint256 shares = fToken.balanceOf(address(this));
        if (shares < 1) return 0;
        return fToken.convertToAssets(shares);
    }

    /// @notice Total USDC controlled by adapter = invested + idle
    function totalAssets() public view override returns (uint256) {
        return investedAssets() + idleAssetBalance();
    }

    /// @notice Conservative withdrawable amount using maxWithdraw
    function withdrawableAssets() public view override returns (uint256) {
        return fToken.maxWithdraw(address(this));
    }

    // ===== ILendingAdapter: Lifecycle =====

    /// @notice Pull USDC from strategy and deposit into Fluid fToken
    function deposit(uint256 assets) external override nonReentrant onlyVault {
        require(assets > 0, "ZERO_ASSETS");
        if (capacity > 0) require(totalAssets() + assets <= capacity, "CAP");

        // Gas: cache `asset`/`fToken` locally -- both set once in initialize()
        // with no setter, avoids re-reading storage across the
        // transferFrom/approve/deposit/revoke sequence below.
        address asset_ = asset;
        IERC4626 fToken_ = fToken;

        // Pull USDC from strategy
        IERC20(asset_).safeTransferFrom(msg.sender, address(this), assets);

        // Just-in-time approval
        IERC20(asset_).forceApprove(address(fToken_), assets);

        // Deposit into Fluid fToken
        uint256 shares = fToken_.deposit(assets, address(this));

        // Revoke approval
        IERC20(asset_).forceApprove(address(fToken_), 0);

        emit Deposited(assets, shares);
    }

    /// @notice Withdraw USDC from Fluid fToken and send to vault
    /// @dev Uses actual received amount (Fluid docs note small differences possible)
    function withdraw(
        uint256 assets,
        address /*receiver*/
    )
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 withdrawn)
    {
        require(assets > 0, "ZERO_ASSETS");

        // Clamp to withdrawable
        uint256 maxOut = withdrawableAssets();
        uint256 want = assets > maxOut ? maxOut : assets;
        if (want == 0) return 0;

        // Gas: cache `asset` locally -- set once in initialize(), no setter.
        IERC20 assetToken = IERC20(asset);

        // Record balance before to measure actual received
        uint256 balBefore = assetToken.balanceOf(address(this));

        // Withdraw from fToken to this adapter
        fToken.withdraw(want, address(this), address(this));

        // Measure actual received (Fluid may have small differences)
        uint256 balAfter = assetToken.balanceOf(address(this));
        withdrawn = balAfter - balBefore;

        // Transfer actual received to vault
        if (withdrawn > 0) {
            assetToken.safeTransfer(vault, withdrawn);
        }

        emit Withdrawn(withdrawn, vault);
    }

    // ===== ILendingAdapter: Yield =====

    /// @notice APY in basis points computed from PPS snapshot delta
    PpsRateLib.Sample internal rateSample;
    function currentAPYBps() external view override returns (uint16) {
        if (apyOverrideBps != 0) return apyOverrideBps;
        try fToken.convertToAssets(1e24) returns (uint256 pps) {
            return PpsRateLib.read(rateSample, pps);
        } catch { return 0; }
    }

    function incentiveAPYBps() external view override returns (uint16) {
        return incentiveBps;
    }

    /// @notice No reward claiming in v1
    function harvestableProfit() external pure override returns (uint256) {
        return 0;
    }

    /// @notice No reward claiming in v1
    function harvest(address) external pure override returns (uint256 realized) {
        return 0;
    }

    // ===== ILendingAdapter: Limits =====

    function maxCapacity() external view override returns (uint256) {
        return capacity == 0 ? type(uint256).max : capacity;
    }

    // ===== ILendingAdapter: External Market TVL =====

    /// @notice Returns total USDC deposited in the Fluid fToken vault
    function externalMarketTVL() external view override returns (uint256) {
        try fToken.totalAssets() returns (uint256 total) {
            return total;
        } catch {
            return 0;
        }
    }

    // ===== Idle Asset & Emergency Recovery =====

    /// @notice Transfer all idle USDC back to vault (does NOT touch invested)
    function sweepIdleAssetToVault() external override nonReentrant onlyVault {
        uint256 idle = IERC20(asset).balanceOf(address(this));
        require(idle > 0, "no idle");
        IERC20(asset).safeTransfer(vault, idle);
        emit IdleAssetSwept(idle);
    }

    /// @notice Emergency: redeem ALL fToken shares + sweep all USDC to vault
    function emergencyPullAllToVault() external override nonReentrant onlyVault {
        // Redeem all invested shares
        uint256 shares = fToken.balanceOf(address(this));
        if (shares > 0) {
            try fToken.redeem(shares, address(this), address(this)) returns (uint256 _assetsOut) {
                emit EmergencyFluidRedeemed(shares, _assetsOut);
            }
            catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                emit EmergencyFluidRedeemed(shares, 0);
            }
        }

        // Transfer FULL USDC balance (redeemed + any pre-existing idle) to vault
        uint256 fullBalance = IERC20(asset).balanceOf(address(this));
        if (fullBalance > 0) {
            IERC20(asset).safeTransfer(vault, fullBalance);
        }
        emit EmergencyPullExecuted(fullBalance);
    }

    // ===== Admin Functions (PARAM_ROLE) =====

    /// @notice Store current share price for APY calculation
    function pokeAPYSnapshots() external onlyParamRole {
        uint256 pps = fToken.convertToAssets(1e18);
        uint64 nowTs = uint64(block.timestamp);
        PpsRateLib.update(rateSample, fToken.convertToAssets(1e24));
        lastSnapshotPPS = pps;
        lastSnapshotTs = nowTs;
        emit APYSnapshotPoked(pps, nowTs);
    }

    function setCapacity(uint256 newCap) external onlyRole(PARAM_ROLE) {
        capacity = newCap;
        emit CapacityUpdated(newCap);
    }

    function setIncentiveBps(uint16 bps) external onlyRole(PARAM_ROLE) {
        require(bps <= 10_000, "bps>10000");
        incentiveBps = bps;
        emit IncentiveBpsUpdated(bps);
    }

    function setAPYOverrideBps(uint16 bps) external onlyRole(PARAM_ROLE) {
        require(bps <= 10_000, "bps>10000");
        apyOverrideBps = bps;
        emit APYOverrideUpdated(bps);
    }

    // ===== View Helpers =====

    /// @notice Returns last APY snapshot data for monitoring
    function getAPYSnapshot() external view returns (uint256 pps, uint64 ts) {
        return (lastSnapshotPPS, lastSnapshotTs);
    }

    /// @notice Returns fToken share balance held by this adapter
    function shareBalance() external view returns (uint256) {
        return fToken.balanceOf(address(this));
    }

    // ===== Fallbacks disabled =====
    receive() external payable {
        revert("NO_RECEIVE");
    }

    fallback() external payable {
        revert("NO_FALLBACK");
    }
    event AdapterOperationFailed(bytes4 indexed operation, bytes reason);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;
import { PpsRateLib } from "./PpsRateLib.sol";

// ===== OpenZeppelin imports =====
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

// ===== ILendingAdapter interface (Euler pattern) =====
interface ILendingAdapter {
    function name() external view returns (string memory);
    function underlying() external view returns (address);
    function totalAssets() external view returns (uint256);
    function withdrawableAssets() external view returns (uint256);
    function deposit(uint256 assets) external;
    function withdraw(uint256 assets, address receiver) external returns (uint256 withdrawn);
    function currentAPYBps() external view returns (uint16);
    function incentiveAPYBps() external view returns (uint16);
    function harvestableProfit() external view returns (uint256);
    function harvest(address receiver) external returns (uint256 realized);
    function maxCapacity() external view returns (uint256);
    function externalMarketTVL() external view returns (uint256);
}

// ===== Minimal ERC-4626 interface for Morpho vaults =====
interface IERC4626Like {
    function asset() external view returns (address);
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);
    function withdraw(uint256 assets, address receiver, address owner)
        external
        returns (uint256 sharesBurned);
    function redeem(uint256 shares, address receiver, address owner)
        external
        returns (uint256 assetsOut);
    function convertToAssets(uint256 shares) external view returns (uint256 assets);
    function convertToShares(uint256 assets) external view returns (uint256 shares);
    function previewWithdraw(uint256 assets) external view returns (uint256 shares);
    function previewRedeem(uint256 shares) external view returns (uint256 assets);
    function totalAssets() external view returns (uint256);
}

// ===== Protocol Registry Interface =====
interface IProtocolRegistry {
    enum ProtocolType {
        AAVE_V3,
        EULER_V2,
        MORPHO,
        COMPOUND_V3,
        DOLOMITE,
        GAINS,
        SILO_V2
    }
    function getEnabledVaults(ProtocolType protocol) external view returns (address[] memory);
    function isEnabled(ProtocolType protocol, address vault) external view returns (bool);
}

// ===== Adapter contract =====
contract MorphoUsdcMultiMarketAdapter is ILendingAdapter, AccessControl, ReentrancyGuard, Initializable {
    using SafeERC20 for IERC20;

    // ===== Roles =====
    bytes32 public constant PARAM_ROLE = keccak256("PARAM_ROLE");

    // ===== Custom Errors =====
    error AllMarketsFailed(uint256 assets);

    // ===== Constants =====
    uint16 public constant BPS_DENOM = 10000;
    uint8 public constant USDC_DECIMALS = 6;
    uint8 public constant MARKET_QUARANTINE_THRESHOLD = 3;
    uint64 public constant PPS_SNAP_TTL = uint64(2 days);

    // ===== State: Addresses =====
    // --- V10 Storage (was immutable in V9.x; logically immutable post-initialize) ---
    address public override underlying; // USDC
    address public vault; // Strategy Vault
    IProtocolRegistry public registry; // Optional registry (address(0) if not used)

    // ===== Market registry =====
    struct Market {
        address addr; // Morpho vault (ERC-4626-like)
        bool enabled; // included in allocation
        bool flagged; // defense/hold: do not increase allocation
        uint16 riskScoreBps; // 0..10000 (10000 = min risk)
    }
    Market[] internal mkts;

    // ===== Principal/accounting =====
    uint256[] public principal; // principal per market
    uint256 public principalTotal; // sum(principal)
    uint8 public activeIdx; // best market index
    uint64 public lastOptimizeTs; // last optimize timestamp

    // ===== Cached NAV per market (eliminates expensive view calls) =====
    mapping(uint256 => uint256) internal cachedMarketNav;

    // ===== CTO Hardening: per-market failure tracking =====
    mapping(address => uint8) public marketFailures;
    mapping(address => uint64) public marketLastFailureTs;
    uint32 public marketFailureDecaySeconds = 1 hours;

    // APY cached fallback (for rate provider revert resilience)
    mapping(address => uint16) public lastGoodApyBps;
    // Audit #2 P1.9 — APY cache staleness tracking (no auto-unflag).
    mapping(address => uint64) public lastApyUpdateTs;
    uint32 public apyStalenessSeconds = 1 days;

    // ===== Parameters =====
    // Scoring weights (sum = 10000) - constant for gas optimization
    uint16 public constant wAPY = 4000;
    uint16 public constant wLiq = 2000;
    uint16 public constant wRisk = 2000;
    uint16 public constant wStability = 1000;
    uint16 public constant wIncentive = 1000;

    // Rebalance/optimize params
    uint16 public rebalanceMinMoveBps = 50; // 0.5%
    uint32 public minSecondsBetweenOptimize = 6 hours;
    uint16 public constant driftToleranceBps = 10; // 0.1%
    uint16 public constant gateHorizonDays = 7;
    uint16 public gateMinNetBenefitBps = 2;
    uint16 public slippageBpsEstimate = 10;
    uint16 public withdrawalSpreadBpsEstimate = 10;
    uint256 public gasCostUSDC = 1e4; // in USDC (6 decimals)

    uint256 public capacity; // 0 = infinite

    // Global incentive APY fallback (bps)
    uint16 public incentiveBpsGlobal;

    // ===== Events =====
    event MarketAdded(uint256 indexed idx, address market);
    event MarketToggled(uint256 indexed idx, bool enabled);
    event MarketFlagged(uint256 indexed idx, bool flagged);
    event MarketUpdated(uint256 indexed idx, address market);
    event CostsEstimatesUpdated(
        uint16 slippageBps, uint16 withdrawalSpreadBps, uint256 gasCostUSDC
    );
    event OptimizeParamsUpdated(
        uint32 minSecondsBetweenOptimize, uint16 subMoveMinBps, uint16 subGateMinNetBenefitBps
    );
    event CapacityUpdated(uint256 capacity);
    event RiskScoreUpdated(uint256 indexed idx, uint16 riskScoreBps);
    event IntraRebalanced(address fromMarket, address toMarket, uint256 movedAssets);
    event Supplied(uint256 assets, address market);
    event Withdrawn(uint256 assets, address market, address receiver);
    // CTO Hardening events
    event MarketDepositFailed(address indexed market, uint256 assets, bytes reason);
    event MarketAutoFlagged(address indexed market, uint8 failures);
    event MarketApyFallbackUsed(address indexed market, uint16 cachedApy);
    event MarketApyUpdated(address indexed market, uint16 apy);
    event MarketFailureReset(address indexed market);

    // ===== Modifiers =====
    modifier onlyVault() {
        require(msg.sender == vault, "MorphoAdapter: not vault");
        _;
    }

    modifier onlyParam() {
        require(
            hasRole(PARAM_ROLE, msg.sender) || hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "MorphoAdapter: not param"
        );
        _;
    }

    // ===== Constructor =====

    /// @notice One-shot initialization called atomically by AdapterFactory.
    function initialize(
        address usdc_,
        address admin_,
        address vault_,
        uint256 capacity_,
        address registry_
    ) external initializer {
        require(usdc_ != address(0) && admin_ != address(0) && vault_ != address(0), "zero");
        underlying = usdc_;
        vault = vault_;
        capacity = capacity_;
        registry = IProtocolRegistry(registry_);

        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
        _grantRole(PARAM_ROLE, admin_);

        // Auto-load vaults from registry if available
        if (registry_ != address(0)) {
            _loadFromRegistry();
        }

        // V9 HARDENING: Fail-fast if no markets loaded
        // This prevents the V8 bug where adapter deployed with empty registry
        // would silently have mkts.length == 0 and panic on first deposit
        require(mkts.length > 0, "MorphoAdapter: no markets - registry required or use addMarket");
    }

    /// @notice Load vaults from protocol registry
    function _loadFromRegistry() internal {
        try registry.getEnabledVaults(IProtocolRegistry.ProtocolType.MORPHO) returns (
            address[] memory vaults
        ) {
            for (uint256 i = 0; i < vaults.length; i++) {
                if (vaults[i] != address(0)) {
                    // Registry is trusted source - no validation needed
                    // Vaults from registry are pre-validated and whitelisted
                    mkts.push(
                        Market({
                            addr: vaults[i], enabled: true, flagged: false, riskScoreBps: BPS_DENOM
                        })
                    );
                    principal.push(0);
                }
            }
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            // Registry call failed - adapter will start with empty markets (use addMarket manually)
        }
    }

    // ===== Registry management (PARAM_ROLE) =====
    function addMarket(address market) external onlyParam {
        require(market != address(0), "zero");
        // Loop counters in getBestMarket()/getRebalancePlan()/sortMarketsByAPY()
        // are uint8; a 256th market would wrap the counter to 0 and infinite-loop
        // (OOG). Cap the registry well below that.
        require(mkts.length < 255, "too many markets");
        require(IERC4626Like(market).asset() == underlying, "wrong asset");
        mkts.push(Market({ addr: market, enabled: true, flagged: false, riskScoreBps: BPS_DENOM }));
        principal.push(0);
        emit MarketAdded(mkts.length - 1, market);
    }

    function toggleMarket(uint256 idx, bool enabled) external onlyParam {
        require(idx < mkts.length, "bad idx");
        mkts[idx].enabled = enabled;
        emit MarketToggled(idx, enabled);
    }

    function flagMarket(uint256 idx, bool flagged) external onlyParam {
        require(idx < mkts.length, "bad idx");
        mkts[idx].flagged = flagged;
        emit MarketFlagged(idx, flagged);
    }

    function updateMarketAddress(uint256 idx, address market) external onlyParam {
        require(idx < mkts.length, "bad idx");
        require(market != address(0), "zero");
        require(IERC4626Like(market).asset() == underlying, "wrong asset");
        mkts[idx].addr = market;
        emit MarketUpdated(idx, market);
    }

    /// @notice Refresh markets from registry (clear and reload)
    /// @dev Only works if registry was set in constructor
    function refreshFromRegistry() external onlyParam {
        require(address(registry) != address(0), "no registry");

        // Clear existing markets
        delete mkts;
        delete principal;

        // Reload from registry
        _loadFromRegistry();
    }

    function setRiskScore(uint256 idx, uint16 riskScoreBps) external onlyParam {
        require(idx < mkts.length, "bad idx");
        require(riskScoreBps <= BPS_DENOM, "bad risk");
        mkts[idx].riskScoreBps = riskScoreBps;
        emit RiskScoreUpdated(idx, riskScoreBps);
    }

    function setCostsEstimates(
        uint16 slippageBps,
        uint16 withdrawalSpreadBps,
        uint256 gasCostUSDC_
    ) external onlyParam {
        slippageBpsEstimate = slippageBps;
        withdrawalSpreadBpsEstimate = withdrawalSpreadBps;
        gasCostUSDC = gasCostUSDC_;
        emit CostsEstimatesUpdated(slippageBps, withdrawalSpreadBps, gasCostUSDC_);
    }

    function setOptimizeParams(
        uint32 minSecondsBetweenOptimize_,
        uint16 subMoveMinBps,
        uint16 subGateMinNetBenefitBps
    ) external onlyParam {
        minSecondsBetweenOptimize = minSecondsBetweenOptimize_;
        rebalanceMinMoveBps = subMoveMinBps;
        gateMinNetBenefitBps = subGateMinNetBenefitBps;
        emit OptimizeParamsUpdated(
            minSecondsBetweenOptimize_, subMoveMinBps, subGateMinNetBenefitBps
        );
    }

    function setCapacity(uint256 cap) external onlyParam {
        capacity = cap;
        emit CapacityUpdated(cap);
    }

    function setIncentiveBpsGlobal(uint16 bps) external onlyParam {
        require(bps <= BPS_DENOM, "bad bps");
        incentiveBpsGlobal = bps;
    }

    function setParamRole(address account, bool enable) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (enable) _grantRole(PARAM_ROLE, account);
        else _revokeRole(PARAM_ROLE, account);
    }

    /// @dev Update market failure decay parameter
    function setMarketFailureDecaySeconds(uint32 _seconds) external onlyParam {
        marketFailureDecaySeconds = _seconds;
    }

    /// @dev Manual unflag a market (after human review)
    function unflagMarket(uint8 idx) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(idx < mkts.length, "bad idx");
        mkts[idx].flagged = false;
        marketFailures[mkts[idx].addr] = 0;
        emit MarketFlagged(idx, false);
    }

    // ===== Adapter interface: metadata =====
    function name() external pure override returns (string memory) {
        return "Morpho_USDC_MultiMarket_Adapter_Arbitrum";
    }

    /// @notice Returns false because Morpho uses PULL deposit pattern
    /// @dev Adapter calls transferFrom() to pull USDC from Strategy during deposit()
    function isPushMode() external pure returns (bool) {
        return false;
    }

    // underlying() auto-generated getter provided by the immutable state variable

    // ===== INTERNAL HELPERS =====

    /// @notice Sets just-in-time approval for exact amount
    /// @dev Prevents unlimited protocol exposure if Morpho market is compromised
    function _approveMarket(address marketAddr, uint256 amount) internal {
        IERC20(underlying).forceApprove(marketAddr, amount);
    }

    /// @notice Resets market approval to zero
    function _revokeMarketApproval(address marketAddr) internal {
        IERC20(underlying).forceApprove(marketAddr, 0);
    }

    // ===== CTO Hardening: Safe view helpers =====

    /// @dev Safe convertToAssets: staticcall, returns (false, 0) on revert.
    function _safeConvertToAssets(address market, uint256 shares)
        internal
        view
        returns (bool ok, uint256 assets)
    {
        (bool success, bytes memory data) =
            market.staticcall(abi.encodeWithSignature("convertToAssets(uint256)", shares));
        if (success && data.length >= 32) {
            assets = abi.decode(data, (uint256));
            return (true, assets);
        }
        return (false, 0);
    }

    /// @dev Decode uint256 APY to uint16, clamp if > type(uint16).max. Returns 0 on bad data.
    function _safeDecodeApyBps(bytes memory data) internal pure returns (uint16) {
        if (data.length < 32) return 0;
        uint256 x = abi.decode(data, (uint256));
        if (x > type(uint16).max) return type(uint16).max;
        return uint16(x);
    }

    /// @dev View-safe APY getter. Never reverts. Falls back to cached lastGoodApyBps.
    /// Audit #2 P1.9: if cache is stale (beyond apyStalenessSeconds), returns 0 so
    /// the scoring engine does not allocate based on outdated yield data.
    function _getAPYOnChainOrCached(address market) internal view returns (uint16) {
        (bool ok, uint256 pps) = _safeConvertToAssets(market, 1e24);
        if (!ok) return 0;
        if (apyStalenessSeconds > 0 && rateSamples[market].ts != 0
            && block.timestamp - rateSamples[market].ts > apyStalenessSeconds) return 0;
        return PpsRateLib.read(rateSamples[market], pps);
    }

    function _refreshApyCache(address market) internal {
        (bool ok, uint256 pps) = _safeConvertToAssets(market, 1e24);
        if (!ok) return;
        PpsRateLib.update(rateSamples[market], pps);
        lastGoodApyBps[market] = PpsRateLib.read(rateSamples[market], pps);
        lastApyUpdateTs[market] = rateSamples[market].ts;
    }

    /// @dev Try deposit to a specific market. Returns true on success, false on failure.
    function _safeDepositToMarket(address market, uint256 assets) internal returns (bool) {
        _approveMarket(market, assets);
        try IERC4626Like(market).deposit(assets, address(this)) returns (uint256 shares) {
            _revokeMarketApproval(market);
            return shares > 0;
        } catch (bytes memory reason) {
            _revokeMarketApproval(market);
            emit MarketDepositFailed(market, assets, reason);
            return false;
        }
    }

    /// @dev Record market failure, auto-flag if threshold exceeded.
    function _recordMarketFailure(address market, uint256 idx) internal {
        // Temporal decay
        if (
            marketFailureDecaySeconds > 0 && marketLastFailureTs[market] > 0
                && block.timestamp - uint256(marketLastFailureTs[market])
                    > marketFailureDecaySeconds
        ) {
            marketFailures[market] = 0;
            emit MarketFailureReset(market);
        }
        marketLastFailureTs[market] = uint64(block.timestamp);

        uint8 failures;
        unchecked {
            failures = marketFailures[market] + 1;
        }
        marketFailures[market] = failures;

        if (failures >= MARKET_QUARANTINE_THRESHOLD && !mkts[idx].flagged) {
            mkts[idx].flagged = true;
            emit MarketAutoFlagged(market, failures);
            emit MarketFlagged(idx, true);
        }
    }

    /// @dev Reset market failure counter on success.
    function _recordMarketSuccess(address market) internal {
        if (marketFailures[market] != 0) {
            marketFailures[market] = 0;
            emit MarketFailureReset(market);
        }
        marketLastFailureTs[market] = uint64(block.timestamp);
    }

    // ===== Adapter interface: accounting =====
    function totalAssets() public view override returns (uint256) {
        return investedAssets() + idleAssetBalance();
    }

    function withdrawableAssets() public view override returns (uint256) {
        uint256 sum = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            address m = mkts[i].addr;
            if (m == address(0)) continue;
            // For Morpho vaults: use maxWithdraw() which accounts for underlying market liquidity
            // Fallback to checking cash balance if maxWithdraw() is not available
            (bool success, bytes memory data) =
                m.staticcall(abi.encodeWithSignature("maxWithdraw(address)", address(this)));
            if (success && data.length >= 32) {
                sum += abi.decode(data, (uint256));
            } else {
                // Fallback: safe estimate via convertToAssets + cash
                uint256 shares = IERC20(m).balanceOf(address(this));
                if (shares < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
                (bool okConvert, uint256 assets) = _safeConvertToAssets(m, shares);
                // FIX P1.L4: continue MUST be inside if-branch so success path runs the cash-cap.
                //          Pre-fix, the unconditional continue made the cash-cap path unreachable
                //          and the market contributed 0 (under-reports liquidity).
                if (!okConvert) {
                    sum += principal[i];
                    continue;
                }
                uint256 cash = IERC20(underlying).balanceOf(m);
                sum += assets < cash ? assets : cash;
            }
        }
        return sum;
    }

    // ===== Adapter interface: deposit/withdraw (NO-CUSTODY) =====
    /// @notice Deposit with multi-market fallback. Tries active market first, then by APY desc.
    /// @dev PULL mode: strategy pre-approves, adapter pulls USDC once.
    ///      If all markets fail, revert rolls back safeTransferFrom atomically.
    function deposit(uint256 assets) external override nonReentrant onlyVault {
        require(assets > 0, "zero");
        if (capacity > 0) require(totalAssets() + assets <= capacity, "cap");

        uint256 n = mkts.length;

        // PULL mode: pull USDC once
        IERC20(underlying).safeTransferFrom(msg.sender, address(this), assets);

        // Try active market first (fast path)
        uint256 firstTry = activeIdx;
        if (firstTry < n) {
            Market storage mkt = mkts[firstTry];
            if (mkt.enabled && !mkt.flagged && mkt.addr != address(0)) {
                _refreshApyCache(mkt.addr);
                if (_safeDepositToMarket(mkt.addr, assets)) {
                    _recordMarketSuccess(mkt.addr);
                    principal[firstTry] += assets;
                    principalTotal += assets;
                    _refreshNavCache();
                    emit Supplied(assets, mkt.addr);
                    return;
                }
                _recordMarketFailure(mkt.addr, firstTry);
            }
        }

        // Fallback: try remaining markets by APY descending
        uint8[] memory idxs = sortMarketsByAPY(false);
        for (uint256 k = 0; k < idxs.length; ++k) {
            uint256 idx = uint256(idxs[k]);
            if (idx == firstTry || idx >= n) continue;
            Market storage m = mkts[idx];
            if (!m.enabled || m.flagged || m.addr == address(0)) continue;

            _refreshApyCache(m.addr);
            if (_safeDepositToMarket(m.addr, assets)) {
                _recordMarketSuccess(m.addr);
                principal[idx] += assets;
                principalTotal += assets;
                activeIdx = uint8(idx);
                _refreshNavCache();
                emit Supplied(assets, m.addr);
                return;
            }
            _recordMarketFailure(m.addr, idx);
        }

        // All markets failed — revert rolls back entire tx including safeTransferFrom
        revert AllMarketsFailed(assets);
    }

    function withdraw(
        uint256 assets,
        address /*receiver*/
    )
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 withdrawn)
    {
        withdrawn = 0; // Initialize return variable (slither: uninitialized-local)
        uint256 want = assets;
        uint256 avail = withdrawableAssets();
        if (want > avail) want = avail;
        require(want > 0, "zero");
        // Withdraw pro-rata from worst APY to best, or by available liquidity
        uint256 n = mkts.length;
        uint256 totalWithdrawn = 0;
        uint256 remaining = want;
        // Build sorted index list by APY ascending (worst first)
        uint8[] memory idxs = sortMarketsByAPY(false);
        for (uint256 k = 0; k < n && remaining > 0; ++k) {
            uint8 idx = idxs[k];
            address m = mkts[idx].addr;
            if (m == address(0)) continue;
            uint256 shares = IERC20(m).balanceOf(address(this));
            if (shares < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0

            // Determine withdrawable amount using maxWithdraw() for accurate liquidity check
            uint256 canWithdraw;
            (bool success, bytes memory data) =
                m.staticcall(abi.encodeWithSignature("maxWithdraw(address)", address(this)));
            if (success && data.length >= 32) {
                canWithdraw = abi.decode(data, (uint256));
            } else {
                // Fallback: estimate via cash balance (for non-Morpho vaults)
                uint256 maxAssets = IERC4626Like(m).convertToAssets(shares);
                uint256 cash = IERC20(underlying).balanceOf(m);
                canWithdraw = maxAssets < cash ? maxAssets : cash;
            }

            if (canWithdraw < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
            uint256 toWithdraw = canWithdraw < remaining ? canWithdraw : remaining;
            uint256 sharesToBurn = IERC4626Like(m).previewWithdraw(toWithdraw);
            // slither: unused-return - capture return value
            uint256 actualSharesBurned = IERC4626Like(m).withdraw(toWithdraw, vault, address(this));
            require(actualSharesBurned > 0 || toWithdraw < 1, "Morpho: withdraw returned 0 shares");
            // Bookkeeping
            uint256 oldPrincipal = principal[idx];
            uint256 currentAssets =
                IERC4626Like(m).convertToAssets(IERC20(m).balanceOf(address(this)));
            uint256 principalDelta = oldPrincipal * toWithdraw
                / (currentAssets + toWithdraw > 0 ? currentAssets + toWithdraw : 1);
            if (principalDelta > principal[idx]) principalDelta = principal[idx];
            principal[idx] -= principalDelta;
            principalTotal -= principalDelta;
            totalWithdrawn += toWithdraw;
            remaining -= toWithdraw;
            emit Withdrawn(toWithdraw, m, vault);
        }
        _refreshNavCache();
        return totalWithdrawn;
    }

    // ===== Adapter interface: APY & yield =====
    uint16 public apyOverrideBps; // optional APY override (bps), 0=disabled

    // ERC-4626 APY snapshot for share price
    struct PpsSnap {
        uint256 pps;
        uint64 ts;
    }
    mapping(address => PpsSnap) public ppsSnap;

    mapping(address => PpsRateLib.Sample) internal rateSamples;
    function currentAPYBps() public view override returns (uint16) {
        if (apyOverrideBps != 0) return apyOverrideBps;
        if (activeIdx < mkts.length && mkts[activeIdx].enabled)
            return _getAPYOnChainOrCached(mkts[activeIdx].addr);
        (, uint16 bestAPY) = getBestMarket();
        return bestAPY;
    }

    function incentiveAPYBps() external view override returns (uint16) {
        return incentiveBpsGlobal;
    }

    function harvestableProfit() external pure override returns (uint256) {
        return 0;
    }

    function harvest(
        address /*receiver*/
    )
        external
        pure
        override
        returns (uint256)
    {
        return 0;
    }

    function maxCapacity() external view override returns (uint256) {
        return capacity == 0 ? type(uint256).max : capacity;
    }

    /// @notice Returns sum of totalAssets() across all enabled Morpho markets
    function externalMarketTVL() external view override returns (uint256 total) {
        total = 0;
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (!mkts[i].enabled) continue;
            try IERC4626Like(mkts[i].addr).totalAssets() returns (uint256 ta) {
                total += ta;
            } catch {
                // skip failed market
            }
        }
    }

    function setAPYOverrideBps(uint16 bps) external onlyRole(PARAM_ROLE) {
        require(bps <= 10000, "bps>10000");
        apyOverrideBps = bps;
    }

    function pokeAPYSnapshots() external onlyRole(PARAM_ROLE) {
        uint256 n = mkts.length;
        uint64 nowTs = uint64(block.timestamp);
        for (uint256 i = 0; i < n; ++i) {
            address m = mkts[i].addr;
            if (m == address(0)) continue;
            _refreshApyCache(m);
            (bool ok, uint256 pps) = _safeConvertToAssets(m, 1e18);
            if (ok) {
                ppsSnap[m] = PpsSnap({ pps: pps, ts: nowTs });
                // Audit #2 P1.9 — record when APY was last successfully refreshed.
                lastApyUpdateTs[m] = rateSamples[m].ts;
            }
        }
        _refreshNavCache();
    }

    // ===== Optimize/rebalance (hardened) =====
    function optimize()
        external
        nonReentrant
        onlyVault
        returns (uint256 movedUSDC, address fromMarket, address toMarket)
    {
        require(block.timestamp >= lastOptimizeTs + minSecondsBetweenOptimize, "cooldown");
        (uint8 fromIdx, uint8 toIdx, uint256 moveAmount, int256 netBenefitBps) = getRebalancePlan();
        require(moveAmount > 0, "no move");
        require(netBenefitBps >= int256(uint256(gateMinNetBenefitBps)), "no benefit");

        fromMarket = mkts[fromIdx].addr;
        toMarket = mkts[toIdx].addr;
        require(fromMarket != address(0) && toMarket != address(0), "bad market");

        // Safe withdraw
        try IERC4626Like(fromMarket).withdraw(moveAmount, address(this), address(this)) returns (
            uint256 _sharesBurned
        ) {
            emit OptimizeMarketWithdrawn(fromIdx, toIdx, moveAmount, _sharesBurned);
        }
        catch (bytes memory reason) {
            emit MarketDepositFailed(fromMarket, moveAmount, reason);
            _recordMarketFailure(fromMarket, fromIdx);
            return (0, fromMarket, toMarket);
        }

        // Safe deposit to target
        _refreshApyCache(toMarket);
        if (!_safeDepositToMarket(toMarket, moveAmount)) {
            _recordMarketFailure(toMarket, toIdx);
            // Re-deposit to source as fallback
            _refreshApyCache(fromMarket);
            _safeDepositToMarket(fromMarket, moveAmount);
            // Worst case: funds idle in adapter. Strategy will recall via withdraw.
            return (0, fromMarket, toMarket);
        }

        _recordMarketSuccess(toMarket);

        // Accounting: move principal
        uint256 fromP = principal[fromIdx];
        uint256 delta = fromP < moveAmount ? fromP : moveAmount;
        principal[fromIdx] = fromP - delta;
        principal[toIdx] += moveAmount;

        activeIdx = toIdx;
        lastOptimizeTs = uint64(block.timestamp);
        _refreshNavCache();
        emit IntraRebalanced(fromMarket, toMarket, moveAmount);
        return (moveAmount, fromMarket, toMarket);
    }

    // ===== Telemetry/API =====
    function markets() external view returns (address[] memory) {
        uint256 n = mkts.length;
        address[] memory out = new address[](n);
        for (uint256 i = 0; i < n; ++i) {
            out[i] = mkts[i].addr;
        }
        return out;
    }

    function activeMarket() external view returns (address) {
        return mkts[activeIdx].addr;
    }

    function positions() external view returns (uint256[] memory assetsByMarket) {
        uint256 n = mkts.length;
        assetsByMarket = new uint256[](n);
        for (uint256 i = 0; i < n; ++i) {
            address m = mkts[i].addr;
            if (m == address(0)) continue;
            uint256 shares = IERC20(m).balanceOf(address(this));
            (bool ok, uint256 assets) = _safeConvertToAssets(m, shares);
            assetsByMarket[i] = ok ? assets : principal[i];
        }
    }

    function effectiveAPYBps() external view returns (uint16) {
        uint256 tvl = totalAssets();
        if (tvl < 1) return 0; // slither: incorrect-equality - use < 1 instead of == 0
        uint256 n = mkts.length;
        uint256 sum = 0;
        for (uint256 i = 0; i < n; ++i) {
            address m = mkts[i].addr;
            if (m == address(0)) continue;
            uint256 shares = IERC20(m).balanceOf(address(this));
            if (shares < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
            (bool ok, uint256 alloc) = _safeConvertToAssets(m, shares);
            if (!ok) alloc = principal[i]; // fallback
            uint16 apy = getAPYOnChain(m);
            sum += alloc * apy;
        }
        uint256 result = sum / tvl;
        if (result > type(uint16).max) return type(uint16).max;
        return uint16(result);
    }

    // ===== Internal: Market scoring, APY, selection =====

    /// @dev View-safe wrapper — all callsites use this. Falls back to cached APY.
    function getAPYOnChain(address market) internal view returns (uint16) {
        return _getAPYOnChainOrCached(market);
    }

    function getBestMarket() internal view returns (uint8 idx, uint16 apy) {
        uint256 n = mkts.length;
        uint16 best = 0;
        uint8 bestIdx = 0;
        for (uint8 i = 0; i < n; ++i) {
            Market storage m = mkts[i];
            if (!m.enabled || m.flagged || m.addr == address(0)) continue;
            uint16 apy_ = getAPYOnChain(m.addr);
            if (apy_ > best) {
                best = apy_;
                bestIdx = i;
            }
        }
        return (bestIdx, best);
    }

    function getActiveOrBestMarket() internal view returns (uint8) {
        Market storage m = mkts[activeIdx];
        if (m.enabled && !m.flagged && m.addr != address(0)) return activeIdx;
        (uint8 bestIdx,) = getBestMarket();
        return bestIdx;
    }

    // Returns (fromIdx, toIdx, moveAmount, netBenefitBps)
    function getRebalancePlan() internal view returns (uint8, uint8, uint256, int256) {
        // Find best and worst market by score, and amount to move
        uint8 n = uint8(mkts.length);
        if (n < 2) return (0, 0, 0, 0);
        // Calculate scores for enabled markets
        uint16[] memory scores = new uint16[](n);
        for (uint8 i = 0; i < n; ++i) {
            scores[i] = marketScore(i);
        }
        // Find fromIdx (lowest) and toIdx (highest)
        uint8 fromIdx = 0;
        uint8 toIdx = 0;
        uint16 minScore = type(uint16).max;
        uint16 maxScore = 0;
        for (uint8 i = 0; i < n; ++i) {
            if (!mkts[i].enabled || mkts[i].addr == address(0)) continue;
            if (scores[i] < minScore) {
                minScore = scores[i];
                fromIdx = i;
            }
            if (!mkts[i].flagged && scores[i] > maxScore) {
                maxScore = scores[i];
                toIdx = i;
            }
        }
        if (fromIdx == toIdx) return (0, 0, 0, 0);
        // Compute move amount (all alloc in fromIdx above drift) — safe call
        (bool okFrom, uint256 fromAlloc) = _safeConvertToAssets(
            mkts[fromIdx].addr, IERC20(mkts[fromIdx].addr).balanceOf(address(this))
        );
        if (!okFrom) return (0, 0, 0, 0); // Can't rebalance if can't price source market
        uint256 tvl = totalAssets();
        uint256 minMove = tvl * rebalanceMinMoveBps / BPS_DENOM;
        if (fromAlloc < minMove) return (0, 0, 0, 0);
        // Compute benefit/cost
        uint16 apyFrom = getAPYOnChain(mkts[fromIdx].addr);
        uint16 apyTo = getAPYOnChain(mkts[toIdx].addr);
        require(fromAlloc <= uint256(type(int256).max), "MorphoUsdcMultiMarket: fromAlloc overflow");
        require(
            gasCostUSDC <= uint256(type(int256).max), "MorphoUsdcMultiMarket: gasCostUSDC overflow"
        );
        // casting to int256 is safe because overflow is checked above (uint16/uint8 always fit in int256)
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 deltaAPY = int256(uint256(apyTo)) - int256(uint256(apyFrom));
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 grossBenefit = int256(fromAlloc) * deltaAPY * int256(uint256(gateHorizonDays))
            / (int256(uint256(BPS_DENOM)) * 365);
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 moveCost = int256(gasCostUSDC) + int256(fromAlloc)
            * int256(uint256(slippageBpsEstimate + withdrawalSpreadBpsEstimate))
            / int256(uint256(BPS_DENOM));
        int256 netBenefit = grossBenefit - moveCost;
        int256 netBenefitBps =
            netBenefit * int256(uint256(BPS_DENOM)) / int256(fromAlloc < 1 ? 1 : fromAlloc); // slither: incorrect-equality - use < 1 instead of == 0
        return (fromIdx, toIdx, fromAlloc, netBenefitBps);
    }

    // Market composite score (0..10000) — hardened with safe calls
    function marketScore(uint8 idx) internal view returns (uint16) {
        Market storage m = mkts[idx];
        if (!m.enabled || m.addr == address(0)) return 0;
        // APY (safe: _getAPYOnChainOrCached never reverts)
        uint16 apy = getAPYOnChain(m.addr);
        // Liq: liquidity ratio (cash/tvl, bps) — safe calls
        uint256 shares = IERC20(m.addr).balanceOf(address(this));
        (bool okAssets, uint256 assets) = _safeConvertToAssets(m.addr, shares);
        if (!okAssets) assets = principal[idx];

        // Safe totalAssets call for market TVL
        (bool okTvl, bytes memory tvlData) =
            m.addr.staticcall(abi.encodeWithSignature("totalAssets()"));
        uint256 tvl = (okTvl && tvlData.length >= 32) ? abi.decode(tvlData, (uint256)) : 0;

        uint256 cash = IERC20(underlying).balanceOf(m.addr);
        uint256 liqCalc = tvl == 0 ? 0 : (cash * BPS_DENOM) / tvl;
        if (liqCalc > type(uint16).max) liqCalc = type(uint16).max;
        uint16 liq = uint16(liqCalc);
        // Risk: 10000 - riskScoreBps
        uint16 risk = BPS_DENOM - m.riskScoreBps;
        // Stability: use APY as proxy (no EMA)
        uint16 stability = apy;
        // Incentive: global
        uint16 incentive = incentiveBpsGlobal;
        // Weighted sum
        uint16 score = uint16(
            (uint256(wAPY)
                    * apy
                    + uint256(wLiq)
                    * liq
                    + uint256(wRisk)
                    * risk
                    + uint256(wStability)
                    * stability
                    + uint256(wIncentive)
                    * incentive) / BPS_DENOM
        );
        return score;
    }

    // Sort markets by APY, ascending if asc=true, descending if asc=false
    function sortMarketsByAPY(bool asc) internal view returns (uint8[] memory idxs) {
        uint256 n = mkts.length;
        idxs = new uint8[](n);
        uint16[] memory apys = new uint16[](n);
        // Each valuation can traverse an underlying vault's markets. Snapshot
        // once per sort, rather than repeating external reads for every comparison.
        for (uint8 i; i < n; ++i) {
            idxs[i] = i;
            apys[i] = getAPYOnChain(mkts[i].addr);
        }
        for (uint8 i; i < n; ++i) {
            uint8 best = i;
            for (uint8 j = i + 1; j < n; ++j) {
                if (asc ? apys[idxs[j]] < apys[idxs[best]] : apys[idxs[j]] > apys[idxs[best]]) best = j;
            }
            if (best != i) (idxs[i], idxs[best]) = (idxs[best], idxs[i]);
        }
    }

    // ===== Idle Asset & Emergency Recovery =====
    event IdleAssetSwept(uint256 amount);
    event EmergencyPullExecuted(uint256 amount);
    /// @dev SLITHER-FIX-3: per-market redeem result captured for incident-response observability.
    event EmergencyMarketRedeemed(uint256 indexed marketIdx, address indexed market, uint256 shares, uint256 assetsOut);
    /// @dev SLITHER-FIX-6: optimize() per-market move telemetry.
    event OptimizeMarketWithdrawn(uint256 indexed fromIdx, uint256 indexed toIdx, uint256 requested, uint256 actualWithdrawn);

    function idleAssetBalance() public view returns (uint256) {
        return IERC20(underlying).balanceOf(address(this));
    }

    /// @notice Returns invested assets from cached per-market NAV (O(n) reads from storage, no external calls)
    function investedAssets() public view returns (uint256 total) {
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (principal[i] == 0 && cachedMarketNav[i] == 0) continue; // skip empty
            total += cachedMarketNav[i];
        }
    }

    /// @notice Returns invested assets via live external calls (expensive, use for off-chain reads)
    function investedAssetsLive() public view returns (uint256 sum) {
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            address m = mkts[i].addr;
            if (m == address(0)) continue;
            uint256 shares = IERC20(m).balanceOf(address(this));
            if (shares < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
            (bool ok, uint256 assets) = _safeConvertToAssets(m, shares);
            sum += ok ? assets : principal[i];
        }
    }

    /// @notice Refresh cached NAV for all markets (callable by vault)
    function refreshNavCache() external onlyVault {
        _refreshNavCache();
    }

    /// @notice Internal: refresh cached NAV for all markets
    function _refreshNavCache() internal {
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            if (principal[i] == 0) { cachedMarketNav[i] = 0; continue; }
            address m = mkts[i].addr;
            if (m == address(0)) { cachedMarketNav[i] = 0; continue; }
            uint256 shares = IERC20(m).balanceOf(address(this));
            if (shares < 1) { cachedMarketNav[i] = 0; continue; }
            (bool ok, uint256 assets) = _safeConvertToAssets(m, shares);
            cachedMarketNav[i] = ok ? assets : principal[i];
        }
    }

    function sweepIdleAssetToVault() external nonReentrant onlyVault {
        uint256 idle = IERC20(underlying).balanceOf(address(this));
        require(idle > 0, "no idle");
        IERC20(underlying).safeTransfer(vault, idle);
        emit IdleAssetSwept(idle);
    }

    function emergencyPullAllToVault() external nonReentrant onlyVault {
        uint256 n = mkts.length;
        for (uint256 i = 0; i < n; ++i) {
            address m = mkts[i].addr;
            if (m == address(0)) continue;
            uint256 shares = IERC20(m).balanceOf(address(this));
            if (shares < 1) continue; // slither: incorrect-equality - use < 1 instead of == 0
            try IERC4626Like(m).redeem(shares, address(this), address(this)) returns (uint256 _assetsOut) {
                emit EmergencyMarketRedeemed(i, m, shares, _assetsOut);
            } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                emit EmergencyMarketRedeemed(i, m, shares, 0);
            }
            principal[i] = 0;
        }
        principalTotal = 0;
        // Transfer FULL balance (withdrawn + any pre-existing idle) to vault
        uint256 fullBalance = IERC20(underlying).balanceOf(address(this));
        if (fullBalance > 0) {
            IERC20(underlying).safeTransfer(vault, fullBalance);
        }
        emit EmergencyPullExecuted(fullBalance);
    }

    // ===== Fallback =====
    // coverage-ignore: ETH guard — intentional revert, no asset path
    receive() external payable {
        revert("MorphoAdapter: no ether");
    }
    event AdapterOperationFailed(bytes4 indexed operation, bytes reason);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

// --- OpenZeppelin imports ---
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

// --- Venus vToken minimal interface ---
interface IVToken {
    function underlying() external view returns (address);
    function mint(uint256 mintAmount) external returns (uint256); // 0 = success
    function redeemUnderlying(uint256 redeemAmount) external returns (uint256); // 0 = success
    function redeem(uint256 redeemTokens) external returns (uint256); // 0 = success
    function balanceOf(address owner) external view returns (uint256);
    function exchangeRateCurrent() external returns (uint256); // NOT view - accrues interest
    function exchangeRateStored() external view returns (uint256); // view version
    function supplyRatePerBlock() external view returns (uint256);
    function blocksOrSecondsPerYear() external view returns (uint256);
    function accrueInterest() external returns (uint256); // 0 = success, Compound error code otherwise
    function getCash() external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function totalBorrows() external view returns (uint256);
}

// --- Venus Comptroller (claim XVS rewards) ---
interface IVenusComptroller {
    function claimVenus(address holder, address[] calldata vTokens) external;
}

// --- RewardSwapHelper interface (Step 4 reward pipeline) ---
interface IRewardSwapHelper {
    function canSwap(address rewardToken) external view returns (bool);
    function previewExpectedOut(address rewardToken, uint256 amountIn) external view returns (uint256);
    function swapToUSDC(address rewardToken, uint256 amountIn, address receiver) external returns (uint256);
}

// --- ILendingAdapter interface ---
interface ILendingAdapter {
    function name() external view returns (string memory);
    function underlying() external view returns (address);
    function totalAssets() external view returns (uint256);
    function withdrawableAssets() external view returns (uint256);
    function deposit(uint256 assets) external;
    function withdraw(uint256 assets, address receiver) external returns (uint256 withdrawn);
    function currentAPYBps() external view returns (uint16);
    function incentiveAPYBps() external view returns (uint16);
    function harvestableProfit() external view returns (uint256);
    function harvest(address receiver) external returns (uint256 realized);
    function maxCapacity() external view returns (uint256);
    function externalMarketTVL() external view returns (uint256);
    function isPushMode() external pure returns (bool);
    function idleAssetBalance() external view returns (uint256);
    function investedAssets() external view returns (uint256);
    function sweepIdleAssetToVault() external;
    function emergencyPullAllToVault() external;
}

/// @title VenusUsdcMultiMarketAdapter
/// @notice Lending adapter for Venus vUSDC_Core on Arbitrum.
/// @dev Raw vToken interface (Compound-fork semantics): mint/redeem, not deposit/withdraw.
///      Single-market adapter targeting vUSDC_Core only.
///      Mode: PULL (approve underlying then mint).
contract VenusUsdcMultiMarketAdapter is ILendingAdapter, AccessControl, ReentrancyGuard, Initializable {
    using SafeERC20 for IERC20;

    // --- Roles ---
    bytes32 public constant PARAM_ROLE = keccak256("PARAM_ROLE");

    // --- Constants ---
    /// @dev Arbitrum One chain ID (informational; chain guard removed in V10 for portability).
    uint256 public constant ARBITRUM_CHAIN_ID = 42161;

    // --- Immutable Storage ---
    // --- V10 Storage (was immutable in V9.x; logically immutable post-initialize) ---
    address public override underlying; // USDC
    address public vault;               // Strategy (no-custody)
    address public vToken;              // Venus vUSDC_Core

    // --- Configurable Storage ---
    uint256 public capacity; // Deposit cap (0 = unlimited)

    // --- Reward Pipeline v1 (Phase 4 Step 4.3) ---
    /// @notice Reward token (typically XVS). address(0) = pipeline disabled.
    address public rewardToken;
    /// @notice Venus Comptroller for claimVenus call.
    address public comptroller;
    /// @notice Configurable swap helper.
    address public swapHelper;
    /// @notice Realized reward APR in bps (gov-set from off-chain measurement).
    uint16 public realizedRewardAPRBps;
    /// @notice Haircut applied to realized reward APR. LOSS percentage in bps.
    ///         Default 7500 = 75% loss -> retain 25%. Range [0, 10000].
    uint16 public incentiveHaircutBps = 7500;

    /// @notice Rate slots per year (seconds for time-based Venus markets).
    /// @dev Legacy getter name retained. Modern markets supply their own normalization.
    uint256 public blocksPerYear;

    // --- Events ---
    event Supplied(uint256 assets);
    event Withdrawn(uint256 assets, address receiver);
    event CapacityUpdated(uint256 capacity);
    event IdleAssetSwept(uint256 amount);
    event EmergencyPullExecuted(uint256 amount);

    // --- Reward Pipeline Events ---
    event RewardConfigInitialized(address rewardToken, address comptroller, address swapHelper);
    event SwapHelperUpdated(address swapHelper);
    event RealizedRewardAPRUpdated(uint16 bps);
    event IncentiveHaircutUpdated(uint16 bps);
    event RewardsClaimed(uint256 amount);
    event RewardClaimFailed(address indexed controller, address indexed market, bytes reason);
    event HarvestExecuted(address rewardToken, uint256 amountIn, uint256 usdcOut, address receiver);
    event SwapDeferred(address rewardToken, uint256 pendingBalance, string reason);

    // --- Modifiers ---
    modifier onlyVault() {
        require(msg.sender == vault, "NotVault");
        _;
    }

    // --- Constructor ---

    /// @notice One-shot initialization called atomically by AdapterFactory.
    /// @dev chain-id check removed per V10 chain-portability goal; deploy script must target correct chain.
    function initialize(
        address usdc_,
        address admin_,
        address vault_,
        uint256 capacity_,
        address vToken_,
        uint256 blocksPerYear_
    ) external initializer {
        require(
            usdc_ != address(0) && admin_ != address(0)
                && vault_ != address(0) && vToken_ != address(0),
            "zero"
        );
        require(IVToken(vToken_).underlying() == usdc_, "vToken/asset mismatch");
        require(blocksPerYear_ > 0 && blocksPerYear_ <= 200_000_000, "blocksPerYear");

        underlying = usdc_;
        vault = vault_;
        vToken = vToken_;
        capacity = capacity_;
        // Venus retains supplyRatePerBlock() even on time-based deployments.
        // Prefer the market normalization; the argument is only for legacy markets.
        uint256 slots = blocksPerYear_;
        try IVToken(vToken_).blocksOrSecondsPerYear() returns (uint256 marketSlots) {
            require(marketSlots > 0 && marketSlots <= 200_000_000, "market slots/year");
            slots = marketSlots;
        } catch {}
        blocksPerYear = slots;

        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
        _grantRole(PARAM_ROLE, admin_);
    }

    // ═══════════════════════════════════════════════════════════
    //  INTERNAL HELPERS
    // ═══════════════════════════════════════════════════════════

    /// @notice Converts vToken balance to underlying using stored exchange rate.
    /// @dev Uses exchangeRateStored() (view-safe, does NOT accrue interest).
    ///      Conservative bias: understates NAV by at most 1 block of Venus interest
    ///      (on Arbitrum ≈ 0.25s at 5% APY → < 0.000004% drift per block).
    ///      Keepers should call accrueVenusInterest() before critical operations
    ///      to sync the stored rate with on-chain accruals.
    ///      Scale: exchangeRate is 1e(18 - 8 + underlyingDecimals) = 1e16 for USDC 6dec.
    ///      investedAssets = vTokenBal * exchangeRate / 1e18
    function _vTokenToUnderlying(uint256 vTokenBal) internal view returns (uint256) {
        if (vTokenBal == 0) return 0;
        uint256 rate = IVToken(vToken).exchangeRateStored();
        return (vTokenBal * rate) / 1e18;
    }

    // ═══════════════════════════════════════════════════════════
    //  KEEPER OPERATIONS
    // ═══════════════════════════════════════════════════════════

    /// @notice Triggers Venus interest accrual, updating exchangeRateStored to current value.
    ///         Permissionless — any address may call. Keepers should invoke this before
    ///         deposit/withdraw operations to minimise exchange-rate drift in totalAssets().
    ///         On Arbitrum the drift is negligible (<0.000004%/block at 5% APY), but on
    ///         slower chains (Ethereum L1 12s blocks) the per-block gap is ~48× larger.
    /// @return err 0 on success; non-zero Compound error code on failure (reverts for safety).
    function accrueVenusInterest() external returns (uint256 err) {
        err = IVToken(vToken).accrueInterest();
        require(err == 0, "Venus: accrueInterest failed");
    }

    // ═══════════════════════════════════════════════════════════
    //  ILendingAdapter: METADATA
    // ═══════════════════════════════════════════════════════════

    function name() external pure override returns (string memory) {
        return "Venus_USDC_Core_Adapter_Arbitrum";
    }

    /// @notice Returns false — Venus uses PULL deposit pattern
    function isPushMode() external pure override returns (bool) {
        return false;
    }

    // ═══════════════════════════════════════════════════════════
    //  ILendingAdapter: ACCOUNTING
    // ═══════════════════════════════════════════════════════════

    function idleAssetBalance() public view override returns (uint256) {
        return IERC20(underlying).balanceOf(address(this));
    }

    /// @notice Assets invested in Venus = vToken balance * exchangeRateStored / 1e18
    function investedAssets() public view override returns (uint256) {
        uint256 vBal = IVToken(vToken).balanceOf(address(this));
        return _vTokenToUnderlying(vBal);
    }

    function totalAssets() public view override returns (uint256) {
        return investedAssets() + idleAssetBalance();
    }

    /// @notice Withdrawable limited by pool liquidity (getCash)
    function withdrawableAssets() public view override returns (uint256) {
        uint256 invested = investedAssets();
        uint256 cash = IVToken(vToken).getCash();
        return invested < cash ? invested : cash;
    }

    // ═══════════════════════════════════════════════════════════
    //  ILendingAdapter: LIFECYCLE
    // ═══════════════════════════════════════════════════════════

    function deposit(uint256 assets) external override nonReentrant onlyVault {
        require(assets > 0, "ZERO_ASSETS");
        if (capacity > 0) require(totalAssets() + assets <= capacity, "CAP");

        // Gas: cache `underlying`/`vToken` locally -- both set once in
        // initialize() with no setter, avoids re-reading storage across the
        // transferFrom/approve/mint/revoke sequence below.
        address underlying_ = underlying;
        address vToken_ = vToken;

        // PULL pattern: transfer USDC from strategy to adapter
        IERC20(underlying_).safeTransferFrom(msg.sender, address(this), assets);

        // Just-in-time approval
        IERC20(underlying_).forceApprove(vToken_, assets);

        // Venus mint: returns 0 on success
        uint256 err = IVToken(vToken_).mint(assets);
        require(err == 0, "Venus:mint failed");

        // Revoke approval
        IERC20(underlying_).forceApprove(vToken_, 0);

        emit Supplied(assets);
    }

    /// @dev Receiver forced: always sends to vault, ignores 'receiver' param
    function withdraw(
        uint256 assets,
        address /*receiver*/
    )
        external
        override
        nonReentrant
        onlyVault
        returns (uint256 withdrawn)
    {
        require(assets > 0, "ZERO_ASSETS");
        uint256 want = assets;
        uint256 maxOut = withdrawableAssets();
        if (want > maxOut) want = maxOut;
        require(want > 0, "nothing withdrawable");

        // Venus redeemUnderlying: returns 0 on success
        uint256 err = IVToken(vToken).redeemUnderlying(want);
        require(err == 0, "Venus:redeem failed");

        // Transfer redeemed USDC to vault
        IERC20(underlying).safeTransfer(vault, want);
        withdrawn = want;

        emit Withdrawn(withdrawn, vault);
    }

    // ═══════════════════════════════════════════════════════════
    //  ILendingAdapter: YIELD
    // ═══════════════════════════════════════════════════════════

    /// @notice Simple annualized supply rate (APR), exposed through the adapter APY API.
    /// @dev The rate is per slot: second on modern Arbitrum Venus, block on legacy markets.
    function currentAPYBps() external view override returns (uint16) {
        uint256 rate = IVToken(vToken).supplyRatePerBlock();
        uint256 apyWad = rate * blocksPerYear; // 1e18 scale
        uint256 bps = apyWad / 1e14;             // 1e18 → 1e4 (bps)
        // casting to uint16 is safe because overflow is checked with ternary
        // forge-lint: disable-next-line(unsafe-typecast)
        return bps > type(uint16).max ? type(uint16).max : uint16(bps);
    }

    /// @notice Effective incentive APY in bps after haircut.
    function incentiveAPYBps() external view override returns (uint16) {
        if (realizedRewardAPRBps == 0) return 0;
        uint256 net = (uint256(realizedRewardAPRBps) * (10_000 - uint256(incentiveHaircutBps))) / 10_000;
        return net > type(uint16).max ? type(uint16).max : uint16(net);
    }

    /// @notice USDC-equivalent of pending raw reward tokens (M1 pre-flight gate).
    function harvestableProfit() external view override returns (uint256) {
        if (rewardToken == address(0)) return 0;
        uint256 bal = IERC20(rewardToken).balanceOf(address(this));
        if (bal == 0) return 0;
        if (swapHelper == address(0)) return 0;
        try IRewardSwapHelper(swapHelper).canSwap(rewardToken) returns (bool ok) {
            if (!ok) return 0;
        } catch { return 0; }
        try IRewardSwapHelper(swapHelper).previewExpectedOut(rewardToken, bal) returns (uint256 e) {
            return e;
        } catch { return 0; }
    }

    /// @notice Claim XVS via comptroller, then swap to USDC if oracle fresh (M2).
    function harvest(address receiver) external override nonReentrant onlyVault returns (uint256 realized) {
        if (rewardToken == address(0) || comptroller == address(0)) return 0;

        // 1. Claim from Comptroller
        address[] memory vTokens = new address[](1);
        vTokens[0] = vToken;
        try IVenusComptroller(comptroller).claimVenus(address(this), vTokens) {} catch (bytes memory reason) {
            emit RewardClaimFailed(comptroller, vToken, reason);
        }

        uint256 bal = IERC20(rewardToken).balanceOf(address(this));
        if (bal > 0) emit RewardsClaimed(bal);
        if (bal == 0) return 0;

        // 2. M2 graceful swap
        if (swapHelper == address(0)) {
            emit SwapDeferred(rewardToken, bal, "no-helper");
            return 0;
        }
        bool ok;
        try IRewardSwapHelper(swapHelper).canSwap(rewardToken) returns (bool v) { ok = v; }
        catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason); ok = false; }
        if (!ok) {
            emit SwapDeferred(rewardToken, bal, "oracle-stale");
            return 0;
        }

        IERC20(rewardToken).forceApprove(swapHelper, bal);
        try IRewardSwapHelper(swapHelper).swapToUSDC(rewardToken, bal, receiver) returns (uint256 out) {
            realized = out;
            emit HarvestExecuted(rewardToken, bal, out, receiver);
        } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
            emit SwapDeferred(rewardToken, bal, "swap-revert");
            realized = 0;
        }
        IERC20(rewardToken).forceApprove(swapHelper, 0);
    }

    // ═══════════════════════════════════════════════════════════
    //  ILendingAdapter: LIMITS
    // ═══════════════════════════════════════════════════════════

    function maxCapacity() external view override returns (uint256) {
        return capacity == 0 ? type(uint256).max : capacity;
    }

    function setCapacity(uint256 capacity_) external onlyRole(PARAM_ROLE) {
        capacity = capacity_;
        emit CapacityUpdated(capacity_);
    }

    // --- Reward Pipeline Admin (Step 4.3) ---

    /// @notice One-shot wiring of reward pipeline. Write-once for token+comptroller.
    function initRewardConfig(
        address rewardToken_,
        address comptroller_,
        address swapHelper_
    ) external onlyRole(PARAM_ROLE) {
        require(rewardToken == address(0) && comptroller == address(0), "already-init");
        require(rewardToken_ != address(0) && comptroller_ != address(0), "zero");
        rewardToken = rewardToken_;
        comptroller = comptroller_;
        swapHelper = swapHelper_;
        emit RewardConfigInitialized(rewardToken_, comptroller_, swapHelper_);
    }

    function setSwapHelper(address swapHelper_) external onlyRole(PARAM_ROLE) {
        swapHelper = swapHelper_;
        emit SwapHelperUpdated(swapHelper_);
    }

    function setRealizedRewardAPRBps(uint16 bps) external onlyRole(PARAM_ROLE) {
        realizedRewardAPRBps = bps;
        emit RealizedRewardAPRUpdated(bps);
    }

    function setIncentiveHaircutBps(uint16 bps) external onlyRole(PARAM_ROLE) {
        require(bps <= 10_000, "bps>10000");
        incentiveHaircutBps = bps;
        emit IncentiveHaircutUpdated(bps);
    }

    function pendingRewardBalance() external view returns (uint256) {
        if (rewardToken == address(0)) return 0;
        return IERC20(rewardToken).balanceOf(address(this));
    }

    // ═══════════════════════════════════════════════════════════
    //  ILendingAdapter: EXTERNAL MARKET TVL
    // ═══════════════════════════════════════════════════════════

    /// @notice Returns total USDC supplied to Venus = getCash + totalBorrows
    /// @dev Conservative: returns getCash only if totalBorrows reverts
    function externalMarketTVL() external view override returns (uint256) {
        uint256 cash;
        uint256 borrows;
        try IVToken(vToken).getCash() returns (uint256 c) {
            cash = c;
        } catch {
            return 0;
        }
        try IVToken(vToken).totalBorrows() returns (uint256 b) {
            borrows = b;
        } catch {
            borrows = 0;
        }
        return cash + borrows;
    }

    // ═══════════════════════════════════════════════════════════
    //  IDLE ASSET & EMERGENCY RECOVERY
    // ═══════════════════════════════════════════════════════════

    function sweepIdleAssetToVault() external override nonReentrant onlyVault {
        uint256 idle = IERC20(underlying).balanceOf(address(this));
        require(idle > 0, "no idle");
        IERC20(underlying).safeTransfer(vault, idle);
        emit IdleAssetSwept(idle);
    }

    function emergencyPullAllToVault() external override nonReentrant onlyVault {
        uint256 vBal = IVToken(vToken).balanceOf(address(this));
        if (vBal > 0) {
            try IVToken(vToken).redeem(vBal) returns (uint256 err) {
                require(err == 0, "Venus:emergency redeem failed");
            } catch (bytes memory reason) {
                emit AdapterOperationFailed(msg.sig, reason);
                // Redeem failed - still sweep whatever idle exists
            }
        }
        uint256 fullBalance = IERC20(underlying).balanceOf(address(this));
        if (fullBalance > 0) {
            IERC20(underlying).safeTransfer(vault, fullBalance);
        }
        emit EmergencyPullExecuted(fullBalance);
    }

    // ═══════════════════════════════════════════════════════════
    //  SWEEP PROTECTION
    // ═══════════════════════════════════════════════════════════

    receive() external payable {
        revert("NO_RECEIVE");
    }

    fallback() external payable {
        revert("NO_FALLBACK");
    }
    event AdapterOperationFailed(bytes4 indexed operation, bytes reason);
}

