// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {
    StrategyStorageLayout,
    DepositModeNotSet
} from "./StrategyStorageLayout.sol";
import { ILendingAdapter, IAdapterEmergency } from "../interfaces/ILendingAdapter.sol";

/// @title StrategyAdapterOpsModule — Adapter deposit/failure operations
/// @notice Delegatecall module extracted from StrategyScoringModule for size limit.
///         All functions operate on strategy storage via delegatecall.
contract StrategyAdapterOpsModule is StrategyStorageLayout {
    using SafeERC20 for IERC20Metadata;

    address private immutable _self;

    constructor(address asset_, address _core, address _paramsModule, address _scoringModule, address _adapterOpsModule)
        StrategyStorageLayout(asset_, _core, _paramsModule, _scoringModule, _adapterOpsModule)
    {
        _self = address(this);
    }

    modifier onlyDelegateCall() {
        require(address(this) != _self, "DIRECT_CALL_FORBIDDEN");
        _;
    }

    /// @notice Safe adapter deposit with failure handling + gas EMA recording.
    /// @dev CORE_ROLE (deposit/withdraw best-effort redeploy) or KEEPER_ROLE
    ///      (harvest/deployIdle/rebalance) — msg.sender is preserved through
    ///      the whole delegatecall chain, so this authorizes every legitimate
    ///      top-level caller while closing the unauthenticated fallback path.
    function safeAdapterDeposit(address adapter, uint256 amount)
        external onlyDelegateCall onlyKeeperOrCoreOrRevert returns (bool)
    {
        if (amount == 0) return true;
        if (!depositModeKnown[adapter]) revert DepositModeNotSet();

        bool countFailure = !_retryMode;
        uint256 balanceBefore = ASSET.balanceOf(address(this));
        uint256 gasBefore = gasleft();

        if (pushDepositMode[adapter]) {
            ASSET.safeTransfer(adapter, amount);
            try ILendingAdapter(adapter).deposit(amount) {
                uint256 measured = gasBefore - gasleft();
                if (ASSET.balanceOf(address(this)) < balanceBefore) _updateGasEma(adapter, measured, true);
                _recordAdapterSuccess(adapter);
                return true;
            } catch (bytes memory reason) {
                emit AdapterDepositFailed(adapter, amount, reason);
                // Non-atomic PUSH failure mode: `amount` was already
                // transferred to the adapter above and deposit() then
                // reverted, so it's sitting as untracked idle balance at the
                // adapter. Best-effort auto-recovery: immediately try to
                // sweep it back to the vault so it stays tracked/idle instead
                // of silently stranded until a manual admin sweep. This is
                // best-effort by design — if the adapter's own
                // sweepIdleAssetToVault() also reverts (e.g. same underlying
                // failure condition), AdapterFundsStranded is still emitted
                // for off-chain alerting and manual recovery remains available.
                try IAdapterEmergency(adapter).sweepIdleAssetToVault() {
                } catch (bytes memory sweepReason) {
                    emit AdapterCallFailed(adapter, IAdapterEmergency.sweepIdleAssetToVault.selector, block.timestamp, sweepReason);
                    emit AdapterFundsStranded(adapter, amount);
                }
                // Audit HIGH 1.3 — unify failure handling: gradual decay on BOTH
                // push and pull deposit paths (was immediate-quarantine on push).
                if (countFailure) _recordAdapterFailure(adapter);
                else emit RetryFailureIgnored(adapter, amount);
                return false;
            }
        } else {
            ASSET.forceApprove(adapter, amount);
            try ILendingAdapter(adapter).deposit(amount) {
                ASSET.forceApprove(adapter, 0);
                uint256 measured = gasBefore - gasleft();
                if (ASSET.balanceOf(address(this)) < balanceBefore) _updateGasEma(adapter, measured, true);
                _recordAdapterSuccess(adapter);
                return true;
            } catch (bytes memory reason) {
                ASSET.forceApprove(adapter, 0);
                emit AdapterDepositFailed(adapter, amount, reason);
                if (countFailure) _recordAdapterFailure(adapter);
                else emit RetryFailureIgnored(adapter, amount);
                return false;
            }
        }
    }

    /// @notice Strict deposit (reverts on failure). Called via delegatecall.
    /// @dev CORE_ROLE (normal deposit() path, bestEffort=false) or KEEPER_ROLE.
    function adapterDeposit(address adapter, uint256 amount) external onlyDelegateCall onlyKeeperOrCoreOrRevert {
        if (amount == 0) return;
        if (!depositModeKnown[adapter]) revert DepositModeNotSet();

        uint256 balanceBefore = ASSET.balanceOf(address(this));
        uint256 gasBefore = gasleft();
        if (pushDepositMode[adapter]) {
            ASSET.safeTransfer(adapter, amount);
            ILendingAdapter(adapter).deposit(amount);
        } else {
            ASSET.forceApprove(adapter, amount);
            ILendingAdapter(adapter).deposit(amount);
            ASSET.forceApprove(adapter, 0);
        }
        uint256 measured = gasBefore - gasleft();
        if (ASSET.balanceOf(address(this)) < balanceBefore) _recordExecutionGas(adapter, measured, true);
    }

    /// @notice Record adapter failure with temporal decay. Called via delegatecall.
    /// @dev KEEPER_ROLE only — the sole legitimate caller is the rebalance
    ///      plan's withdraw try/catch (executeRebalanceStep(), KEEPER-gated).
    function recordAdapterFailure(address adapter) external onlyDelegateCall onlyRoleOrRevert(KEEPER_ROLE) {
        _recordAdapterFailure(adapter);
    }

    /// @notice Record adapter success (gradual decrement). Called via delegatecall.
    /// @dev KEEPER_ROLE only — see recordAdapterFailure.
    function recordAdapterSuccess(address adapter) external onlyDelegateCall onlyRoleOrRevert(KEEPER_ROLE) {
        _recordAdapterSuccess(adapter);
    }

    // ── Internal ────────────────────────────────────────────────────────────

    function _recordAdapterFailure(address adapter) internal {
        if (quarantined[adapter]) return;
        uint64 lastFailTs = adapterLastFailureTs[adapter];
        if (
            failureDecaySeconds > 0 && lastFailTs > 0
                && block.timestamp - lastFailTs > failureDecaySeconds
        ) {
            adapterConsecutiveFailures[adapter] = 0;
        }
        adapterLastFailureTs[adapter] = uint64(block.timestamp);

        uint8 failures;
        unchecked {
            failures = adapterConsecutiveFailures[adapter] + 1;
        }
        adapterConsecutiveFailures[adapter] = failures;
        uint8 threshold = adapterQuarantineThreshold;
        if (threshold > 0 && failures >= threshold) {
            quarantined[adapter] = true;
            emit AdapterAutoQuarantined(adapter, failures);
        }
    }

    // coverage-ignore: dead code — no in-tree caller; kept as defensive reserve
    function _recordAdapterFailureImmediate(address adapter) internal {
        if (quarantined[adapter]) return;
        quarantined[adapter] = true;
        emit AdapterAutoQuarantined(adapter, adapterConsecutiveFailures[adapter]);
    }

    function _recordAdapterSuccess(address adapter) internal {
        if (adapterConsecutiveFailures[adapter] > 0) {
            adapterConsecutiveFailures[adapter]--;
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // V10 P0: Execution Gas EMA
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Record withdraw gas for EMA (called by ScoringModule after withdraw)
    /// @dev KEEPER_ROLE only.
    function recordWithdrawGas(address adapter, uint256 gasUsed) external onlyDelegateCall onlyRoleOrRevert(KEEPER_ROLE) {
        _updateGasEma(adapter, gasUsed, false);
        // Keeper-supplied legacy samples are not execution evidence.
        delete withdrawGasObservation[adapter];
    }

    /// @dev Update per-adapter gas EMA. alpha = gasEmaSmoothingBps / 10000.
    function _updateGasEma(address adapter, uint256 gasUsed, bool isDeposit) internal {
        _recordExecutionGas(adapter, gasUsed, isDeposit);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Position sync (extracted from StrategyScoringModule, F-SIZE-01)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Sync positionAssets from live adapter balances. Called via delegatecall.
    ///         force=true: bypass cooldown (rebalance). force=false: respect cooldown (deployIdle).
    /// @dev KEEPER_ROLE only — legitimate callers are deployIdle() and
    ///      computeInputsForPlan() (reached via prepareRebalance()), both KEEPER-gated.
    function syncPositionAssets(bool force) external onlyDelegateCall onlyRoleOrRevert(KEEPER_ROLE) {
        if (!force && lastSyncTs != 0
            && block.timestamp < uint256(lastSyncTs) + minSecondsBetweenSync) return;

        address[] storage _adapters = adapters;
        uint256 n = _adapters.length;
        uint256 totalDrift = 0;
        bool hasNegative = false;
        uint256 _dust = dustTolerance;

        for (uint256 i = 0; i < n;) {
            address adapter = _adapters[i];
            if (enabled[adapter] || positionAssets[adapter] > 0) {
                uint256 oldPos = positionAssets[adapter];
                uint256 actual = _observedTotalAssets(adapter);
                if (actual == 0 && oldPos > 0) {
                    emit PositionSyncSkippedSuspicious(adapter, oldPos, actual);
                    unchecked { ++i; }
                    continue;
                }
                if (oldPos > 0 && actual > oldPos * 3) {
                    emit PositionSyncSkippedSuspicious(adapter, oldPos, actual);
                    unchecked { ++i; }
                    continue;
                }
                uint256 diff = actual > oldPos ? actual - oldPos : oldPos - actual;
                if (actual < oldPos) hasNegative = true;
                unchecked { totalDrift += diff; }
                if (diff >= _dust) {
                    positionAssets[adapter] = actual;
                    emit PositionAssetsSynced(adapter, oldPos, actual);
                }
            }
            unchecked { ++i; }
        }

        lastSyncTs = uint64(block.timestamp);
        if (totalDrift > 0) emit DriftMeasured(totalDrift, hasNegative);

        uint32 _liqStaleness = liquidityStalenessSeconds;
        if (_liqStaleness > 0) {
            for (uint256 j = 0; j < n;) {
                address a = _adapters[j];
                if (enabled[a] && cachedLiquidityTs[a] > 0) {
                    uint256 age = block.timestamp - cachedLiquidityTs[a];
                    if (age > _liqStaleness) {
                        emit LiquidityCacheStale(a, age);
                    }
                }
                unchecked { ++j; }
            }
        }
    }

    // ── Liquidity realization (F-SIZE-02) ────────────────────────────────────

    /// @notice Two-pass pro-rata withdrawal from adapters. Called via delegatecall from vault.
    /// @dev CORE_ROLE (withdraw()'s internal shortfall realization) or KEEPER_ROLE
    ///      (the realizeLiquidity() wrapper's own onlyKeeperOrCore gate).
    function executeRealizeLiquidity(uint256 amountNeeded) external onlyDelegateCall onlyKeeperOrCoreOrRevert {
        uint256 tvl = _tvl();
        if (tvl < 1) return;
        uint256 totalRealized = 0;
        uint256 n = adapters.length;
        for (uint8 pass = 0; pass < 2 && totalRealized < amountNeeded; ++pass) {
            uint256 need = amountNeeded - totalRealized;
            for (uint256 i = 0; i < n && totalRealized < amountNeeded; ++i) {
                address a = adapters[i];
                if (!enabled[a]) continue;
                if (pass == 1 && quarantined[a]) continue;
                uint256 pos = positionAssets[a];
                if (pos < 1) continue;
                uint256 w = pass == 0 ? (need * pos) / tvl : need;
                if (w > pos) w = pos;
                if (w < 1) continue;
                uint256 gasBefore = gasleft();
                try ILendingAdapter(a).withdraw(w, address(this)) returns (uint256 got) {
                    uint256 observed = gasBefore - gasleft();
                    if (got > 0) _recordExecutionGas(a, observed, false);
                    positionAssets[a] -= got;
                    totalRealized += got;
                    _recordAdapterSuccess(a);
                } catch (bytes memory reason) {
                    emit AdapterWithdrawFailed(a, w, reason);
                    _recordAdapterFailure(a);
                }
            }
        }
        if (totalRealized < amountNeeded) emit WithdrawalShortfall(amountNeeded, totalRealized);
        emit LiquidityRealized(amountNeeded, totalRealized);
    }

    // ── View diagnostics (F-SIZE-02) ─────────────────────────────────────────

    /// @notice Weighted average liquidity readiness across enabled adapters.
    function liquidityReadinessBps() external view onlyDelegateCall returns (uint16) {
        uint256 totalWeight = 0;
        uint256 weightedLiq = 0;
        uint256 n = adapters.length;
        for (uint256 i = 0; i < n;) {
            address a = adapters[i];
            if (enabled[a] && !quarantined[a]) {
                uint256 pos = positionAssets[a];
                uint16 liq = cachedLiquidityBps[a];
                if (liq == 0) liq = 5000;
                weightedLiq += pos * liq;
                totalWeight += pos;
            }
            unchecked { ++i; }
        }
        if (totalWeight == 0) return 10000;
        uint256 result = weightedLiq / totalWeight;
        return result > 10000 ? uint16(10000) : uint16(result);
    }

    /// @notice Rebalance penalty: higher = capital should not move.
    function rebalancePenaltyBps() external view onlyDelegateCall returns (uint16) {
        if (rebalancePlanPhase > 0) return 5000;
        if (lastRebalanceTs == 0) return 0;
        uint256 elapsed = block.timestamp - lastRebalanceTs;
        uint256 cooldown = minSecondsBetweenRebalances;
        if (cooldown == 0) return 0;
        if (elapsed >= cooldown) return 0;
        return uint16((2000 * (cooldown - elapsed)) / cooldown);
    }

    /// @notice Returns harvest readiness and harvestable sum.
    function canHarvest() external view onlyDelegateCall returns (bool ok, uint256 sumHarvestable, uint64 sinceLastHarvest) {
        uint256 n = adapters.length;
        for (uint256 i = 0; i < n;) {
            address adapter = adapters[i];
            if (enabled[adapter]) {
                try ILendingAdapter(adapter).harvestableProfit() returns (uint256 profit) {
                    sumHarvestable += profit;
                } catch { }
            }
            unchecked { ++i; }
        }
        uint256 tvl = _tvl();
        ok = (sumHarvestable > 0 && sumHarvestable >= (harvestThresholdBps * tvl) / 1e4)
            || (minSecondsBetweenHarvests > 0 && block.timestamp - lastHarvestTs >= minSecondsBetweenHarvests);
        sinceLastHarvest = uint64(block.timestamp - lastHarvestTs);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

// ═══════════════════════════════════════════════════════════════════════════════
// StrategyAllocCalcModule — delegatecall module for allocation calculation
// ═══════════════════════════════════════════════════════════════════════════════
// Extracted from StrategyScoringModule.sol (REFACTOR-B, 2026-05-04).
// Pure computation cluster: scoring pipeline, normalization, sorting,
// target allocation, cap/headroom checks. No deposits — ScoringModule
// executes deposits after receiving the allocation plan from this module.
// All functions operate on the strategy's storage via delegatecall.
// Direct calls are forbidden.
// ═══════════════════════════════════════════════════════════════════════════════

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { StrategyConfigLib } from "../lib/StrategyConfigLib.sol";

import {
    StrategyStorageLayout,
    AdapterScore,
    QueryFailed
} from "./StrategyStorageLayout.sol";
import { ILendingAdapter } from "../interfaces/ILendingAdapter.sol";

interface IAdapterAPYExt {
    function effectiveAPYBps() external view returns (uint16);
}

contract StrategyAllocCalcModule is StrategyStorageLayout {
    using SafeERC20 for IERC20Metadata;

    // ── Delegatecall-only guard ──────────────────────────────────────────────

    address private immutable _self;

    constructor(address asset_, address _core)
        StrategyStorageLayout(asset_, _core, address(0), address(0), address(0))
    {
        _self = address(this);
    }

    modifier onlyDelegateCall() {
        require(address(this) != _self, "DIRECT_CALL_FORBIDDEN");
        _;
    }

    // ── External entry points (called by ScoringModule via delegatecall) ────

    /// @notice Compute adapter scores. Returns unsorted, unnormalized.
    function execComputeScores(address[] memory enabledAdapters)
        external
        onlyDelegateCall
        returns (AdapterScore[] memory)
    {
        return _computeAdapterScores(enabledAdapters, false);
    }

    /// @notice Transaction-only scoring path; read-only gate keeps the non-emitting entry point.
    function execComputeScoresObserved(address[] memory enabledAdapters)
        external onlyDelegateCall returns (AdapterScore[] memory)
    {
        return _computeAdapterScores(enabledAdapters, true);
    }

    /// @notice Normalize scores in-place.
    function execNormalizeScores(AdapterScore[] memory scores)
        external
        view
        onlyDelegateCall
        returns (AdapterScore[] memory)
    {
        _normalizeScores(scores);
        return scores;
    }

    /// @notice Compute target allocations per adapter given normalized scores and TVL.
    function execTargetAllocations(AdapterScore[] memory scores, uint256 tvl)
        external
        view
        onlyDelegateCall
        returns (uint256[] memory)
    {
        return _targetAllocations(scores, tvl);
    }

    /// @notice Aggregate plan inputs: apys, normScores, moved delta.
    function execAggregatePlanInputs(
        AdapterScore[] memory scores,
        address[] memory enabledList,
        uint256[] memory targetAllocs
    ) external view onlyDelegateCall returns (
        uint16[]  memory apys,
        uint256[] memory normScores,
        uint256 moved
    ) {
        uint256 len = enabledList.length;
        apys = new uint16[](len);
        normScores = new uint256[](len);
        for (uint256 i; i < len;) {
            AdapterScore memory s = scores[i];
            apys[i] = uint16(s.apyBps);
            normScores[i] = s.score;
            uint256 curr = positionAssets[enabledList[i]];
            uint256 tgt = targetAllocs[i];
            moved += curr > tgt ? curr - tgt : tgt - curr;
            unchecked { ++i; }
        }
    }

    /// @notice Compute the deployment allocation plan for idle cash.
    /// @dev    Returns selected adapters and per-adapter target deposit amounts.
    ///         ScoringModule executes the actual deposits after receiving this plan.
    function execSelectAllocation(uint256 amount, bool bestEffort)
        external
        onlyDelegateCall
        returns (address[] memory selected, uint256[] memory targets, uint256 selCount)
    {
        if (amount < 1) return (new address[](0), new uint256[](0), 0);

        address[] memory enabledList = _enabledAdapters();
        if (enabledList.length < 1) return (new address[](0), new uint256[](0), 0);

        AdapterScore[] memory scores = _computeAdapterScores(enabledList, true);
        _normalizeScores(scores);
        _sortAdapterScores(scores);

        return _buildAllocationPlan(scores, amount, bestEffort);
    }

    // ── Internal scoring helpers ─────────────────────────────────────────────

    function _computeAdapterScores(address[] memory enabledAdapters, bool emitFailures)
        internal
        returns (AdapterScore[] memory)
    {
        uint256 n = enabledAdapters.length;
        AdapterScore[] memory scores = new AdapterScore[](n);

        uint16 wA = wAPY;
        uint16 wL = wLiq;
        uint16 wR = wRisk;
        uint16 wS = wStability;
        uint16 wI = wIncentive;

        uint16[] memory rawAPYs = new uint16[](n);
        uint16 maxAPY = 0;
        for (uint256 i = 0; i < n;) {
            uint16 effective = 0;
            try IAdapterAPYExt(enabledAdapters[i]).effectiveAPYBps() returns (uint16 a) {
                effective = a;
            } catch (bytes memory reason) {
                if (emitFailures) emit AdapterCallFailed(enabledAdapters[i], IAdapterAPYExt.effectiveAPYBps.selector, block.timestamp, reason);
            }
            if (effective > 0) {
                rawAPYs[i] = effective;
            } else {
                try ILendingAdapter(enabledAdapters[i]).currentAPYBps() returns (uint16 a) {
                    rawAPYs[i] = a;
                } catch (bytes memory reason) {
                    if (emitFailures) emit AdapterCallFailed(enabledAdapters[i], ILendingAdapter.currentAPYBps.selector, block.timestamp, reason);
                    rawAPYs[i] = 0;
                }
            }
            if (rawAPYs[i] > maxAPY) maxAPY = rawAPYs[i];
            unchecked { ++i; }
        }

        for (uint256 i = 0; i < n;) {
            scores[i] = _scoreOneAdapter(enabledAdapters[i], rawAPYs[i], maxAPY, wA, wL, wR, wS, wI);
            unchecked { ++i; }
        }
        return scores;
    }

    function _scoreOneAdapter(
        address adapter,
        uint16 rawAPY,
        uint16 maxAPY,
        uint16 wA, uint16 wL, uint16 wR, uint16 wS, uint16 wI
    ) internal view returns (AdapterScore memory) {
        uint256 apyNorm = maxAPY > 0 ? (uint256(rawAPY) * 1e4) / maxAPY : 0;
        uint16 incentive = 0;
        uint256 liq = _cachedLiq(adapter);

        uint256 riskScore = riskScoreBps[adapter];
        {
            uint32 _riskStale = riskScoreStalenessSeconds;
            uint64 _riskUpdatedTs = lastRiskScoreUpdateTs[adapter];
            if (_riskStale > 0 && _riskUpdatedTs > 0
                && block.timestamp - _riskUpdatedTs > _riskStale) {
                riskScore = 0;
            }
        }
        uint256 risk = riskScore > 0 ? (10000 - riskScore) : DEFAULT_RISK_BPS;
        uint256 confidence = _tvlConfidence(adapter);
        risk = (risk * confidence) / 1e4;

        uint256 stability = stabilityEMA[adapter];
        {
            uint32 _stabStale = stabilityEMAStalenessSeconds;
            uint64 _stabUpdatedTs = lastStabilityUpdateTs[adapter];
            if (_stabStale > 0 && _stabUpdatedTs > 0
                && block.timestamp - _stabUpdatedTs > _stabStale) {
                stability = 0;
            }
        }
        if (stability < 1) stability = DEFAULT_STABILITY_BPS;

        uint256 score = uint256(wA) * (apyNorm > 10000 ? 10000 : apyNorm)
            + uint256(wL) * (liq > 10000 ? 10000 : liq)
            + uint256(wR) * (risk > 10000 ? 10000 : risk)
            + uint256(wS) * (stability > 10000 ? 10000 : stability)
            + uint256(wI) * (incentive > 10000 ? 10000 : uint256(incentive));
        return AdapterScore(adapter, score, rawAPY, incentive, liq, risk, stability);
    }

    function _normalizeScores(AdapterScore[] memory scores) internal pure {
        uint256 len = scores.length;
        if (len < 1) return;
        uint256 sum = 0;
        for (uint256 i = 0; i < len;) {
            sum += scores[i].score;
            unchecked { ++i; }
        }
        if (sum < 1) {
            uint256 equalShare = 1e4 / len;
            for (uint256 i = 0; i < len;) {
                scores[i].score = equalShare;
                unchecked { ++i; }
            }
            return;
        }
        for (uint256 i = 0; i < len;) {
            scores[i].score = (scores[i].score * 1e4) / sum;
            unchecked { ++i; }
        }
    }

    function _sortAdapterScores(AdapterScore[] memory scores) internal pure {
        uint256 n = scores.length;
        for (uint256 i = 0; i < n;) {
            uint256 maxIdx = i;
            for (uint256 j = i + 1; j < n;) {
                if (scores[j].score > scores[maxIdx].score) maxIdx = j;
                unchecked { ++j; }
            }
            if (maxIdx != i) {
                AdapterScore memory tmp = scores[i];
                scores[i] = scores[maxIdx];
                scores[maxIdx] = tmp;
            }
            unchecked { ++i; }
        }
    }

    function _targetAllocations(AdapterScore[] memory scores, uint256 tvl)
        internal
        view
        returns (uint256[] memory)
    {
        uint256 n = scores.length;
        uint256[] memory allocs = new uint256[](n);
        // Preserve adapter order for scoring/gate alignment; select by composite score.
        bool[] memory selected = new bool[](n);
        uint256 totalScore;
        uint256 limit = _effectiveMaxAdapters(tvl);
        for (uint256 k; k < limit && k < n; ++k) {
            uint256 best = n;
            for (uint256 j; j < n; ++j) {
                address candidate = scores[j].adapter;
                if (selected[j] || flagged[candidate] || quarantined[candidate] || scores[j].score == 0) continue;
                if (best == n || scores[j].score > scores[best].score) best = j;
            }
            if (best == n) break;
            selected[best] = true;
            totalScore += scores[best].score;
        }
        if (totalScore < 1) return allocs;
        uint16 maxRelGov = maxRelativeExposureBps;

        // P0.7 (2026-06-11) — conditional safety margin applied ONLY when a cap
        // binds. Prevents the post-rebalance position from sitting exactly at
        // the cap, which would re-trigger the mandate as soon as the external
        // TVL fluctuated. See docs/SAFETY_ADAPTER_TIER.md.
        uint256 marginBps = uint256(targetSafetyMarginBps);
        uint256 safetyMult = 10_000 - marginBps;

        for (uint256 i = 0; i < n;) {
            if (!selected[i]) { unchecked { ++i; } continue; }
            address adapter = scores[i].adapter;
            // Scoring path always uses NORMAL caps. The fallback caps are
            // intentionally NOT honoured here — opportunistic allocation must
            // not target above the regular cap; only the safety-overflow path
            // can push above it.
            uint256 maxExp = (_effectiveAbsCapBps(adapter, tvl) * tvl) / 1e4;
            uint256 raw = (scores[i].score * tvl) / totalScore;
            uint256 capped = raw > maxExp ? (maxExp * safetyMult) / 10_000 : raw;

            uint256 extTVL = cachedExternalTVL[adapter];
            if (extTVL > 0) {
                uint16 dynRel = _effectiveRelativeCapBps(extTVL);
                uint16 effRel = (maxRelGov > 0 && maxRelGov < dynRel)
                    ? maxRelGov : dynRel;
                uint256 relCap = (uint256(effRel) * extTVL) / 1e4;
                if (capped > relCap) capped = (relCap * safetyMult) / 10_000;
            }

            // === PRESERVE SAFETY TRANCHE (P0.7 — the critical architectural rule)
            // For safety adapters, if the current position is between the
            // normal scoring target and the fallback ceiling, HOLD the
            // position. The overflow path is the ONLY mechanism that grows
            // the safety tranche above the normal target; the rebalance plan
            // must never unwind that legitimate tranche, otherwise the gain
            // from routing overflow to the safety adapter is immediately
            // given back at the next rebalance.
            SafetyFallback memory sf = safetyFallback[adapter];
            if (sf.absCapBps != 0) {
                uint256 current = positionAssets[adapter];
                if (current > capped) {
                    uint256 fbCeiling = (uint256(sf.absCapBps) * tvl) / 1e4;
                    if (adapterMaxExposureBps > 0 && sf.absCapBps > adapterMaxExposureBps)
                        fbCeiling = uint256(adapterMaxExposureBps) * tvl / 1e4;
                    if (extTVL > 0 && sf.relCapBps > 0) {
                        uint256 fbRelCeiling = (uint256(sf.relCapBps) * extTVL) / 1e4;
                        if (fbRelCeiling < fbCeiling) fbCeiling = fbRelCeiling;
                    }
                    if (current <= fbCeiling) {
                        capped = current;
                    }
                }
            }

            // Dynamic-cost plans must be executable at the quoted capacity.
            // A target above maxCapacity otherwise makes every plan fail its
            // preflight even when other venues have a profitable opportunity.
            if (rebalanceGasEstimator != address(0)) {
                try ILendingAdapter(adapter).maxCapacity() returns (uint256 capacity) {
                    if (capped > capacity) capped = capacity;
                } catch { capped = positionAssets[adapter]; }
            }
            allocs[i] = capped;
            unchecked { ++i; }
        }
        return allocs;
    }

    // ── Allocation plan builder (no state writes, bestEffort is advisory) ────

    function _buildAllocationPlan(
        AdapterScore[] memory scores,
        uint256 amount,
        bool bestEffort
    ) internal returns (
        address[] memory selected,
        uint256[] memory targets,
        uint256 selCount
    ) {
        uint256 tvl = _tvl();
        uint256 n = scores.length;
        uint256 _dust = dustTolerance;
        uint16 maxAdapters = _effectiveMaxAdapters(tvl);

        selected = new address[](n);
        uint256[] memory selScores = new uint256[](n);
        uint256[] memory headrooms = new uint256[](n);

        for (uint256 i = 0; i < n && selCount < maxAdapters; ++i) {
            (bool eligible, uint256 headroom) = _checkAdapterEligibility(
                scores[i].adapter, tvl, _dust, bestEffort
            );
            if (!eligible) continue;
            selected[selCount] = scores[i].adapter;
            selScores[selCount] = scores[i].score;
            headrooms[selCount] = headroom;
            selCount++;
        }

        if (selCount < 1) {
            return (selected, new uint256[](0), 0);
        }

        targets = _computeTargets(selected, selScores, headrooms, selCount, amount, _dust);
    }

    /// @notice Read-only cap validation for an already selected rebalance deposit.
    /// @dev Same cap helpers as allocation; called by the gate through delegatecall.
    function validateRebalanceDeposit(address adapter, uint256 projected, uint256 tvl)
        external view onlyDelegateCall returns (bool)
    {
        if (!enabled[adapter] || flagged[adapter] || quarantined[adapter] || depositsDisabled) return false;
        if (_tvlConfidence(adapter) == CONFIDENCE_ZERO) return false;
        if (projected > _effectiveAbsCapBps(adapter, tvl) * tvl / 10000) return false;
        uint256 externalTvl = cachedExternalTVL[adapter];
        if (externalTvl > 0) {
            uint16 cap = _effectiveRelativeCapBps(externalTvl);
            if (maxRelativeExposureBps > 0 && maxRelativeExposureBps < cap) cap = maxRelativeExposureBps;
            if (projected > externalTvl * cap / 10000) return false;
        }
        try ILendingAdapter(adapter).maxCapacity() returns (uint256 capacity) {
            return projected <= capacity;
        } catch { return false; }
    }

    function _checkAdapterEligibility(address adapter, uint256 tvl, uint256 _dust, bool bestEffort)
        internal returns (bool, uint256)
    {
        if (flagged[adapter]) return (false, 0);
        // P0.7 (2026-06-11) — non-safety adapters in mandate cooldown are
        // skipped for opportunistic redeploy. Safety adapters NEVER enter
        // cooldown (the mandate path doesn't set lastRelCapMandateTs for them).
        if (safetyFallback[adapter].absCapBps == 0) {
            uint32 cd = mandateRedeployCooldownSeconds;
            uint64 lastTs = lastRelCapMandateTs[adapter];
            if (cd > 0 && lastTs > 0 && block.timestamp < lastTs + cd) {
                return (false, 0);
            }
        }
        uint256 conf = _tvlConfidence(adapter);
        if (conf == CONFIDENCE_ZERO) return (false, 0);
        uint256 current = positionAssets[adapter];
        uint256 maxExp = (_effectiveAbsCapBps(adapter, tvl) * tvl) / 1e4;
        if (current >= maxExp) return (false, 0);
        uint256 headroom = maxExp - current;
        {
            uint256 extTVL = cachedExternalTVL[adapter];
            if (extTVL > 0) {
                uint16 dynRelCap = _effectiveRelativeCapBps(extTVL);
                uint16 effRelCap = (maxRelativeExposureBps > 0 && maxRelativeExposureBps < dynRelCap)
                    ? maxRelativeExposureBps : dynRelCap;
                uint256 relCap = (extTVL * effRelCap) / 1e4;
                if (current >= relCap) return (false, 0);
                uint256 rh = relCap - current;
                if (rh < headroom) headroom = rh;
            }
        }
        if (!isBootstrapActive()) {
            bool inRamp = block.timestamp < adapterActivatedAt[adapter] + newAdapterRampDuration;
            bool seasoned = isSeasoned[adapter];
            bool rampForDustNeeded = (current <= _dust) && !seasoned;
            bool isNew = (inRamp && current < _effectiveMinSeed(tvl)) || rampForDustNeeded;
            if (isNew) {
                uint256 rawLimit = (uint256(newAdapterRampBps) * tvl) / 1e4;
                if (rawLimit < headroom) headroom = rawLimit;
            }
        }
        try ILendingAdapter(adapter).maxCapacity() returns (uint256 cap) {
            if (cap == 0) { headroom = 0; }
            else if (current + headroom > cap) { headroom = cap > current ? cap - current : 0; }
            if (cap < current) { headroom = 0; }
            else if (cachedAdapterCapacity[adapter] > 0 && cap > 0
                && cachedAdapterCapacity[adapter] < type(uint256).max / MAX_EXTERNAL_TVL_JUMP_BPS) {
                uint256 maxJump = (cachedAdapterCapacity[adapter] * MAX_EXTERNAL_TVL_JUMP_BPS) / 10_000;
                if (cap > maxJump) headroom = headroom / 2;
            }
        } catch (bytes memory reason) {
            emit AdapterCallFailed(adapter, ILendingAdapter.maxCapacity.selector, block.timestamp, reason);
            if (!bestEffort) revert QueryFailed();
            return (false, 0);
        }
        if (headroom < 1) return (false, 0);
        return (true, headroom);
    }

    function _computeTargets(
        address[] memory selected,
        uint256[] memory selScores,
        uint256[] memory headrooms,
        uint256 selCount,
        uint256 amount,
        uint256 _dust
    ) internal pure returns (uint256[] memory targets) {
        targets = new uint256[](selCount);
        uint256 remaining = amount;
        bool[] memory clamped = new bool[](selCount);

        for (uint256 pass = 0; pass < 3 && remaining > _dust; ++pass) {
            uint256 sSum = 0;
            for (uint256 j = 0; j < selCount; ++j) {
                if (!clamped[j]) sSum += selScores[j];
            }
            if (sSum < 1) break;
            uint256 distributed = 0;
            for (uint256 j = 0; j < selCount; ++j) {
                if (clamped[j]) continue;
                uint256 used = targets[j];
                uint256 remainingHeadroom = headrooms[j] > used ? headrooms[j] - used : 0;
                if (remainingHeadroom == 0) { clamped[j] = true; continue; }
                uint256 target = (remaining * selScores[j]) / sSum;
                if (target > remainingHeadroom) { target = remainingHeadroom; clamped[j] = true; }
                targets[j] += target;
                distributed += target;
            }
            remaining -= distributed;
        }
        // Residual redistribution: floor-division across selCount adapters leaves
        // up to (selCount-1) wei unassigned per pass. After the 3-pass loop, if a
        // sub-dust residual remains and an adapter still has headroom, assign it
        // there rather than leaving it as idle. Prevents silent idle accumulation
        // across repeated deployIdle calls (systematic drift).
        if (remaining > 0 && remaining <= _dust) {
            for (uint256 j = 0; j < selCount; ++j) {
                if (clamped[j]) continue;
                uint256 rem = headrooms[j] > targets[j] ? headrooms[j] - targets[j] : 0;
                if (rem >= remaining) {
                    targets[j] += remaining;
                    break;
                }
            }
        }
    }

    // ── Inlined cap/seed helpers (mirrors ScoringModule — same storage context) ─

    // Gas: takes tvl as a parameter instead of recomputing it internally --
    // every call site in this file already has `tvl` in scope (same view
    // call, no intervening state mutation), so the old zero-arg version's
    // internal _tvl() call (external ASSET.balanceOf + a full loop over
    // positionAssets) was pure redundant work, paid up to MAX_ADAPTERS times
    // per deployIdle()/prepareRebalance() cycle.
    function _effectiveMaxAdapters(uint256 tvl) internal view returns (uint16) {
        uint16 staticMax = maxAdaptersPerAllocation;
        uint16 dynamicMax;
        if (tvl < 25_000e6) dynamicMax = 1;
        else if (tvl < 250_000e6) dynamicMax = 2;
        else if (tvl < 1_000_000e6) dynamicMax = 3;
        else if (tvl < 5_000_000e6) dynamicMax = 4;
        else dynamicMax = 5;
        return (staticMax > 0 && staticMax < dynamicMax) ? staticMax : dynamicMax;
    }

    function _effectiveAbsCapBps(address adapter, uint256 tvl) internal view returns (uint256) {
        uint16 dMax = _effectiveMaxAdapters(tvl);
        if (dMax == 0) return 0;
        // A manual one-slot limit may restrict deployment, but must not relax exposure caps.
        if (dMax < 2) dMax = 2;
        uint256 cap = (11000 + uint256(dMax) - 1) / uint256(dMax);
        if (cap > 10000) cap = 10000;
        if (cap < 2500) cap = 2500;
        uint16 globalCeiling = adapterMaxExposureBps;
        if (globalCeiling > 0 && globalCeiling < cap) cap = uint256(globalCeiling);
        cap = (cap * _riskOverlay(adapter)) / 10000;
        cap = (cap * _failureOverlay(adapter)) / 10000;
        cap = (cap * _liquidityOverlay(adapter)) / 10000;
        uint16 floor = adapterAbsCapOverrideBps[adapter];
        if (floor > 0 && cap < uint256(floor)) cap = uint256(floor);
        if (adapterMaxExposureBps > 0 && cap > adapterMaxExposureBps) cap = adapterMaxExposureBps;
        return cap;
    }

    // S4/S3/S5 overlays — delegate to StrategyConfigLib (single source of
    // truth shared with StrategyScoringModule; previously two independent
    // hand-copies, the exact divergence class that caused AUDIT-FINDING-13
    // and the F-SCORING-INV2 regression). See docs/TIER_MODEL.md §4.2-4.4.
    function _riskOverlay(address adapter) internal view returns (uint16) {
        return StrategyConfigLib.riskOverlay(
            riskScoreBps[adapter], riskScoreStalenessSeconds, lastRiskScoreUpdateTs[adapter]
        );
    }

    function _failureOverlay(address adapter) internal view returns (uint16) {
        return StrategyConfigLib.failureOverlay(adapterConsecutiveFailures[adapter]);
    }

    function _liquidityOverlay(address adapter) internal view returns (uint16) {
        return StrategyConfigLib.liquidityOverlay(_cachedLiq(adapter));
    }

    function _effectiveMinSeed(uint256 tvl) internal view returns (uint256) {
        uint256 staticSeed = minNewAdapterSeed;
        uint256 dynamicSeed;
        if (tvl < 250_000e6) dynamicSeed = 100e6;
        else if (tvl < 1_000_000e6) dynamicSeed = 1_000e6;
        else if (tvl < 5_000_000e6) dynamicSeed = 5_000e6;
        else if (tvl < 25_000_000e6) dynamicSeed = 25_000e6;
        else dynamicSeed = (tvl * 200) / 1e4;
        return staticSeed > dynamicSeed ? staticSeed : dynamicSeed;
    }

    // ── Liquidity cache helper ───────────────────────────────────────────────

    function _cachedLiq(address adapter) internal view returns (uint256) {
        return StrategyConfigLib.cachedLiq(
            cachedLiquidityBps[adapter], liquidityStalenessSeconds, cachedLiquidityTs[adapter]
        );
    }

    function isBootstrapActive() public view returns (bool) {
        return bootstrapEndsAt > 0 && block.timestamp < bootstrapEndsAt;
    }

    function idleCash() public view returns (uint256) {
        return ASSET.balanceOf(address(this));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/**
 * @title StrategyParamsModule
 * @notice Operational param functions for UsdcMultiLendingVault, called via delegatecall.
 * @dev    Governance setters (DEFAULT_ADMIN_ROLE + PARAM_ROLE) were extracted to
 *         StrategySettingsModule (REFACTOR-A, 2026-05-04) to stay under EIP-170.
 *
 *         This module retains: position sync, external TVL/liquidity poking,
 *         stability EMA, and operational view helpers.
 */

// FIX P0.L5: AccessControl/Pausable/ReentrancyGuard inherited transitively
// via StrategyStorageLayout — direct imports removed to prevent shadowing.
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { ILendingAdapter, IAdapterEmergency } from "../interfaces/ILendingAdapter.sol";
// FIX P0.L5: import full file → brings in StrategyStorageLayout (parent) +
// all file-scope errors (Unauthorized, Frozen, ParamOutOfRange, ZeroAmount,
// InsufficientBalance, ZeroAddress, etc.) used by setter logic.
import {
    StrategyStorageLayout,
    SkipReason,
    Unauthorized, Frozen, InvalidAdapter, WeightsSumInvalid,
    MinAdaptersTooLow, RiskScoreTooHigh, DurationTooLong, BackfillTooLarge,
    BootstrapInactive, InvalidInput, ParamOutOfRange, ZeroAmount,
    InsufficientBalance, ZeroAddress
} from "./StrategyStorageLayout.sol";

/**
 * @dev CRITICAL: Storage layout must be IDENTICAL to UsdcMultiLendingVault.
 *      We inherit AccessControl + Pausable + ReentrancyGuard in the same order
 *      to guarantee the same slot offsets for inherited state, then declare
 *      all strategy storage variables in the exact same order.
 */
contract StrategyParamsModule is StrategyStorageLayout {
    using SafeERC20 for IERC20Metadata;

    // ── Constants UNIQUE to ParamsModule ────────────────────────────────
    uint256 public constant MAX_EXTERNAL_TVL = 50_000_000_000e6; // 50B USDC

    // ── Events UNIQUE to ParamsModule (not in StorageLayout) ────────────
    event ExternalTVLRejected(address indexed adapter, uint256 previousTvl, uint256 reportedTvl);

    // ── Constructor ─────────────────────────────────────────────────────
    constructor(address asset_, address _core)
        StrategyStorageLayout(asset_, _core, address(0), address(0), address(0))
    {}

    // ══════════════════════════════════════════════════════════════════════
    //  VIEW: ADAPTER REGISTRY
    // ══════════════════════════════════════════════════════════════════════

    function adapterCount() external view returns (uint256) {
        return adapters.length;
    }

    // ══════════════════════════════════════════════════════════════════════
    //  DELEGATED FUNCTIONS (moved from UsdcLendingStrategy for size limit)
    // ══════════════════════════════════════════════════════════════════════

    // FIX P0.L5: DEFAULT_*/CONFIDENCE_* constants inherited from StorageLayout.
    // ExternalTVLPoked event also inherited.
    event ScoringComputed(
        address indexed adapter, uint256 scoreRaw, uint256 scoreNorm,
        uint256 targetAlloc, uint256 currentPos, uint16 apyBps,
        uint256 liqBps, uint256 riskBps, uint256 stabilityBps, uint16 incentiveBps
    );

    // ══════════════════════════════════════════════════════════════════════
    //  POSITION SYNC (PARAM_ROLE)
    // ══════════════════════════════════════════════════════════════════════

    /// @notice Manual full sync — PARAM_ROLE only. Same guards as internal.
    function syncPositionAssets() external onlyRoleOrRevert(PARAM_ROLE) {
        uint256 n = adapters.length;
        uint256 totalDrift = 0;
        bool hasNegative = false;
        uint256 _dust = dustTolerance;
        for (uint256 i = 0; i < n;) {
            address adapter = adapters[i];
            if (enabled[adapter] || positionAssets[adapter] > 0) {
                uint256 oldPos = positionAssets[adapter];
                uint256 actual = _observedTotalAssets(adapter);
                if (actual == 0 && oldPos > 0) {
                    emit PositionSyncSkippedSuspicious(adapter, oldPos, actual);
                    unchecked { ++i; } continue;
                }
                if (oldPos > 0 && actual > oldPos * 3) {
                    emit PositionSyncSkippedSuspicious(adapter, oldPos, actual);
                    unchecked { ++i; } continue;
                }
                uint256 diff = actual > oldPos ? actual - oldPos : oldPos - actual;
                if (actual < oldPos) hasNegative = true;
                unchecked { totalDrift += diff; }
                if (diff >= _dust) {
                    positionAssets[adapter] = actual;
                    emit PositionAssetsSynced(adapter, oldPos, actual);
                }
            }
            unchecked { ++i; }
        }
        lastSyncTs = uint64(block.timestamp);
        if (totalDrift > 0) emit DriftMeasured(totalDrift, hasNegative);
    }

    /// @notice Per-adapter sync (granular) — PARAM_ROLE only.
    function syncPositionAsset(address adapter) external onlyRoleOrRevert(PARAM_ROLE) {
        if (!isAdapter[adapter]) revert InvalidAdapter();
        if (!enabled[adapter] && positionAssets[adapter] == 0) return;
        uint256 oldPos = positionAssets[adapter];
        uint256 actual = _observedTotalAssets(adapter);
        if (actual == 0 && oldPos > 0) { emit PositionSyncSkippedSuspicious(adapter, oldPos, actual); return; }
        if (oldPos > 0 && actual > oldPos * 3) { emit PositionSyncSkippedSuspicious(adapter, oldPos, actual); return; }
        uint256 diff = actual > oldPos ? actual - oldPos : oldPos - actual;
        if (diff >= dustTolerance) {
            positionAssets[adapter] = actual;
            emit PositionAssetsSynced(adapter, oldPos, actual);
        }
    }

    /// @notice View: total bookkeeping drift (monitoring ONLY — expensive off-chain call).
    function drift() external view returns (uint256 totalDrift, bool hasNegative) {
        uint256 n = adapters.length;
        for (uint256 i = 0; i < n;) {
            address adapter = adapters[i];
            if (enabled[adapter] || positionAssets[adapter] > 0) {
                uint256 actual = _safeTotalAssets(adapter);
                uint256 pos = positionAssets[adapter];
                if (actual > pos) { unchecked { totalDrift += actual - pos; } }
                else if (pos > actual) { unchecked { totalDrift += pos - actual; } hasNegative = true; }
            }
            unchecked { ++i; }
        }
    }

    /// @notice View: should sync run? Cheap cooldown check for off-chain callers.
    function shouldSyncPositionAssets() external view returns (bool) {
        if (lastSyncTs != 0 && block.timestamp < uint256(lastSyncTs) + minSecondsBetweenSync) return false;
        return true;
    }

    // ══════════════════════════════════════════════════════════════════════
    //  EXTERNAL TVL CACHE
    // ══════════════════════════════════════════════════════════════════════

    /// @notice Refresh external TVL cache ONLY (no liquidity). KEEPER_ROLE.
    /// @dev    Cheap (~1M gas for 7 adapters). Call pokeLiquidityBatch separately.
    function pokeExternalTVL() external onlyRoleOrRevert(KEEPER_ROLE) {
        address[] memory enabledList = _enabledAdapters();
        uint256 n = enabledList.length;
        for (uint256 i = 0; i < n;) {
            address adapter = enabledList[i];
            (bool tvlOk, uint256 tvl) = _readAdapterUintObserved(adapter, ILendingAdapter.externalMarketTVL.selector);
            if (tvlOk) {
                uint256 prev = cachedExternalTVL[adapter];
                bool valid = true;

                // Layer 1: absolute sanity bound
                if (tvl > MAX_EXTERNAL_TVL) valid = false;

                // Layer 2: delta limiter — reject jumps > 10x previous value
                if (valid && prev > 0) {
                    uint256 maxJump = (prev * MAX_EXTERNAL_TVL_JUMP_BPS) / 10_000;
                    if (tvl > maxJump) valid = false;
                }

                if (valid) {
                    // Phase 1.5: snapshot OLD value before overwrite, but only once per window.
                    // Skip first-time (cachedExternalTVL==0) — no baseline to compare against.
                    uint64 snapshotAge = uint64(block.timestamp) - lastExtTVLSnapshotTs[adapter];
                    if (prev > 0 && snapshotAge >= EXT_TVL_PANIC_WINDOW_SEC) {
                        lastExtTVLSnapshot[adapter]   = prev;
                        lastExtTVLSnapshotTs[adapter] = uint64(block.timestamp);
                    }
                    cachedExternalTVL[adapter] = tvl;
                    cachedExternalTVLTs[adapter] = uint64(block.timestamp);
                    emit ExternalTVLPoked(adapter, tvl);
                } else {
                    emit ExternalTVLRejected(adapter, prev, tvl);
                }
            }

            // Audit HIGH 1.6 fix: populate cachedAdapterCapacity so the delta
            // jump limiter in StrategyAllocCalcModule._checkAdapterEligibility()
            // (which reads this mapping) is no longer permanently inert. Same
            // keeper cadence and try/catch-safe pattern as the externalMarketTVL
            // poke above -- a bricked/reverting maxCapacity() simply leaves the
            // cache at its last known-good value.
            (bool capOk, uint256 cap) = _readAdapterUintObserved(adapter, ILendingAdapter.maxCapacity.selector);
            if (capOk) {
                uint256 prevCap = cachedAdapterCapacity[adapter];
                if (prevCap > 0 && cap > prevCap) {
                    uint256 maxCapJump = (prevCap * MAX_EXTERNAL_TVL_JUMP_BPS) / 10_000;
                    if (cap > maxCapJump) {
                        emit AdapterCapacityJump(adapter, prevCap, cap);
                    }
                } else if (prevCap > 0 && cap < prevCap) {
                    emit AdapterCapacityDecreased(adapter, cap, prevCap);
                }
                cachedAdapterCapacity[adapter] = cap;
            }
            unchecked { ++i; }
        }
    }

    /// @notice Refresh liquidity cache for adapters [start, end). KEEPER_ROLE.
    /// @dev    Morpho alone costs ~3.15M gas. Split into small batches.
    function pokeLiquidityBatch(uint256 start, uint256 end) external onlyRoleOrRevert(KEEPER_ROLE) {
        address[] memory enabledList = _enabledAdapters();
        if (end > enabledList.length) end = enabledList.length;
        if (start >= end) return;
        for (uint256 i = start; i < end;) {
            _pokeLiquidity(enabledList[i]);
            unchecked { ++i; }
        }
    }

    function _pokeLiquidity(address adapter) internal {
        (bool totalOk, uint256 tot) = _readAdapterUintObserved(adapter, ILendingAdapter.totalAssets.selector);
        if (!totalOk) tot = positionAssets[adapter];
        if (tot <= dustTolerance) {
            cachedLiquidityBps[adapter] = 10000; // empty adapter = fully liquid
            cachedLiquidityTs[adapter] = uint64(block.timestamp);
            return;
        }
        (bool withdrawableOk, uint256 wa) = _readAdapterUintObserved(adapter, ILendingAdapter.withdrawableAssets.selector);
        if (!withdrawableOk) wa = positionAssets[adapter];
        uint256 liq = (wa * 1e4) / tot;
        if (liq > 10000) liq = 10000;
        // Store 1 instead of 0 to distinguish "measured zero" from "never cached".
        // _cachedLiq() treats cached==0 as "never cached" → DEFAULT_LIQ_BPS.
        // cached==1 means "measured, near-zero liquidity" → score penalty applied.
        cachedLiquidityBps[adapter] = liq < 1 ? 1 : uint16(liq);
        cachedLiquidityTs[adapter] = uint64(block.timestamp);

        // V9.2 CTO: Update stability EMA in the same observation pass
        try ILendingAdapter(adapter).currentAPYBps() returns (uint16 currApy) {
            _updateStabilityEMA(adapter, currApy);
        } catch (bytes memory reason) {
            emit AdapterCallFailed(adapter, ILendingAdapter.currentAPYBps.selector, block.timestamp, reason);
            // APY query failed — don't penalize stability for query failure
        }
    }

    /// @dev Stability EMA update — measures APY volatility over time (CTO-approved formula).
    ///      denom = max(prevAPY, apyFloorBps)
    ///      deltaRatioBps = min(|curr - prev| * 10000 / denom, 10000)
    ///      rawStability = 10000 - deltaRatioBps
    ///      stabilityEMA = α * rawStability + (1 - α) * oldEMA,  α = 2/(period+1)
    function _updateStabilityEMA(address adapter, uint16 currApyBps) internal {
        uint64 nowTs = uint64(block.timestamp);
        uint64 lastTs = lastStabilityUpdateTs[adapter];

        // Skip overly frequent updates to avoid noisy signal
        uint32 minInterval = minStabilityUpdateInterval;
        if (minInterval == 0) minInterval = 6 hours;
        if (lastTs != 0 && nowTs < lastTs + minInterval) return;

        uint16 prevApyBps = lastPokedAPY[adapter];

        // First observation: seed with neutral default, don't compute delta
        if (prevApyBps == 0 && lastTs == 0) {
            lastPokedAPY[adapter] = currApyBps;
            lastStabilityUpdateTs[adapter] = nowTs;
            if (stabilityEMA[adapter] == 0) {
                stabilityEMA[adapter] = DEFAULT_STABILITY_BPS;
            }
            return;
        }

        // Delta ratio with floor protection
        uint256 floor = apyFloorBps;
        if (floor == 0) floor = 50;
        uint256 denom = prevApyBps > floor ? prevApyBps : floor;
        uint256 diff = currApyBps > prevApyBps
            ? uint256(currApyBps - prevApyBps)
            : uint256(prevApyBps - currApyBps);
        uint256 deltaRatioBps = (diff * 10000) / denom;
        if (deltaRatioBps > 10000) deltaRatioBps = 10000;

        uint16 rawStability = uint16(10000 - deltaRatioBps);

        // EMA smoothing
        uint256 period = stabilityEMAPeriod;
        if (period == 0) period = 7;
        uint256 alphaBps = (2 * 10000) / (period + 1);
        uint256 prevEma = stabilityEMA[adapter];
        if (prevEma == 0) prevEma = DEFAULT_STABILITY_BPS;

        stabilityEMA[adapter] = uint16(
            (alphaBps * uint256(rawStability) + (10000 - alphaBps) * prevEma) / 10000
        );
        lastPokedAPY[adapter] = currApyBps;
        lastStabilityUpdateTs[adapter] = nowTs;
    }

    // NOTE: explainScore() and explainAllocation() moved to StrategyExplainabilityLens
    // (external read-only contract, NOT a delegatecall module). The lens reads strategy
    // public state via getters and reconstructs scoring logic independently.
    // This is best-effort explainability — NOT the canonical economic logic source.
    // See: src/strategies/usdc-lending/lens/StrategyExplainabilityLens.sol

    // NOTE (cleanup): _effectiveMaxAdapters(uint256) and
    // effectiveMinNewAdapterSeed()/_effectiveMinNewAdapterSeed(uint256) were
    // removed from this module. Both were unreachable dead code: the vault's
    // fallback() dispatches to StrategyScoringModule (mods[0]) before
    // StrategyParamsModule (mods[4]), and StrategyScoringModule already
    // implements effectiveMinNewAdapterSeed() with the identical selector, so
    // it always wins the dispatch -- this module's copy could never execute
    // via the vault. Worse, _effectiveMaxAdapters(uint256) had STALE tier
    // thresholds (150K/650K/3M) predating the AUDIT-FINDING-1 fix that
    // corrected them to 25K/250K/1M/5M in StrategyScoringModule/
    // StrategyAllocCalcModule -- leaving it in place risked a future edit
    // mistakenly wiring up the stale copy. See test/strategies/usdc-lending/
    // Dynamic_Seed.t.sol and Scoring_Model.t.sol, which exercise the live
    // StrategyScoringModule implementation via `StrategyParamsModule(address(vault))
    // .effectiveMinNewAdapterSeed()` -- the cast is only for ABI encoding;
    // dispatch still resolves to ScoringModule.

    /// @dev Internal mirror of UsdcLendingStrategy.isBootstrapActive() — used inside delegatecall.
    function _isBootstrapActive() internal view returns (bool) {
        return bootstrapEndsAt > 0 && block.timestamp < bootstrapEndsAt;
    }

    // _tvl (ASSET.balanceOf variant), _enabledAdapters, _clampLiq, _tvlConfidence,
    // _effectiveRelativeCapBps, _safeTotalAssets, _safeWithdrawableAssets — inherited from StrategyStorageLayout.

}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {
    StrategyStorageLayout,
    Overflow,
    GateNotMet
} from "./StrategyStorageLayout.sol";
import {ReadOnlyGasEstimator as GasEstimator} from "../gas/ReadOnlyGasEstimator.sol";
import {ILendingAdapter} from "../interfaces/ILendingAdapter.sol";
import { StrategyConfigLib } from "../lib/StrategyConfigLib.sol";

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

/// @title StrategyRebalanceGateModule — Rebalance policy/gating logic
/// @notice Delegatecall module. Decides IF a rebalance should proceed based on:
///         P0: Dynamic execution cost (EMA-based)
///         P1: Hysteresis (benefit/cost ratio, entry/exit drift, min move)
///         P2: Coordination (recent rebalance penalty, liquidity readiness)
///         P3: Regime (STABLE/VOLATILE/STRESS horizon+confidence adjustments)
/// @dev    Calls ScoringModule.computeRebalanceInputs() via delegatecall to
///         scoringModule address (NOT via fallback — direct module call).
///         All functions require onlyDelegateCall guard.
contract StrategyRebalanceGateModule is StrategyStorageLayout {

    // ── Delegatecall-only guard ──────────────────────────────────────────
    address private immutable _self;

    constructor(address asset_, address _core, address _paramsModule, address _scoringModule, address _adapterOpsModule)
        StrategyStorageLayout(asset_, _core, _paramsModule, _scoringModule, _adapterOpsModule)
    {
        _self = address(this);
    }

    modifier onlyDelegateCall() {
        require(address(this) != _self, "DIRECT_CALL_FORBIDDEN");
        _;
    }

    // ── Selector for ScoringModule.computeRebalanceInputs() ─────────────
    bytes4 private constant COMPUTE_INPUTS_SEL =
        bytes4(keccak256("computeRebalanceInputs()"));

    // ── External functions ──────────────────────────────────────────────

    /// @notice Check if rebalance is warranted. NOT view (uses delegatecall to ScoringModule).
    /// @dev    Replaces the old ScoringModule.canRebalance().
    ///         Called by LendingStrategyUpkeep via strategy fallback routing.
    function canRebalance()
        external
        onlyDelegateCall
        returns (bool ok, uint256 movedEstimateUSDC, int256 netBenefitBps)
    {
        // Pre-checks (same as old canRebalance)
        if (rebalancePlanPhase != 0) return (false, 0, 0);
        uint256 cooldown = minSecondsBetweenRebalances;
        if (rebalancePlanBackoffThreshold > 0 && rebalancePlanConsecutiveFailures > rebalancePlanBackoffThreshold)
            cooldown *= rebalancePlanConsecutiveFailures - rebalancePlanBackoffThreshold >= 2 ? 4 : 2;
        if (block.timestamp - lastRebalanceTs < cooldown) {
            return (false, 0, 0);
        }

        // Get scoring data via delegatecall to ScoringModule
        (bool dcOk, bytes memory dcRes) = scoringModule.delegatecall(
            abi.encodeWithSelector(COMPUTE_INPUTS_SEL)
        );
        if (!dcOk) return (false, 0, 0);

        (
            uint16[] memory apyBpsArray,
            address[] memory enabledAdapters,
            uint256[] memory targetAllocs,
            uint256 tvl,
            uint256 moved,
            uint256[] memory scores
        ) = abi.decode(dcRes, (uint16[], address[], uint256[], uint256, uint256, uint256[]));

        if (enabledAdapters.length < minAdaptersActive) return (false, 0, 0);

        // canRebalance is called via STATICCALL by LendingStrategyUpkeep.checkUpkeep
        // (view). Passing `emitOnMandate=false` guarantees no LOG* opcode executes
        // on this path, so the staticcall succeeds even when the mandate fires.
        // The CapDriftMandate event is still emitted when the plan is actually
        // prepared (checkGate path, see below).
        GasEstimator.Action[] memory actions = _candidateActions(enabledAdapters, targetAllocs, scores, tvl);
        (ok, netBenefitBps) = _fullGateCheck(
            apyBpsArray, enabledAdapters, targetAllocs, tvl, moved, false, actions
        );
        if (rebalanceGasEstimator == address(0)) movedEstimateUSDC = moved;
        else for (uint256 i; i < actions.length; ++i) movedEstimateUSDC += actions[i].amount;
    }

    /// @notice Gate check called by ScoringModule._prepareRebalanceInternal() via delegatecall.
    /// @dev    Receives pre-computed scoring data. Runs all P0-P3 checks.
    ///         `emitOnMandate=true` because this is the action path (non-view).
    ///         KEEPER_ROLE only — the sole legitimate caller is
    ///         prepareRebalance() (KEEPER-gated). Unlike canRebalance() (a
    ///         read-only STATICCALL path with emitOnMandate=false), this path
    ///         can WRITE `lastRelCapMandateTs`, so caller-supplied `tvl`/
    ///         `enabledAdapters` must not be reachable unauthenticated.
    function checkGate(
        uint16[] calldata apyBpsArray,
        address[] calldata enabledAdapters,
        uint256[] calldata targetAllocs,
        uint256 tvl,
        uint256 moved
    ) external onlyDelegateCall onlyRoleOrRevert(KEEPER_ROLE) returns (bool ok, int256 netBenefitBps) {
        return _fullGateCheck(apyBpsArray, enabledAdapters, targetAllocs, tvl, moved, true,
            _candidateActions(enabledAdapters, targetAllocs, new uint256[](enabledAdapters.length), tvl));
    }

    /// @notice True read-only preview; uses the same scoring and candidate builder as preparation.
    /// @dev Scoring's false-update path is STATICCALL-safe. No quotes are stored.
    function previewRebalanceGas() external view onlyDelegateCall
        returns (GasEstimator.Action[] memory actions, GasEstimator.Quote memory quote)
    {
        (bool ok, bytes memory data) = address(this).staticcall(abi.encodeWithSelector(COMPUTE_INPUTS_SEL));
        require(ok, "scoring-preview");
        (, address[] memory list, uint256[] memory targets, uint256 tvl,, uint256[] memory scores) =
            abi.decode(data, (uint16[], address[], uint256[], uint256, uint256, uint256[]));
        if (list.length == 0) return (new GasEstimator.Action[](0), quote);
        actions = _candidateActions(list, targets, scores, tvl);
        if (actions.length > 0 && rebalanceGasEstimator != address(0)) quote = _quote(actions, true);
    }

    /// @notice Preparation evaluates the same canonical ordered actions as execution.
    function checkCandidateGate(uint16[] calldata apys, address[] calldata list, uint256[] calldata targets,
        uint256[] calldata scores, uint256 tvl, uint256 moved)
        external onlyDelegateCall onlyRoleOrRevert(KEEPER_ROLE) returns (bool pass, int256 benefit, bool safety)
    {
        if (capDriftToleranceBps > 0 && adapterMaxExposureBps > 0 && tvl > 0)
            (safety,,,) = _checkCapDriftMandate(list, tvl);
        (pass, benefit) = _fullGateCheck(apys, list, targets, tvl, moved, true, _candidateActions(list, targets, scores, tvl));
    }

    function _quote(GasEstimator.Action[] memory actions, bool prepare) internal view returns (GasEstimator.Quote memory q) {
        uint8 batch = maxRebalanceActionsPerTx == 0 ? 2 : maxRebalanceActionsPerTx;
        try GasEstimator(rebalanceGasEstimator).estimate(address(this), actions, batch, prepare)
            returns (GasEstimator.Quote memory result) { return result; } catch { return q; }
    }

    /// @dev Validate executable funding and construct the resulting allocation.
    ///      Short liquidity, disabled venues and changed deposit flags invalidate the plan.
    function _actionTargets(address[] memory list, GasEstimator.Action[] memory actions, uint256 tvl)
        internal returns (bool valid, uint256[] memory targets, uint256 moved)
    {
        targets = new uint256[](list.length);
        for (uint256 j; j < list.length; ++j) targets[j] = positionAssets[list[j]];
        uint256 cash = ASSET.balanceOf(address(this));
        for (uint256 i; i < actions.length; ++i) {
            GasEstimator.Action memory action = actions[i];
            if (!enabled[action.adapter] || quarantined[action.adapter]) return (false, targets, moved);
            bool found;
            for (uint256 j; j < list.length; ++j) {
                if (list[j] != action.adapter) continue;
                found = true;
                if (action.deposit) {
                    if (depositsDisabled || flagged[action.adapter] || action.amount > cash) return (false, targets, moved);
                    uint256 projected = targets[j] + action.amount;
                    (bool success, bytes memory response) = allocCalcModule_addr.delegatecall(
                        abi.encodeWithSignature("validateRebalanceDeposit(address,uint256,uint256)", action.adapter, projected, tvl)
                    );
                    if (!success || response.length < 32 || !abi.decode(response, (bool))) return (false, targets, moved);
                    cash -= action.amount;
                    targets[j] = projected;
                } else {
                    if (action.amount > targets[j]) return (false, targets, moved);
                    try ILendingAdapter(action.adapter).withdrawableAssets() returns (uint256 liquid) {
                        if (action.amount > liquid) return (false, targets, moved);
                    } catch { return (false, targets, moved); }
                    targets[j] -= action.amount;
                    cash += action.amount;
                }
                moved += action.amount;
                break;
            }
            if (!found) return (false, targets, moved);
        }
        valid = actions.length > 0;
    }

    /// @notice Reprice the unexecuted suffix; sunk preparation/step costs are excluded.
    function checkRemainingPlan() external onlyDelegateCall onlyRoleOrRevert(KEEPER_ROLE) returns (bool) {
        if (rebalanceGasEstimator == address(0) || _gasPlanSafety) return true;
        (bool success, bytes memory data) = scoringModule.delegatecall(abi.encodeWithSelector(COMPUTE_INPUTS_SEL));
        if (!success) return false;
        (uint16[] memory apys, address[] memory list, uint256[] memory currentTargets, uint256 tvl,,) =
            abi.decode(data, (uint16[], address[], uint256[], uint256, uint256, uint256[]));
        uint256 count = rebalancePlanTotalActions - rebalancePlanNextAction;
        GasEstimator.Action[] memory actions = new GasEstimator.Action[](count);
        for (uint256 i; i < count; ++i) {
            uint256 at = rebalancePlanNextAction + i;
            uint256 raw = rebalancePlanAmounts[at];
            actions[i] = GasEstimator.Action(rebalancePlanAdapters[at], raw & ((1 << 255)-1), raw >> 255 == 1);
        }
        // Scores/TVL can change the selected set after preparation. Never deposit
        // into a venue excluded by the freshly recomputed target policy.
        for (uint256 i; i < actions.length; ++i) {
            if (!actions[i].deposit) continue;
            bool selected;
            for (uint256 j; j < list.length; ++j) {
                if (list[j] == actions[i].adapter && currentTargets[j] > 0) { selected = true; break; }
            }
            if (!selected) return false;
        }
        (bool valid, uint256[] memory targets, uint256 moved) = _actionTargets(list, actions, tvl);
        if (!valid) return false;
        GasEstimator.Quote memory q = _quote(actions, false);
        emit RebalanceGasEvaluated(q.actionsHash, q.costUSDC, q.l2Gas, q.posterWei, q.reliable);
        if (!q.reliable) return false;
        (bool pass, uint256 gross, int256 net) = _gateBenefitCost(apys, list, targets, tvl, moved, q.costUSDC);
        emit RebalanceEconomicsEvaluated(moved, gross, q.costUSDC, net, pass);
        return pass;
    }

    // ── Internal gate logic ─────────────────────────────────────────────

    function _fullGateCheck(
        uint16[] memory apyBpsArray,
        address[] memory enabledAdapters,
        uint256[] memory targetAllocs,
        uint256 tvl,
        uint256 moved,
        bool emitOnMandate,
        GasEstimator.Action[] memory actions
    ) internal returns (bool ok, int256 netBenefitBps) {
        if (rebalanceGasEstimator != address(0) && actions.length == 0) return (false, 0);
        // ─────────────────────────────────────────────────────────────────
        // P0.4 (2026-04-24) — Cap drift mandate bypass.
        //
        // If any enabled adapter's position exceeds the hard ceiling
        //   hardCeiling = adapterMaxExposureBps * tvl * (1e4 + capDriftToleranceBps) / 1e8
        // the gate MUST accept the rebalance plan regardless of benefit-vs-cost.
        //
        // Rationale: yield accrues continuously on-chain while TVL can shrink
        // (user withdrawals). Strict `current <= maxExp` is therefore physically
        // impossible to maintain. The protocol must auto-heal over-cap positions
        // beyond a bounded tolerance even when the move is not economically
        // justified by APY uplift alone. Below `hardCeiling` but above `maxExp`,
        // the existing `overCapRiskPremiumBps` soft-incentive continues to tilt
        // the benefit/cost calculation (see _computeOverCapProtectionBenefit).
        //
        // Trigger: any adapter over ceiling → mandate. Cheaper and more
        // conservative than an aggregated drift metric.
        //
        // `tvl` here is the total strategy TVL (idle + all positions) — same
        // denominator used by `_checkAdapterForDeploy` when computing maxExp,
        // so the ceiling is consistent with the deploy-time gate.
        //
        // `emitOnMandate` is false when this is reached via `canRebalance`,
        // which is called via STATICCALL by the Chainlink upkeep's view-only
        // `checkUpkeep`. Emitting LOG* under staticcall reverts. The event is
        // emitted only on the action path (`checkGate` → prepareRebalance).
        if (capDriftToleranceBps > 0 && adapterMaxExposureBps > 0 && tvl > 0) {
            (bool fired, address hitAdapter, uint256 hitCurr, uint256 hardCeiling) =
                _checkCapDriftMandate(enabledAdapters, tvl);
            if (fired) {
                if (emitOnMandate) {
                    emit CapDriftMandate(hitAdapter, hitCurr, hardCeiling);
                    // P0.7 (2026-06-11) — Per-adapter mandate cooldown.
                    // ONLY for non-safety adapters: safety adapters are exempt
                    // from cooldown by design (their mandate ceiling is the
                    // fallback cap, not the normal cap; if they hit it, the
                    // overflow path will naturally back off via the
                    // fbCeiling - current check).
                    if (safetyFallback[hitAdapter].absCapBps == 0) {
                        uint32 cd = mandateRedeployCooldownSeconds;
                        if (cd > 0) {
                            lastRelCapMandateTs[hitAdapter] = uint64(block.timestamp);
                            emit RelCapMandateCooldownStarted(
                                hitAdapter, uint64(block.timestamp), cd
                            );
                        }
                    }
                }
                // Mandate fired: accept plan unconditionally. netBenefitBps = 0
                // because the economic justification is protection, not yield.
                return (true, 0);
            }
        }
        // ─────────────────────────────────────────────────────────────────

        uint256 cost = estimatedGasCostUSDC > 0 ? estimatedGasCostUSDC : gasCostUSDC;
        if (rebalanceGasEstimator != address(0)) {
            bool valid;
            (valid, targetAllocs, moved) = _actionTargets(enabledAdapters, actions, tvl);
            if (!valid) return (false, 0);
            GasEstimator.Quote memory q = _quote(actions, true);
            if (emitOnMandate) emit RebalanceGasEvaluated(q.actionsHash, q.costUSDC, q.l2Gas, q.posterWei, q.reliable);
            if (!q.reliable) return (false, 0);
            cost = q.costUSDC;
        }

        // P0.3 (remediation sprint 2026-04-22): drift denominator must use the
        // re-allocatable TVL (idle + enabled positions), NOT the total TVL that
        // includes quarantined positions. Otherwise quarantine inflates the
        // denominator and a legitimate rebalance on the healthy subset gets
        // artificially blocked.
        uint256 tvlEnabled = _tvlEnabled(enabledAdapters);

        // P1: Min move BPS check — against the re-allocatable TVL, not total.
        if (moved < (uint256(rebalanceMinMoveBps) * tvlEnabled) / 1e4) return (false, 0);

        // P1: Entry hysteresis — same denominator correction.
        if (entryDriftBps > 0 && tvlEnabled > 0) {
            uint256 driftBps = (moved * 1e4) / tvlEnabled;
            if (driftBps < entryDriftBps) return (false, 0);
        }

        // P1: Absolute minimum move floor
        if (minMoveUsd > 0 && moved < minMoveUsd) return (false, 0);

        // Run benefit/cost analysis (note: the benefit/cost formula itself still
        // uses `tvl` only indirectly via weighted APY; we pass `tvlEnabled` so
        // the net-benefit-bps normalisation is consistent with the pre-check).
        uint256 grossBenefit;
        (ok, grossBenefit, netBenefitBps) = _gateBenefitCost(
            apyBpsArray, enabledAdapters, targetAllocs, tvl, moved, cost
        );
        if (emitOnMandate && rebalanceGasEstimator != address(0))
            emit RebalanceEconomicsEvaluated(moved, grossBenefit, cost, netBenefitBps, ok);
    }

    /// @dev P0.4 (2026-04-24) — scan enabled adapters for cap drift mandate.
    ///      P0.5 (2026-04-25) — extended to cover the relative cap (symmetric
    ///        with the new clamp in `_targetAllocations`).
    ///      Pure view: returns on the FIRST adapter whose `positionAssets`
    ///      exceeds either hard ceiling. The caller decides whether to emit
    ///      the `CapDriftMandate` event (keeps `canRebalance`'s STATICCALL
    ///      path safe — no LOG* opcodes under staticcall).
    ///
    ///      Conservative by design:
    ///        - Any single over-ceiling adapter fires the mandate.
    ///        - Absolute ceiling uses total `tvl` (includes quarantined) to
    ///          match `_checkAdapterForDeploy`'s maxExp computation.
    ///        - Relative ceiling uses cached external TVL (same source as
    ///          the deploy gate and `_targetAllocations` clamp).
    ///        - On rel cap hit, `hardCeiling` returned is the rel hard
    ///          ceiling for the offending adapter — useful for the event.
    function _checkCapDriftMandate(
        address[] memory enabledAdapters,
        uint256 tvl
    ) internal view returns (
        bool fired,
        address hitAdapter,
        uint256 hitCurrent,
        uint256 hardCeiling
    ) {
        // P0.7 (iter-3b 2026-06-11) — Fallback-aware mandate.
        //
        // For safety-fallback adapters, the ceiling becomes the (governance-
        // approved, elevated) fallback cap instead of the normal abs/rel cap.
        // Without this, the safety overflow path would push e.g. Aave above
        // 30% and the mandate would immediately yank it back — exactly the
        // doomed-rotation loop diagnosed in iter-3 of the backtest sweep.
        //
        // Each adapter is now scored against its OWN ceiling tier:
        //   - non-safety: absHard  = (adapterMaxExposureBps * tvl) × (1+tol)
        //                 relHard  = (dynRel * extTVL)              × (1+tol)
        //   - safety:     absHard  = (fbAbsCapBps     * tvl)        × (1+tol)
        //                 relHard  = (fbRelCapBps     * extTVL)     × (1+tol)
        //                 (rel uses fallback ONLY when fbRelCapBps > 0;
        //                  otherwise falls back to the dynamic rel band.)
        //
        // The default-return hardCeiling (when no adapter fires) is the
        // legacy NORMAL absolute hard ceiling — preserved for callers that
        // read the field on the false-path (none today, but defensive).
        uint16 normalAbsCapBps = adapterMaxExposureBps;
        uint256 normalMaxExp   = (uint256(normalAbsCapBps) * tvl) / 1e4;
        hardCeiling = (normalMaxExp * (1e4 + uint256(capDriftToleranceBps))) / 1e4;

        uint16 maxRelGov = maxRelativeExposureBps;
        uint16 tolBps    = capDriftToleranceBps;
        uint256 n = enabledAdapters.length;

        for (uint256 i = 0; i < n;) {
            address a = enabledAdapters[i];
            uint256 curr = positionAssets[a];

            // === Resolve the per-adapter ceiling tier ===
            SafetyFallback memory sf = safetyFallback[a];
            bool isSafety = (sf.absCapBps != 0);

            // (1) Absolute cap drift — fallback abs cap for safety adapters.
            uint256 absCapBpsEff = isSafety ? uint256(sf.absCapBps) : uint256(normalAbsCapBps);
            if (normalAbsCapBps > 0 && absCapBpsEff > normalAbsCapBps) absCapBpsEff = normalAbsCapBps;
            uint256 absMaxExp   = (absCapBpsEff * tvl) / 1e4;
            uint256 absHard     = (absMaxExp * (1e4 + uint256(tolBps))) / 1e4;
            if (curr > absHard) {
                return (true, a, curr, absHard);
            }

            // (2) Relative cap drift (P0.5).
            // Safety adapter with explicit fbRelCapBps > 0 uses fallback rel.
            // Safety adapter with fbRelCapBps == 0 falls back to dynamic rel
            // (the "abs-only safety" mode — uncommon but supported).
            uint256 extTVL = cachedExternalTVL[a];
            if (extTVL > 0 && curr > 0) {
                uint16 effRel;
                if (isSafety && sf.relCapBps > 0) {
                    effRel = sf.relCapBps;
                } else {
                    uint16 dynRel = _gateRelativeCapBps(extTVL);
                    effRel = (maxRelGov > 0 && maxRelGov < dynRel)
                        ? maxRelGov : dynRel;
                }
                if (effRel > 0) {
                    uint256 relCap = (uint256(effRel) * extTVL) / 1e4;
                    uint256 relHard =
                        (relCap * (1e4 + uint256(tolBps))) / 1e4;
                    if (curr > relHard) {
                        return (true, a, curr, relHard);
                    }
                }
            }

            unchecked { ++i; }
        }
        return (false, address(0), 0, hardCeiling);
    }

    /// @dev Remediation sprint P0.3 — reallocatable TVL (excludes quarantined).
    ///      Uses ASSET.balanceOf(this) for idle since idleCash() lives in a
    ///      sibling module; the storage layout is shared so the immutable
    ///      ASSET address is the same strategy-scoped USDC.
    function _tvlEnabled(address[] memory enabledAdapters) internal view returns (uint256 sum) {
        sum = ASSET.balanceOf(address(this));
        uint256 n = enabledAdapters.length;
        for (uint256 i = 0; i < n;) {
            sum += positionAssets[enabledAdapters[i]];
            unchecked { ++i; }
        }
    }

    /// @dev Benefit/cost gate with P0-P3 enhancements.
    function _gateBenefitCost(
        uint16[] memory apyBpsArray,
        address[] memory enabledAdapters,
        uint256[] memory targetAllocs,
        uint256 tvl,
        uint256 moved,
        uint256 gasCost
    ) internal view returns (bool ok, uint256 grossBenefit, int256 netBenefitBps) {
        // Calculate deltaAPY = weightedAPY(target) - weightedAPY(current)
        uint256 currWeightedAPY = 0;
        uint256 tgtWeightedAPY = 0;
        uint256 sumCurr = 0;
        uint256 sumTgt = 0;
        for (uint256 i = 0; i < enabledAdapters.length; ++i) {
            uint256 curr = positionAssets[enabledAdapters[i]];
            uint256 tgt = targetAllocs[i];
            uint256 apy = apyBpsArray[i];
            currWeightedAPY += curr * apy;
            tgtWeightedAPY += tgt * apy;
            sumCurr += curr;
            sumTgt += tgt;
        }
        if (sumCurr > 0) currWeightedAPY /= sumCurr;
        if (sumTgt > 0) tgtWeightedAPY /= sumTgt;
        if (tgtWeightedAPY > uint256(type(int256).max)) revert Overflow();
        if (currWeightedAPY > uint256(type(int256).max)) revert Overflow();

        int256 deltaAPY = int256(tgtWeightedAPY) - int256(currWeightedAPY);
        // Dynamic mode uses the executable allocation's annual USDC yield delta.
        int256 annualDelta;
        if (rebalanceGasEstimator != address(0)) {
            for (uint256 i; i < enabledAdapters.length; ++i) {
                uint256 beforeYield = positionAssets[enabledAdapters[i]] * apyBpsArray[i];
                uint256 afterYield = targetAllocs[i] * apyBpsArray[i];
                if (beforeYield > uint256(type(int256).max) || afterYield > uint256(type(int256).max)) revert Overflow();
                annualDelta += int256(afterYield) - int256(beforeYield);
            }
        }


        // P3: Regime-aware horizon (0 = use default)
        uint256 _horizon = regimeHorizonDays > 0 ? regimeHorizonDays : gateHorizonDays;

        // Gross benefit = moved × deltaAPY × horizon / (10000 × 365)
        if (rebalanceGasEstimator != address(0)) {
            if (annualDelta > 0) grossBenefit = uint256(annualDelta) * _horizon / (10000 * 365);
        } else if (deltaAPY > 0) {
            grossBenefit = (moved * uint256(deltaAPY) * _horizon) / (10000 * 365);
        }

        // === P0.1 (remediation sprint 2026-04-22) — over-cap protection benefit ===
        // When an adapter's current position is above its effective relative cap,
        // reducing that position is economically valuable even when deltaAPY <= 0,
        // because every extra day spent over-cap is a day of concentration risk.
        //
        // We model this risk cost as an annualised premium (overCapRiskPremiumBps):
        //   protection_benefit += overcap_reduction × premiumBps × horizon / (1e4 × 365)
        // where overcap_reduction is the portion of the move that actually brings
        // the position closer to the rel cap (not exceeding the remaining overcap).
        //
        // 0 = feature disabled (legacy behaviour).
        if (overCapRiskPremiumBps > 0) {
            uint256 protBenefit = _computeOverCapProtectionBenefit(
                enabledAdapters, targetAllocs, _horizon
            );
            grossBenefit += protBenefit;
        }

        if (rebalanceGasEstimator != address(0) && annualDelta < 0) {
            uint256 yieldLoss = uint256(-annualDelta) * _horizon / (10000 * 365);
            grossBenefit = grossBenefit > yieldLoss ? grossBenefit - yieldLoss : 0;
        }

        // P3: Confidence multiplier (10000 = 1x, 0 = no override)
        if (regimeConfidenceMultBps > 0 && regimeConfidenceMultBps < 10000) {
            grossBenefit = (grossBenefit * regimeConfidenceMultBps) / 10000;
        }

        // P2: Coordination penalty — reduce benefit if recently rebalanced
        if (recentRebalancePenaltyBps > 0 && recentRebalanceWindowSeconds > 0) {
            if (lastRebalanceTs > 0 && block.timestamp - lastRebalanceTs < recentRebalanceWindowSeconds) {
                grossBenefit = (grossBenefit * (10000 - recentRebalancePenaltyBps)) / 10000;
            }
        }

        // P0: Dynamic gas cost (EMA-based if available, else fixed fallback)
        uint256 _gasCost = gasCost;
        uint256 moveCost = _gasCost + (moved * (slippageBpsEstimate + withdrawalSpreadBpsEstimate)) / 1e4;

        if (grossBenefit > uint256(type(int256).max)) revert Overflow();
        if (moveCost > uint256(type(int256).max)) revert Overflow();
        if (moved > uint256(type(int256).max)) revert Overflow();

        int256 netBenefit = int256(grossBenefit) - int256(moveCost);
        if (rebalanceGasEstimator != address(0) && netBenefit <= 0) return (true, grossBenefit, 0);
        if (moved < 1) return (false, grossBenefit, 0);
        netBenefitBps = (netBenefit * 1e4) / int256(moved);

        // P1: Benefit/cost ratio minimum (0 = disabled)
        if (minBenefitCostRatioBps > 0 && moveCost > 0) {
            if (grossBenefit * 10000 < moveCost * uint256(minBenefitCostRatioBps)) {
                return (false, grossBenefit, netBenefitBps);
            }
        }

        ok = netBenefitBps >= int256(uint256(gateMinNetBenefitBps));
    }

    /// @dev Remediation sprint P0.1 — over-cap protection benefit.
    ///      For each enabled adapter where `current > relCap`, if the target
    ///      reduces the position (target < current), credit the gross benefit
    ///      with `overcap_reduction × premiumBps × horizon / (1e4 × 365)`.
    ///      `overcap_reduction` is bounded by min(current - target, current - relCap)
    ///      so maintenance moves above rel cap are NOT rewarded — only genuine
    ///      divestiture toward or beyond the cap.
    function _computeOverCapProtectionBenefit(
        address[] memory enabledAdapters,
        uint256[] memory targetAllocs,
        uint256 horizonDays
    ) internal view returns (uint256 totalBenefit) {
        uint16 premium = overCapRiskPremiumBps;
        if (premium == 0) return 0;

        uint16 maxRel = maxRelativeExposureBps;
        uint256 n = enabledAdapters.length;
        for (uint256 i = 0; i < n;) {
            address a = enabledAdapters[i];
            uint256 curr = positionAssets[a];
            uint256 tgt = targetAllocs[i];
            uint256 extTVL = cachedExternalTVL[a];
            if (extTVL == 0 || curr == 0 || tgt >= curr) {
                unchecked { ++i; }
                continue;
            }

            // Effective rel cap (governance override if tighter).
            uint16 dynRel = _gateRelativeCapBps(extTVL);
            uint16 effRel = (maxRel > 0 && maxRel < dynRel) ? maxRel : dynRel;
            if (effRel == 0) {
                // Zero-cap band → any positive current is over-cap; reduction reward
                // is bounded by the full (curr - tgt) move.
                uint256 reduction = curr - tgt;
                totalBenefit += (reduction * uint256(premium) * horizonDays) / (10000 * 365);
                unchecked { ++i; }
                continue;
            }

            uint256 relCap = (uint256(effRel) * extTVL) / 1e4;
            if (curr <= relCap) {
                unchecked { ++i; }
                continue; // not over-cap → no protection benefit
            }

            uint256 overcap = curr - relCap;
            uint256 move = curr - tgt;
            uint256 reduction = move < overcap ? move : overcap;
            if (reduction > 0) {
                totalBenefit += (reduction * uint256(premium) * horizonDays) / (10000 * 365);
            }
            unchecked { ++i; }
        }
    }

    /// @dev Delegates to StrategyConfigLib (single source of truth, shared
    ///      with StrategyStorageLayout._effectiveRelativeCapBps). Previously
    ///      an independent hand-copy of the same band table -- StrategyConfigLib
    ///      functions are `internal` (compiler-inlined, no deployed library
    ///      address), so there was never actually a delegatecall to avoid.
    function _gateRelativeCapBps(uint256 extTVL) internal pure returns (uint16) {
        return StrategyConfigLib.effectiveRelativeCapBps(extTVL);
    }
}

