        if (!(_max >= 1 && _max <= 3)) revert ParamOutOfRange(); // "range: 1-3"
        uint8 old = maxRebalanceActionsPerTx;
        maxRebalanceActionsPerTx = _max;
        emit MaxRebalanceActionsUpdated(old, _max);
    }

